window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_008"]={"n":"宋褧","dyn":"元","poems":[{"t":"座主学士虞先生眉庵诗","f":"曲","c":["厥初生人，感善孕灵。","窍骸肤发，各践乃形。","曰睹曰闻，克持克履。","效职尔劳，不具尔耻。","唯眉于面，既崇且优。","明明容观，疏爽洁脩。","頫瞰群役，靡愆靡□。","矧不羸于壮，耋亦靡□□。","捐舒泰者，喜□□□。","忧形则□，矉无矫无。","俞表里天，君□世贵。","适用我罔，或遌之有。","忽于兹我，莫敢与之。","允矣君子，顾諟斯义。","小子诗之，式告执事。"]},{"t":"日出齐化门（都城东出南头第一门）","f":"五言古诗","c":["日出齐化门，腾腾开九光。","四面启金钥，崇扉辟辉煌。","都城万井烟，沃盥整衣裳。","纳履戒车马，出入纷仓皇。","士者趋名誉，鱼佩锵琳琅。","鄙夫竞锥刀，虮子罗康庄。","大明忽西颓，所遇皆不常。","败事头抢地，得志骄昂昂。","扰攘千万情，四序恒茫茫。","□□驭天风，弭节白云乡。","左骖碧虹蜺，右驾紫凤皇。","俯视尘土海，灵台惄悲伤。","誓将九转丹，投之疗膏肓。","巍巍金银宫，境界殊清凉。","凡骨倘有缘，握手同徜徉。"]},{"t":"送魏通甫南归","f":"五言古诗","c":["魏君江海儒，孟浪游天都。","天都产功名，豪侠争奔趋。","子云老太玄，紫绶金张纡。","吾侪赤手来，抱艺将何如。","时无解貂人，太白悲穷途。","晨炊待桂玉，恶况那能祛。","凉风西北来，尘埃与之俱。","秋清气寥瑟，愁悲塞中区。","驾言欲南还，感激仍踌躇。","岂不愿君留，潜珍俟须臾。","江南垂白亲，日夕恒倚闾。","袖中出毛檄，入室聊欢娱。","斗食勿羞薄，再举冲天衢。"]},{"t":"雪寒书事廿六韵（延祐己未在乐亭县作）","f":"五言古诗","c":["幽云敷层霄，狂吹趣阴霰。","氛霾互黤黮，雨雪事交战。","弥空始糁屑，降地旋削片。","斯须万汇失，顷刻九有遍。","霏霏集颓堞，皓皓被遐甸。","危峰冒周圭，广陌曳齐练。","崇陵受委积，枯蘖容挂罥。","况缟未足多，拟絮差可善。","通逵骇连璐，块壤讶垂瑱。","阶平恶漫没，谷□□□□。","□□烦褰箔，烛幌助披卷。","气清华盖爽，光烂银海眩。","太素靡污垢，至朴谢雕瑑。","人踪绝往反，野色一更变。","积阴若胶轕，祁寒病增羡。","晨衣袭狐貉，夜席益莞荐。","衾重初昏寝，薪湿停午膳。","严威折纩绵，冻璺裂盎甗。","发森惮去笠，指直愁结袸。","凌坚莱芜釜，澌瑩歙溪砚。","羁人畜怨憾，狩将坐畏愞。","虎士跗趾瘃，马走牙齿颤。","罢氓归禁㾕，陋邑矧饥荐。","屋润仅自侈，室匮畴与唁。","穷荒觊吹律，凝冱需见睍。","挥翰书自繁，敢以古雅衒。"]},{"t":"送项鍊师还天台","f":"五言古诗","c":["海岸山岧峣，飞霞凌紫霄。","中栖鍊形子，绿发颜不凋。","漆点双瞳人，神授养生诀。","暮乘赤城风，晨谒玉京阙。","振迅鹤氅净，翱翔凫舄轻。","金丹自爱惜，绿酒陶性情。","我惭尘土姿，解后方外友。","忘形时一见，谈屑纷在口。","今朝闻还山，惜别令人嗟。","相思欲相见，难访碧桃花。"]},{"t":"松涛斋","f":"五言律诗","c":["华省树飂飂，繁声发中宵。","讵非漆园籁，谓是广陵潮。","羽葆荡流月，凤吹激商飙。","永言托栖息，听此涤烦嚣。"]},{"t":"中秋陪谢敬德修撰达兼善典签诚夫兄学士会饮周子嘉如舟亭交命险韵十二依次诗得赏字","f":"五言古诗","c":["秋川澄荇藻，凉樾坠栗橡。","雅集融酒尊，缓步阮屐緉。","华构故依岸，危栏欲飘㼽。","夕斋涤烦嚣，时清侈欢赏。","寒光揭宝鉴，灏气凝铜掌。","翔翾仙蜕骨，鼓舞儿释襁。","初窥祇开轩，久眺还倚杖。","林鸟惊倦翼，莎蛬荐哀响。","缅怀谷之盘，未卜川若辋。","典签雄朔客，太史诧川党。","交觥罚如雠，探策心遽驵。","主人画舫斋，坐客龙虎榜。"]},{"t":"群玉司崔元方琅然亭","f":"五言律诗","c":["幽人虚白室，理琴恒自怡。","声兼碧玉调，弦是水晶丝。","凉飙动脩樾，皓月涵清池。","至音一入耳，四座无邪思。"]},{"t":"送李溉之得请还济南","f":"五言古诗","c":["髫龀客江汉，早闻高士名。","君居玉沙县，我在渚宫城。","弱小知慕君，不得觌君面。","道路播词章，庸俗矜俊彦。","骐骥厌庭户，鸾凤悲草莱。","英标出世表，去去黄金台。","风尘绮陌深，烟雾玉堂窅。","浩歌香炉峰，巢云寄木杪。","朝辞九华顶，暮宿黄鹤楼。","纶巾紫凤褐，欲去仍或留。","朅来重翱翔，五十霜鬓秋。","瀛洲列群仙，蓬山撷兰芷。","一登銮坡峻，再陟阿阁崇。","牙符杂珂佩，通籍金闺中。","谒帝兴圣宫，回车历城道。","矫首凌天风，振衣下瑶岛。","东望华不注，烟霞齐鲁郊。","言归理松楸，啸傲依堂坳。","缅想共君游，不得恒聚首。","叩首屡投刺，尘鞅阻文酒。","雨濯野山色，晴飞溪柳花。","明发遂长往，怜君离思赊。","云汉耀奎文，长庚丽其下。","天书行召还，岂是栖栖者。"]},{"t":"浚州李氏一门娣姒四人贞节","f":"五言律诗","c":["玉树摧秋霜，穗帐悲夜凉。","松柏争厉操，兰蕙俱流芳。","悽楚仅一子，仪刑自见亡。","共嗟怨毒苦，不知年命长。"]},{"t":"和王师鲁哭子诗廿七韵","f":"五言古诗","c":["我识王内翰，早岁赋美质。","筮仕困州县，处友固胶漆。","摛辞若纂组，粲烂锦城匹。","福善宜裕后，酬劳当任逸。","苍天不可问，得子旋伤失。","君怀未能慰，我恨亦云积。","孟春丧孩女，仍唁仆与侄。","阿申并官奴，两儿众所惜。","方期及髫龀，入学相诱掖。","亭亭芝芳妍，温温玉缜栗。","随行操几杖，或可弄文笔。","一以世科第，一以嗣臧获。","云胡俱夭折，相去不百日。","孩女不甚痛，长不恃其力。","初疾忍辄弃，命医恒接迹。","终焉莫救药，枉负不慈责。","娟娟竞秀爽，眉目犹在觌。","伤心掷絪褓，尘泥污红碧。","父哀犹强饭，母悼不安席。","适值吕太史，为我亦傍泣。","渠子岁三丧，鹓邹劳卵翼。","尤嗟中殇女，絺绣已能刺。","吾儿幸存二，怀抱若可释。","疲劣不好学，稍令诵内则。","君诚旷达士，悲泪莫频滴。","祷神名山颠，置妾居侧室。","伫作汤饼会，人醉酒一石。"]},{"t":"送张孟功扬州觐省分题得游丝","f":"五言律诗","c":["东郭畅景韶，飞丝荡晴朝。","细逐柳绵度，狂随薰风飘。","燕郊萦去策，楚岸罥征桡。","嗟予顾不及，相送共迢遥。"]},{"t":"江阳毛定甫天光云影阁","f":"五言律诗","c":["伊人结小隐，凿沼若一镜。","澄波涵至明，穹昊入俯映。","初缘适幽情，乃谓契善性。","考亭或神游，可让不可竞。"]},{"t":"江东胡士恭嘉树轩","f":"五言律诗","c":["野人爱嘉树，题作幽轩名。","顾岂樗栎散，愿怀松柏贞。","深沈永夏景，萧飒繁秋声。","纷纷事游冶，啧啧争春荣。"]},{"t":"王君冕关中别墅芳润亭寄题二十韵","f":"五言古诗","c":["雍壤第上上，土厚风气温。","水泉引甘泽，卉木滋以蕃。","兴王作都会，山川郁屏藩。","维周秦汉唐，陈迹犹具存。","一览以娱目，矧此长子孙。","胜境遇名士，相值复何言。","王君长安人，负郭有田园。","蓝田在其左，终南高且尊。","平川豁瞻眺，崇冈如吐吞。","结搆事幽隐，池台閟重垣。","植木春茂茂，酾酒夏沄沄。","晴花炫屋角，秋苔黯墙根。","岚翠浥图籍，柯叶荫壶尊。","觞咏协时序，起居适寒暄。","生涯付子弟，供具有鸡豚。","好客时过从，租吏不叩门。","谈评极宇宙，息偃度朝昏。","缅怀鹤在阴，大笑虱处裈。","茫然圭组念，邈矣车马喧。","兹亭可适意，馀事勿复论。"]},{"t":"早发安平（录囚襄阳）","f":"五言古诗","c":["露华沐脩丛，凉思浩可掬。","阳光炫遥川，热念汹相续。","驾言省民瘼，行行涉岩谷。","呶呶纷听讼，亹亹廑问俗。","伤哉无知氓，误向宪网触。","伏辜痛呼謈，冤者说拲梏。","于时嗟稍旱，禾黍未丰缛。","愧无雨随车，润泽溥川陆。","皇灵赫临照，恒负伐檀恧。","虽非于公仁，敢效俊臣酷。"]},{"t":"山北宪佥丁文苑挽诗（乙夘科哈必齐也）","f":"五言律诗","c":["使君气凌云，学剑喜论文。","生材拔其萃，立事张吾军。","奕叶擢高第，甘棠荫孤坟。","九京不可作，顽懦徒纷纭。"]},{"t":"送太原房淳德赴上长芦校官廿四韵","f":"五言古诗","c":["曩岁在甲子，我忝登桂籍。","君从河东来，劘垒肆健笔。","相识稠人中，神胜须发黑。","河汾孕灵秀，翛然涧松柏。","文章岂优劣，方晷判得失。","时运或少乖，战艺不幸北。","乾龙飞九五，湛恩逮点额。","受职固匪轻，笑捧告身敕。","音问久寥邈，再遇京尘陌。","或荐诸太常，借径簿领役。","礼文熟讨论，固岂刀笔术。","鹾司巍学宫，俨在漳水侧。","横经属老成，弟子拜讲席。","广文莫厌冷，师道贵名实。","宦业堕素餐，吾党有愧色。","育材登廷珍，计功倍千百。","拿舟载妻子，携书去王国。","别酒借颜红，春衣点头白。","尚忆韩与许，当时同少诎。","士宗掾柏台，才气森崒嵂。","辉卿莎塞下，幕府著劳绩。","小大无弃捐，朝家礼罗密。","贤路辟榛芜，异才应间出。","文运岂偶然，因君重太息。"]},{"t":"苏伯脩湖广行省参政分题赋诗送行得洞庭波","f":"五言古诗","c":["秋风木叶下，送目人千里。","汹涌趋东陵，潏荡混南纪。","天垂俱沈浮，霜落乃清泚。","蛟龙怒未平，舟楫漫难理。","苍梧云气连，笙竹矶石磊。","所恨碍君山，仍嗟愁帝子。","予怀渺不极，客思浩然起。","愿令沅湘波，安流入江水。"]},{"t":"礼部侍郎台哈布哈兼善出守会稽分题送行得读书堆","f":"五言古诗","c":["昔贤居海陬，幽潜有遗址。","简编不复存，培塿尚堪指。","三年不窥园，西京称董子。","蓬蒿绕宅生，仲蔚号高士。","为学贵处静，业成尚致理。","用行舍则藏，训诂殆卑猥。","黄门任大同，朱墨订文字。","虽非注鱼虾，乃尔汇虎豕。","夫君系贵族，缀缉浙江涘。","弱冠登巍科，禁省久历履。","今此乃作守，出处将肖彼。","掉策国东行，去志疾若矢。","南州欲访古，不惮纡道里。","遥知郡政暇，闭阁究经史。","仕学能两优，岂直野王止。","来慕子所歌，亦复懦可起。"]},{"t":"草虫图（蝗螽斯螳螂蟋蟀图国子生求跋）","f":"五言律诗","c":["群虫居草间，翾动各有趣。","或为人所怜，或为人所恶。","怜恶我岂偏，彼乃自致然。","披图付一哂，不足汨吾天。"]},{"t":"送高丽进士李仁复东分题得箕子庙","f":"五言古诗","c":["皇矣锡畴衍，已焉鼓琴悲。","列封出异代，主教开东陲。","道义三仁称，德泽万世思。","遗像俨圭衮，巍宫肃笾彝。","頫临帻沟溇，奔走高句骊。","宇宙相终穷，肸蚃无已时。","之子诵经籍，宾兴膺爵縻。","龙光粲冠裳，鹿鸣奏歌诗。","眷此承帝恩，实由文化施。","归与下车拜，报称恒念兹。"]},{"t":"题道者山（多尔济国王）","f":"五言古诗","c":["元气肇融结，律兀蟠厚坤。","蓬瀛诧虚无，五岳名号尊。","兹山介平营，特与太古存。","碣石拱其侧，水岩何足论。","东北医巫闾，罗列为弟昆。","境迥称曕晀，多景移晨昏。","烟霏杂草树，海气时吐吞。","幽深閟灵怪，胜丽难具言。","谓宜栖隐沦，秋鹤仍春猿。","丛桂赋骚雅，萝薜相婵媛。","顾此缁衣流，结构开祗园。","陈迹纷惚恍，纪载探本原。","属问贤侯王，游观驻朱轩。","从行乐觞咏，风日摇旌幡。","我昔延祐末，东迈窥其籓。","望望不得登，予怀未能谖。","于时秋雨霁，仰羡思攀援。","谁为持此意，洒翰题空门。"]},{"t":"送多尔济班监宪淮东分题赋诗得丰乐亭","f":"五言古诗","c":["丰山既足玩，丰岁仍可喜。","太守为筑亭，日日饮涤水。","幽谷环轩楹，泉石列阶戺。","蔼蔼禾稼盛，皞皞风俗美。","政平共觞咏，民安事田里。","摛辞述佳致，行乐遗旧址。","使君出贵裔，读书精治理。","帝命徂淮南，持节长风纪。","是州处行部，西望才尺咫。","今兹罹旱暵，郡邑多苦馁。","衣食赖贤明，庶免沟壑死。","先忧回天心，相业由此始。"]},{"t":"送王德常南台御史分题赋诗得朱雀桥","f":"五言古诗","c":["秣陵古都会，秦淮实壮哉。","长波护巨镇，危桥横曲隈。","华桁何伟丽，赤阑亦萦回。","世称题柱石，人是济川才。","泛鹢堪屡往，乘骢经几回。","当时王谢宅，燕子喜重来。"]},{"t":"荥阳赵孝子（名璧字君璋）","f":"五言古诗","c":["孝乃百行本，亲有罔极恩。","亲恩何以报，持报百身论。","事生或能尽，事亡鲜如存。","赵君性诚笃，能窥曾闵籓。","亲癠拜医师，既葬庐墓垣。","身与木石居，泪零松柏原。","动息抚遗体，哀痛伤心魂。","读礼已无愧，抱恨终弗谖。","过车式而敬，朝命表宅门。","大哉永锡类，浇风庶能敦。"]},{"t":"节妇刘氏（刘氏阳曲民家女早嫁西杜王舜卿生子甫一岁王远游越十年不归刘氏奉舅姑惟谨无怨言子年十四闻父留滦京往拜焉至则他娶矣刘若不闻日勉其子以学又十年王始归浃日而复去竟死滦水上刘自奋艰厄中以保其家以成其子有司上其事旌其门子名思义刘年七十馀）","f":"五言律诗","c":["生世苦不谐，愈甚太常属。","藁砧任飘荡，宁馨堪抚育。","生无织锦诗，死有崩城哭。","愁云散晋溪，华表照阳曲。"]},{"t":"送汪臣良编修出知馀姚州题得石鼓","f":"五言古诗","c":["繄昔中兴王，振武岐阳蒐。","臣工作歌诗，纪迹庸阐幽。","琢石制为鼓，深刻将垂休。","浑坚不少磷，文字粲以周。","古拙出史籀，蟠错纷蛟虬。","毡驼护转徙，逮阅三千秋。","天朝尤宝惜，移寘宫墙陬。","栖息得所托，珍秘价莫酬。","刺史瑚琏器，出守趋东瓯。","敦朴且贵重，华采殆罕俦。","旌麾暂补外，廊庙行见收。","亦若此鼓然，置之昆崙丘。"]},{"t":"胡震亨家庆堂","f":"曲","c":["三釜及具庆，庭闱有馀欢。","易贵不家食，禄养心始安。","东邻供滫?，西人盛盘餐。","酒旨肴亦嘉，素身兴永叹。","君子奋逢掖，牙绯效王官。","作堂娱二亲，上寿罗芝兰。","养志既可尚，扬名良独难。","锡类动里闬，美誉期不刊。"]},{"t":"凉夜吟（十五岁作）","f":"七言古诗","c":["云头金玦秋意生，城南啼乌三四声。","漙漙斜露铜铺湿，阑下幽花香气清。","倡楼迢遰咽凝管，波底老龙求子鸣。","萧萧竹树小山雨，惊觉佳人梦中语。","湿萤寥落阶莎寒，拂拭桃笙掩闺户。"]},{"t":"朝元宫白牡丹（延祐丙辰在汴作）","f":"七言古诗","c":["瑶圃廓落昆崙高，霓旌豹节凌旋飙。","东门偷种来尘嚣，开云镂月百千瓣。","雪痕冰璺辞锼雕，重台复榭玉版臼。","湿露拥出青霞娇，琼娥爱春受春足。","香腴酥腻愁风消，人间洛阳红紫妖。","紫霞滟滟吹秦箫，青鸾望极何当招。"]},{"t":"岳阳楼","f":"七言律诗","c":["热云滃滃东风死，东方春来著兰芷。","画栏十二君山青，北渚南汀碍眸子。","苍茫杳霭一千里，鬼诞仙妖似湖水。","纤阿浴菟出西涯，飞上南翁棹歌里。"]},{"t":"遗芳蔓","f":"七言古诗","c":["龟屏象簟尘凝辉，桂枝落尽秋气悽。","琼瑶台上魂是非，孤鸾照影心含悲。","离宫别馆春茫茫，延凉殿上空情伤。","却凭钟火一茎草，换得蘅芜三月香。","兰风蕙露怨娇尽，落叶哀蝉□鸣嘶。","嘤嘤呓语谁得知，再取玉篸搔素丝。"]},{"t":"五月寒（延祐丙辰夏江南久雨甚寒）","f":"七言古诗","c":["朱明避事秋万里，葛溽罗塺索裘绮。","赤帝藏龙天漏水，白鸟苍蝇冻缩觜。","五月雨声长在耳，有虞皇帝拂瑶徽，湿透檿丝弹不起。","招摇下望白玉京，朝天苍佩寒无晶。","马毛拳猬坊门闭，閒却金盘不赐冰。"]},{"t":"洗车雨（每七夕有雨俗谓天帝为织女洗车）","f":"七言古诗","c":["一从去岁闲油壁，尘暗香軿有谁拭。","琼娥玉媵莫迟回，为我飞书呼轸毕。","雄雷雌电倾河来，宝轮濯濯无纤埃。","桂香陌上不泥泞，虚无指点回蓬莱。","乌桥银浦沾濡彻，凤靷鸾鞭洁如雪。","犹恐黄姑净病深，更擘湿云填古辙。"]},{"t":"北中寒","f":"曲","c":["烛龙吹冷玄冥唾，鸡子庖从沙□过。","羲和呵手驭日车，噤㾕阳乌三足堕。","骊山温泉彻底冰，白地裂文如旱塍。","穷阴冻合黄钟琯，缇室葭灰不得升。","射麋将军守毡屋，霜结虬须悬䍡?。","琵琶弦折酒成澌，风刀劙破双颧肉。"]},{"t":"荣华乐","f":"曲","c":["大明飞光白玉堂，花楼网户腾春香。","鸣钟馔玉云母床，堂堂夫婿侍中郎。","青云捧车谒汉皇，公卿夹毂趋道傍。","董贤朝朝眠未央，将军夜穿蹋鞠场。","柏梁置酒诗成章，黄金驷马来徜徉。","起山引泉大宅张，兰汤洒壁鸣笙簧。","女娥?窱声绕梁，回风飞雪衣飘飏。","芳年华月温柔乡，流苏斗帐垂珠珰。","红麸麝枕辟凶殃，紫金钗梁悬凤皇。","阶前七十二鸳鸯，绮襜罗列生辉光。","平头奴子跽擎觞，酒酣调笑邯郸倡。","腰横半解金蛇黄，玉池芙蓉帘外霜。","□符如火□□黄，门开将趋宫漏长。","扶来丹地拜天子，愿沐鸿休亘终始。"]},{"t":"同年程时叔内翰还浙东","f":"七言古诗","c":["玉堂松柏高萧森，老子时时庄舄吟。","久矣京衢厌尘土，兹焉海浦觅园林。","西清供事有佳兴，南浦独返无留心。","著书藏稿名山远，读易探蓍理窟深。","春流沄沄败冰暖，昼日曀曀高天阴。","离情竟作一发箭，交道终期百鍊金。","众宾怀抱付杯酒，二子德色堕衣襟。","人生会合有天命，□□□□□商参。"]},{"t":"张武定战死西南夷","f":"七言律诗","c":["邛竹蒟酱启边衅，犀甲吴戈成国殇。","风悲战鼓惨欲死，日曀战云寒不光。","黩武可怜弃躯命，讨罪宜用施威强。","内符近遣滇海将，传说英声皆激昂。"]},{"t":"赵存诚除曲江县尹将上枉道还长沙为乃父平远公焚黄","f":"七言古诗","c":["曲江大夫故家子，白发萧骚辞帝里。","官居岭表不即上，路指湘中有馀喜。","乃翁勋业闻紫庭，手捧芝书新易名。","祥光一夕照宰木，芳衔千古荣佳城。","椎牛上冢欢声重，石兽无情亦飞动。","莫怨神道少丰碑，闻说新除好祖奉。"]},{"t":"九日再会饮如舟亭分韵得异字约赋廿句","f":"七言古诗","c":["周郎家本住武溪，入京暂作公府吏。","闭门哦诗常抚卷，倒屣迎宾能好事。","今年中秋偶晴明，好友持杯恰三四。","时当九日复宴集，潇洒轩楹临水次。","槛华错粲邻舍移，壶酝氤氲内官赐。","天高气清萸菊节，攘袂奋发湖海士。","风尘悠悠渺芳躅，觞咏兰亭或堪似。","人生行乐适意尔，局促辕驹老将至。","酣歌慷慨时自新，放达何须较愚智。","愧无硬语出磊磈，追逐卢仝并马异。"]},{"t":"永丰曾明善秀才挽诗","f":"曲","c":["三十未有二十强，清门士子堪悲伤。","读书矻矻穷昼夜，弄笔往往多篇章。","世人谩歌蒿里曲，地下应作修文郎。","君不见江城南有客不识字，华缨紫绶须如霜。"]},{"t":"宇文子诚出掾河南行省二十韵","f":"七言古诗","c":["至顺元年十月初，故人舍我将南徙。","君喜迎亲去志速，我惨送君离思起。","西山雪小阳乌逝，北口风高乔木死。","吉贝衣消京国尘，木兰舟溯漳河水。","夷门旧交兄弟若，吴房老父咫尺尔。","人生百年贵适意，戚促何须羡金紫。","忆我前年在滦阳，千里兵尘四郊垒。","妻子哀号不得见，乘驼归来溷悲喜。","彤庭捧牍负长材，乌府珥笔存旧履。","磊落不作风尘态，宇宙茫茫少知己。","与君同朝三四年，清苦何尝设醪醴。","岁时相见徒劳问，我尔俱贫情曷已。","江陵古城多北客，我昔与君共闾里。","君年三十入公府，我发漆黑政童子。","迩来踪迹各星散，南北东西困泥滓。","王城会面忽惊电，君踰知命我强仕。","微躯潦倒属名缰，半世萧条鲜生理。","重内轻外古所云，愧我谋身敢如此。","鸠巢未葺政坐拙，菟裘将营何所指。","因君之行重太息，搔首苍茫对斜晷。"]},{"t":"送周子嘉由长秋寺令史出为滁之来安簿暂回武陵觐省二十五韵","f":"七言古诗","c":["周郎十五二十时，皎如玉树阶庭芝。","出门掉臂不揖客，操觚作赋犹从师。","龙驹未腾掣电足，松羔早挺凌霜姿。","自怜渠侬似明镜，目我伧父为钝椎。","论文忽经十寒暑，聚首遂作双埙篪。","君留我别迹相远，离群索居情不怡。","流萍适楚复南迈，行李趋燕同北驰。","桑弧蓬矢负夙志，爷娘妻子成远离。","黄鹤楼前暑云徂，文明门内秋为期。","风尘南陌困英锐，痴僮羸马淹孤羁。","太学诸生曳青衿，长秋小史称白眉。","延春阁下昼脩牍，崇恩寺中朝侍祠。","往来滦京堂适庭，召集阍寺铁就磁。","出祖春醉葡萄馆，劳还秋宴白莲池。","词林旧交赏清俊，公府馀暇陪遨嬉。","河滨亭子九日酒，座中华笔十韵诗。","吏役免谴获书满，选曹拟官惟据资。","米珠薪桂脱艰阻，青袍文笏将设施。","快如海鹏始奋翼，逸如天马初释羁。","亲庭何劳赋陟岵，子舍那复歌扊扅。","祗知定省当汲汲，奚较赴上犹迟迟。","华裾綷䌨别良久，大艑峨岢载小姬。","策名仕版副君愿，赋诗河梁劳我思。","长安落叶路不见，洞庭寒波风乱吹。","若到来安将举职，莫忘武陵初解维。"]},{"t":"欧阳原功由艺文少监谒告归浏阳","f":"七言古诗","c":["七年不见荼蘼花，湘南学士思还家。","卖马径出艺文监，买船便赴潞河沙。","始随徵书官璧水，北门风月清谈尔。","兵尘荏苒居庸关，襆被萧条教忠里。","奎章阁上进成书，九重知是尹芜湖。","腰带黄金佩苍玉，玉卮赐酒榻前趋。","君恩如海谁能报，回首乡关动怀抱。","尚平昏嫁几时毕，陶令田园何日到。","槐舒菟目柳如绵，浩然归兴南风前。","闺人含笑仆夫喜，那顾悲欢各异缘。","西山过雨离筵晓，川途万里云缭绕。","里闬逢迎樽俎欢，都城会合簪缨少。"]},{"t":"徐延寿母张节孝（时徐将赴顺德任县尹）","f":"七言古诗","c":["良人旅榇藏故乡，襁中孤儿佩铜章。","善事尊章不归宁，藁砧泉下无遗恨，棹楔门前有耿光。"]},{"t":"庐江县尹俞器之妻罗恭人节行（罗汉臣学士之女）","f":"七言律诗","c":["庐江生前事箴组，庐江身后主门户。","疾时和药死庐墓，刲肌断发事可举。","庐江无子谁与处，鸾诰腾光照乡土。","共怜令尹得贞妻，不道翰林生淑女。"]},{"t":"金陈州同知孙德政妻高氏贞节（一子名润孙五人高氏卒年八十八）","f":"七言律诗","c":["三十良人如冠玉，领兵当关死不复。","燕赵年饥盗贼窟，携儿避难聚衰族。","鸾镜尘昏忘膏沐，含饴弄孙备五福。","巍巍双桓表门屋，杞妻谩作崩城哭。"]},{"t":"潘阳胡茂卿善馀堂（茂卿尝作此堂奉其父叔嘉今年七十子五人）","f":"七言律诗","c":["老人种善如种田，三世力耕无歉年。","贤为镃基义为耒，芝兰玉树嘉禾然。","菑畬有术谁能传，沃不以粪激匪泉。","井底白金五千两，瓮中青钱三百缗。"]},{"t":"庆元叶谦甫挽诗","f":"七言古诗","c":["维南一士美如玉，怀才制行遁空谷。","子孙诜诜宜厚福，青衿十年易章服。","翔凤原头可瞑目。"]},{"t":"苏伯脩右司滋溪书堂","f":"七言古诗","c":["滋溪溪水清如玉，堂中藏书高似屋。","缃缥装潢芸叶馥，远过李侯三万轴。","上世遗安重教督，有美令孙克佩服。","移书庋几置书腹，用之经济且启沃。","尊经缵史雅志笃，屈宋衙官骚则仆。","堂前山水秀且绿，堂中之书兹不辱。","愧我四十鬓欲秃，文学事功俱鹿鹿。","悲欢枯落悔不足，欲登君堂借书读。"]},{"t":"行路叹书利阳驿壁","f":"曲","c":["冬雨扑面朝不寒，驱马驰逐荆门山。","麦陇高平稻塍直，竹树鸡豚山两间。","少年笔砚为生理，耕得虚名才半纸。","道逢良田胜境如，曲车老我流涎何日止。"]},{"t":"李时进佥宪持其考君墓表求诗（受封襄垣县男）","f":"曲","c":["襄垣老人志不群，教子岌岌兴高门。","燕山谏议有阴德，陈氏省华多子孙。","少年孤贫嗟素身，策名仕版期后昆。","报施之道昭而神，蓍布爻象龟灼文。","老人种善如种树，老人视财如视土。","紫衣綵衣事尊俎，恩封乡县爵第五。","七帙告终既寿考，螭首龟趺贲泉户。","君不见草间无闻乱冢何足数，却是当时守钱虏。"]},{"t":"赵侯发白返黑（后卫千户致仕年八十八吏前卫时王千户杀西相至今能谈其事）","f":"曲","c":["日中则必昃，百川东之不西流。","将军须发白返黑，身强能使元气周。","禁军前卫皆从事，少壮驰驱老来贵。","幕中文字羽檄飞，腰间符节龙章佩。","功成名遂乐天年，矍铄何须羡马援。","述旧能谈铁锤将，弈棋常对烂柯仙。","只今行年垂九十，鬓变青丝发点漆。","高堂明镜莫空悲，学取将军养生术。"]},{"t":"中兴万户爱假山筑亭号粹峰亭","f":"曲","c":["元戎生长太平世，雨甲苔枪日无事。","筑亭排石示燕閒，比似南塘更清致。","烟霏晻霭群峰峦，莎阴藓璺相回环。","天台庐阜入胸次，华阳艮岳非尘寰。","米狂呼兄名不朽，千古高情能尚友。","我知主人爱山符节然，传付子孙俱世守。"]},{"t":"柴舜元玄云石","f":"七言古诗","c":["重阴蔽天浓似墨，疾风碎剪不盈尺。","累累霭霭乱抛掷，肖像凝神作奇石。","松窗竹坞玉立之，仙雾为幄烟为衣。","米狂拜罢捉不住，清润一卷愁欲飞。","长安才子惜如宝，袖中携置夷门道。","当时不见万态峰，只今空望三山岛。"]},{"t":"吉安刘楚奇秘书浮云道院","f":"曲","c":["桑弧蓬矢男子志，溟鲲鼓鬣鹏张翅。","揭天勋业固垂名，择地园林须适意。","夫君家住白鹭洲，先世田庐不外求。","宗亲同居三百岁，卉木素封千户侯。","桃花源里山川丽，辋口庄前亭馆邃。","儿孙祗解弦诵声，泉石更无尘土气。","迩来矫首蓬莱山，凌风珂佩声珊珊。","萧然三径兀自若，梦寐衡门时往还。","贤豪心事人不识，进退卷舒那可必。","君不见太平宰相三十馀，千驷万钟成弃掷。"]},{"t":"太白酒楼（延祐己未初自江南还京途经济州所作）","f":"曲","c":["我昔在髫年，知有谪仙人。","少壮读所作，天才气凌云。","浔阳紫极宫，往岁闻佳句。","采石青山头，前月拜荒墓。","夜宿檐下云，秋弄江上月。","何如任城楼，狂饮兴豪发。","况有任城宰，具酒复知音。","酒酣隘八极，世事徒骎骎。","内子香闺梦，伯禽娇且啼。","人间火宅谩煎逼，政是玉山倾倒时。","散披紫绮裘，倒著白接䍦。","银台金马直一唾，方瀛绛阙行将去。","仙之酒杯失，遗基楼观雄。","垣表暗题咏，石榴海柏森西东。","谪仙人，今何在，汶水凫山黯苍霭。","手挥玉鞭骑玉鲸，应在浮云九州外。","仙人魂魄茫氛氲，望之不见矧可亲。","明朝我至玉京去，愿谒蓬仙贺季真。"]},{"t":"三五七言（乐亭县作）","f":"曲","c":["寒空高，寒雁号。","霜气严征柝，风威薄锦袍。","一夜相思心似海，荒城四望愈忉忉。"]},{"t":"尘泥叹（至元元年乙亥七月久雨后）","f":"曲","c":["经涂九轨壮王国，岐蹊委巷错综若纬织。","僵车石马匹亿，旦旦躏轹，化作深土深数尺。","污人衣冠，垢人发肤，飘簸荡穿入牖渍。","几席令人生憎，心内热气郁悒。","丰隆裂缺怒赫赫，天雨下土痛濯涤。","涨空埃壒净无迹，洒然顿觉醒胸臆。","谁谓满天霖霪数十日，尘固无复作祟，泥淖乃尔亦可疾。","舆陷三十辐，骄马至不能援其膝。","壮夫徒行循墙仅彳亍，弱妇孱子悉鱼贯困踬。","七月中气处暑毕，阴云未彻霁未必。","小夫贱隶又恐风高日出尘复作，辗转皇惑计无所出。","我为呼天敕鬼工，运甓或伐石。","甃叠平安妥，泥少尘亦息。"]},{"t":"送翰林编脩成谊叔驿召鲁子翚学士于邓遂便觐省成由国子生乡举于大都至顺四年登科今始得归乡里","f":"曲","c":["盛时寰区奠金瓯，四方才子纷来游。","郭隗台荒登不得，李膺门下久难留。","南阳年少诣阙下，气如雕鹗文如彪。","长松耸壑被斲削，大玉作器辞雕■。","既不能上书谒宰相，又不能投刺干王侯。","独抱获麟经，信如渭滨钩。","鼓箧桥门不盈岁，夺标桂苑仅经秋。","挽彊一中杨叶远，不识楚人三刖愁。","落落拾地芥，肯贻乡邦羞。","铮铮破天荒，乃在帝王州。","泥金帖子附家信，上报里中父老惊倒同门俦。","玉堂载笔事方始，北堂戏彩心难酬。","书藏石室报天子，遂我拜母三年谋。","蓟门一昔归心起，梦里阿㜷惊且喜。","驿楼佳树拂狨鞯，词馆新篇盈茧纸。","家园风景有如此，关吏欢迎弃繻子。","疾趋慈梱笑称觞，次谒乡贤忙倒屣。","浮云暂蔽奎躔尔，须信斯文难坠地。","招邀郊薮凤麟来，菊花潭上从君始。","西南归路平如砥，太行山色青如洗。","我幸君归且怨别，心逐太行山色，送君直过黄河水。"]},{"t":"奎章阁学士院照磨林彦广代祀岳镇海渎以诗送之","f":"曲","c":["天子代天理万物，辅相治明神治幽。","赞佐化育两交尽，始得物无疵疠年有秋。","神有狸沈牲币封爵位号祈报古典礼，人则公侯卿相秩禄宠数尊且优。","庙堂燮理未始有乖戾无乃神失职，遂使燕赵旱暵吴越饿莩盈田畴。","九重宵旰念民命，慎简清直乘轩輶。","分诣诸神祠焚玉，尘坌驰突不少留。","恒岳奠畿辅，济渎河内为上流。","矫首东南行，径指会稽秦望游。","衣冠粲庭陛，珂佩锵琳璆。","椒浆桂酒感肸蚃，竹笾木豆罗脯鱐。","焚香早致辞，盥手屡叩头。","润泽善利责望水兴云作雨嘑噏，燥湿申命林麓原隰诸林丘。","我知山灵川后今岁效职致丰稔，不负天子圣虑贻我使者羞。"]},{"t":"追和何谢铜雀台妓","f":"五言律诗","c":["寒露泫丘草，悲风漳水声。","黄肠定何许，歌吹徒营营。","穗帐守明月，佳人情不胜。","眠中不得近，痴绝望西陵。"]},{"t":"秋弦怨","f":"曲","c":["海风吹凉薄璇宇，桂压钩栏秋作主。","银湾凝月澹游溶，云彩粼粼鶱凤羽。","玉帐悬沙塞梦寒，沙泪啼秋山迸泉。","哀蛬不解论心素，金字空侯挑夜弦。","大漠沙如云，去京三万里。","弦声隔秦城，无路入君耳。","七星西横露漫漫，金刀剪衣丁夜眠。","他日赐金高似屋，嫖姚应是□婵媛。"]},{"t":"汉宫怨","f":"曲","c":["赵飞燕，汉春如一日。","色映豹尾竿，膏香发鬈漆。","扫粉浴兰云帐底，三十六宫寒似水。","天教痴妒擅浮荣，绿箧缄传还啄矢。","唯馀拥背人，暖梦黄金殿。","西风长信深，尘埋旧纨扇。"]},{"t":"两头纤纤 其一","f":"七言绝句","c":["两头纤纤豪矢鬃，半白半黑月蚀空。","腷腷膞膞叩头虫，磊磊落落真英雄。"]},{"t":"两头纤纤 其二","f":"七言绝句","c":["两头纤纤针觜鱼，半白半黑茧纸书。","腷腷膊膊雨跳珠，磊磊落落戴石砠。"]},{"t":"五杂组 其一","f":"曲","c":["五杂组，螮蝀掣。","往复还，寒暑节。","不获已，新昏别。"]},{"t":"五杂组 其二","f":"曲","c":["五杂组，眼缬眩。","往复还，乌衣燕。","不获已，沙场战。"]},{"t":"五杂组 其三","f":"曲","c":["五杂组，袆翟衣。","往复还，大明辉。","不获己，妻儿饥。"]},{"t":"战城南（天历元年秋）","f":"曲","c":["战城南，战城北，前军失利势日迫。","敌兵过谷彍骑据水相扼。","乘间格斗，日薄西陲，大车传飨，且噍且战。","彼灶不得晨炊，伯兄刺弱小弟。","父子对射泣涕洏，马践渠答行仆踬。","剑锋刜落左辫，脑骨披厚陈云，雾敛乌乌四面集。","高天厚地，哀我身死名不立。","奏凯第功赏，持书论首级。","皇帝陛下圣寿千万岁，掩骼埋胔告郡邑。"]},{"t":"拟古辞寡妇叹","f":"曲","c":["弱质生良家，幼岁听傅姆训戒言。","闻有三从，夙夜居，常惕然。","及年适夫子，自意偕老，死归黄泉。","上戴苍苍之天，下有我履之厚地，竟不酬我愿。","为妇未十载，夫子忽舍我去，魂魄不复还。","尊嫜哭其儿，且哀我，少寡居，涕泗恒涟涟。","我哀曷已，恐重伤堂上心，茹恨忍死强自宽。","抚育四三孤，纺绩治生。","供衣服粥?，教养幸成人。","奉夫子祀事，以树立家门，上奉尊章甘旨，不敢少怠，犹夫子生前。","华饰不复施，衿鞶缨佩置之埃尘。","有耳不敢闻闺外事，律己逾于未嫁先。","自分为待命未亡人，礼法自防岂敢愆。","犹复小郎口说譊譊，姻族捃摭相熬煎。","哀哀欲谁诉，祇苦心内割裂，欲死无缘。","赖是县官旌宅里，里中称，孝且贤。","少白我心，瞑目无所怨。","谇曰：已矣乎，薄躯奚术求全。","愿言祷大司命，生世莫作妇人。","即复作妇人，愿死在藁砧前。"]},{"t":"流黄引","f":"七言古诗","c":["桂庭月午啼螀閒，鸾宫露下冰纨单。","酥灯毳帐雁门塞，妾心料此中闺寒。","流黄缩涩微含润，锦石铺云瑩相衬。","细腰杵急夜如年，捣碎商飙不知困。","春纤易制添光泽，凤花入眼波纹溢。","东天皓皓呼侍儿，快取衣箱金粟尺。"]},{"t":"竹枝歌三首 其一 洞庭舟中赋时至治二年二月","f":"七言绝句","c":["正月二月不曾晴，蘼芜洲边春水生。","黄陵女儿年纪小，学唱竹枝三四声。"]},{"t":"竹枝歌三首 其二 洞庭舟中赋时至治二年二月","f":"七言绝句","c":["菜花一尺篱门开，栗留声断斑鸠来。","舍南青苗没人插，郎在黔中何日回。"]},{"t":"竹枝歌三首 其三 洞庭舟中赋时至治二年二月","f":"七言绝句","c":["东山日赤云气昏，河姑劝我莫出门。","持筐采得桑叶满，直到阻雨溪南村。"]},{"t":"竹枝歌二首 其一 自遵化县还京途中作至治三年春","f":"七言绝句","c":["五里河边修禊时，犊车载得细君归。","河边柳色迎草色，山云结雨行人稀。"]},{"t":"竹枝歌二首 其二 自遵化县还京途中作至治三年春","f":"七言绝句","c":["野春平碧生暖烟，虹桥南畔沙漫天。","潞阳河上见酒旆，直下复有钓鱼船。"]},{"t":"竹枝歌三首 其一 送余德辉还池州","f":"七言绝句","c":["春城客子酒著颜，迢迢秋浦是乡关。","江风海月棹歌去，南寻李白何日还。"]},{"t":"竹枝歌三首 其二 送余德辉还池州","f":"七言绝句","c":["沙渚青青芳草茁，梅根潮落蒲帆发。","江头少妇卜金钱，行人归来有华发。"]},{"t":"竹枝歌三首 其三 送余德辉还池州","f":"七言绝句","c":["江东酒船可拍浮，江东女儿娇且羞。","况复春江花月夜，吴侬还向个中留。"]},{"t":"竹枝歌四首 其一 送安庆教授朱仁卿","f":"七言绝句","c":["城南城北雪不消，城门道东无柳条。","我侬相别无可赠，学取楚语作歌谣。"]},{"t":"竹枝歌四首 其二 送安庆教授朱仁卿","f":"七言绝句","c":["淮河岸头春草生，淮河舟中客子行。","春江花月棹歌发，吴侬伴我过清明。"]},{"t":"竹枝歌四首 其三 送安庆教授朱仁卿","f":"七言绝句","c":["南是长江北是淮，中间独坐吟高斋。","有书不报朝贵客，有梦不忆长安街。"]},{"t":"竹枝歌四首 其四 送安庆教授朱仁卿","f":"七言绝句","c":["往年泛舟扬使旌，七月八月江水清。","秋江亭上好风月，莫怪我侬忘寄声。"]},{"t":"竹枝歌六首 其一 自温州抵处州途中作","f":"七言绝句","c":["江南十月如春晖，不知北土霜霰霏。","揽屿亭前橙荐酒，瑶□岭上汗沾衣。"]},{"t":"竹枝歌六首 其二 自温州抵处州途中作","f":"七言绝句","c":["容城洞口朝雨霾，江心寺下早潮回。","永嘉山水自好在，永嘉过客不重来。"]},{"t":"竹枝歌六首 其三 自温州抵处州途中作","f":"七言绝句","c":["此去京城五千里，川途修阻万山峨。","好山好水且消遣，欲说离愁将奈何。"]},{"t":"竹枝歌六首 其四 自温州抵处州途中作","f":"七言绝句","c":["思远楼前罢登眺，华盖峰下好吟哦。","东瓯舟子趁潮去，棹讴不似竹枝歌。"]},{"t":"竹枝歌六首 其五 自温州抵处州途中作","f":"七言绝句","c":["山头小雨云如衣，山下白烟是□炊。","永嘉上流无驿路，永嘉舟中宜赋诗。"]},{"t":"竹枝歌六首 其六 自温州抵处州途中作","f":"七言绝句","c":["石如鹅卵水如玉，安溪戈□清有馀。","我侬舟中多乐事，坐□看□□□□。"]},{"t":"杨柳枝","f":"七言绝句","c":["齐化门东驰道上，鹅黄闪色弄新阳。","凭谁移向龙池种，摇曳宫花扑面香。"]},{"t":"杨柳枝六首 其一 通州道中作至元四年春","f":"七言绝句","c":["第一鹅黄映晓烟。","梢长袅娜弄暄妍。","待得浓阴满夏日，不如春月取人怜。"]},{"t":"杨柳枝六首 其二 通州道中作至元四年春","f":"七言绝句","c":["夹道青青到凤城。","一般飞絮两般情。","离筵见处泣相送，归鞍扑著喜相迎。"]},{"t":"杨柳枝六首 其三 通州道中作至元四年春","f":"七言绝句","c":["玉泉山下绿丝垂。","曾见先皇驻跸时。","翠辇金舆何处去，烟条露叶不胜悲。"]},{"t":"杨柳枝六首 其四 通州道中作至元四年春","f":"七言绝句","c":["金鞍晓拂枝头露，珠帽晴沾苑内尘。","古来每见人悲树，如今却见树悲人。"]},{"t":"杨柳枝六首 其五 通州道中作至元四年春","f":"七言绝句","c":["齐化门东醉别时。","主人折赠最高枝。","船开酒醒潞河远，回头烟树漫参差。"]},{"t":"杨柳枝六首 其六 通州道中作至元四年春","f":"七言绝句","c":["北客还乡二十年。","来时杨柳故堪怜。","而今张绪生华发，手弄柔条一惘然。"]},{"t":"辘轳曲","f":"五言绝句","c":["汉月转桐枝，罗衣怯嫩飔。","银瓶轻坠放，惊散乳鸦儿。"]},{"t":"绿水曲","f":"五言律诗","c":["妾家若耶溪，门扉绿水西。","桂月破烟暝，波明枫影低。","潮痕暗沙觜，浦影空云飞。","蘋洲风未起，待妾采莲归。"]},{"t":"垂杨曲（唐体和张仲容）","f":"七言古诗","c":["杏花雨小西曛出，红鸳微步芳溪曲。","垂杨树暗粉墙高，却上晴楼窥宋玉。","檀奴不到心茫茫，春波一眼无鸳鸯。","探花蝶子不解事，双飞直到帘旌傍。","含娇倚困愁如许，捧砚轻绡识眉宇。","柔情书满紫霞笺，教与雕檐绿鹦鹉。"]},{"t":"春城曲（和马伯庸）","f":"七言律诗","c":["孟阳冉冉青年度，乐酒踏歌宁计数。","魏花如斗云光红，扬镳迤逦城南路。","门前佩马春泥声，香闱锁暗银杯倾。","可是卓姬能窃去，梁园司马擅才名。"]},{"t":"杨花曲","f":"七言古诗","c":["宫莺百啭花房委，燕子日长三月尾。","玳瑁钩帘后阁空，残丝拂度银塘水。","白袷春衫侠少年，旌旗别恨相萦牵。","卢家小娘不闭户，低回交舞妆台前。","软风吹香娇脉脉，西园坞径东园陌。","云踪雨迹杳难凭，青年误杀金钗客。"]},{"t":"残春曲","f":"七言古诗","c":["三月初尽四月始，天气无常每如此。","云垂乍占雨脚近，日丽倏惊风势起。","宫槐蓊郁花如洗，南园愔愔净如水。","公子王孙醉不归，酒醒一昔芳心死。","繁华去矣馀尘埃，愁来不饮空持杯。","歌筵蝶粉频稀少，宾馆柳絮犹徘徊。","少年但知恣欢赏，不道天时有来往。","青轩无计驻芳菲，赤帝多情催长养。"]},{"t":"河淮曲（送桃源县令简西碧）","f":"曲","c":["河水浊，淮水清。","中央置县树孤城，县中置令司群氓。","官尊无差遣，俗善少斗争。","令果仁贤严且明，能令民衣食馀饶鸡犬不惊。","恩泽旁浃垂令名，圭田租入足代耕。","鲜醲饫妻孥，馈遗及友生。","何必黄尘赤日飘缨纡组趋神京，乃始得称豪英。","呜呼简君官甚美，我歌送行不骪骳，愿君莫学河水学淮水。"]},{"t":"杏蜡辞（和马伯庸泰定元年作时初忝科第）","f":"七言律诗","c":["霞绡簇春笑红雨，曲江芳情恼游子。","郎君焰光高二丈，烧杀杏花三十里。","觞酣小驻庞姨家，莺歌溜玉铿红牙。","华裾飘麝鬓毫绿，上马行陪择婿车。"]},{"t":"乞巧辞二章（京师里俗以七月七日昏时设祠乞巧于天星织女盖闺人处子惑于荒谬怪诞之说不事箴组觊倖渺茫虚无之效卒无所得予闵其愚遂设为妇祷神答之意缀成此章假辞托兴以譬夫世之学者昧下学上达之理忽略遗弃于日用寻常之事而谓圣人之迶高远玄妙非力行之所可企及当求之于恍惚有无之域是以终于无闻漫不知省因以为戒且自警云尔） 其一","f":"楚辞体","c":["若有人兮炫服嫭容。","禀慧淑兮思擅女红。","邈天媛兮扬灵，资祷祠兮或通。","明月兮为宫。","琼筵兮名供。","餦餭兮桂醑，蕙炷兮兰缸。","纷娣侄兮翾翻，俨竦息兮敬恭。","晞明明兮嘉惠，感款恳兮弱衷。","抒绝艺兮告予，启下妾兮昏蒙。","俟肸蚃兮□□，极劳心兮忡忡。"]},{"t":"乞巧辞二章（京师里俗以七月七日昏时设祠乞巧于天星织女盖闺人处子惑于荒谬怪诞之说不事箴组觊倖渺茫虚无之效卒无所得予闵其愚遂设为妇祷神答之意缀成此章假辞托兴以譬夫世之学者昧下学上达之理忽略遗弃于日用寻常之事而谓圣人之迶高远玄妙非力行之所可企及当求之于恍惚有无之域是以终于无闻漫不知省因以为戒且自警云尔） 其二","f":"楚辞体","c":["若有人兮天渚廓，凭虚兮容与。","长缡结兮云衣，锵琳琅兮珩瑀。","擢翠旌兮前导，召星妃兮为侣。","肃冷风兮高驰，指药房兮来下，哀要眇兮闇昧，恍冥冥兮晤语。","曰妇职兮实人为，懋劬劳兮事纂组。","谅纫针兮制作，将剖毫兮析缕。","祇乞灵兮诡秘，羌遗诮兮卤莽。","女怊怅兮太息，渺神君兮遐举。"]},{"t":"彭宗建思亲堂辞","f":"楚辞体","c":["羌吾有身兮。","恩孰厚于亲兮。","爱日竭力志犹未信兮。","生事不及思之极天兮。","思兮思兮岂徒劳吾神兮。","不愧不辱贻令名于不泯兮。","孝子锡类推吾仁兮。","谇语德色尚人其人兮。"]},{"t":"延平叶将军歌（叶名衡字仲舆）","f":"楚辞体","c":["鸊鹈膏兮两刃明，箶簶櫜箭双带轻。","将军意气紫电腾，竹函龙节关中行。","丛巢篟栅妖氛死，欧狗馀氛净如洗。","綵幅缠骹事耕耒，牲酒昼欢门夜启。","有时整队搜林樾，鸡狗不惊笳鼓歇。","悬刀解箭烧红帓，倚帐酣吟刺桐月。"]},{"t":"天台道人歌（赠项子虚）","f":"曲","c":["天台道人住幽燕，相知垂及二十年。","黄冠羽衣固不与众异，心脾一片常若冰雪之洒然。","瞳子点漆黑，两颊朝霞鲜。","不知世有熊经鸟伸吐纳鍊摄之秘诀，方寸坦坦泓渟渊。","闾阎府署得失已不挂齿颊，炼丹蜕骨又不形语言。","不曲意谐俗而俗自喜不超然，逃名而名自贤。","不为壶公左慈之幻眩，不为祀灶却老之诞谩。","病者相谒径走马往救，不屑屑责报归来燕坐高槐轩。","艺精时犹闭户究难素，客至大叫拍案治具倾玉船。","共谈南土风物辄欢笑京衢，风沙暑雨亦复不厌能留连。","我为道人写真已太逼，何用缣素施丹铅。","他年史笔不传方士传方技，历历为我徵长篇。"]},{"t":"知足斋歌（东海蔡平甫未七十致仕以知足名斋其子升卿与予为同舍生江陵郡庠）","f":"七言古诗","c":["人生堪舆渺海粟，心为形役太愁蹙。","岁衣十匹适燠寒，日饭两盂充馁腹。","口体之奉盖养生，蝇营狗苟复功名。","轩裳茵鼎遂雅志，白头皱面无欢情。","四十不作尚书郎，倏忽头颅已如此。","渊明那叹松径荒，季鹰岂谓莼鲈美。","蔡侯静者吾故人，老聃名言书诸绅。","向持白简肃江汉，今祇牙绯耀里邻。","幅巾黎杖书连屋，孙子田园多厚福。","久知薄酒胜茶汤，尤恶得陇复望蜀。","五陵纨裤争纷华，掠剩鬼瞰高明家。","旂常竹帛渺何许，云阳市上令人嗟。","左手持肴右持酒，酒酣起舞歌击缶。","采衣照映酡颜红，不识门前断肠柳。","枌榆乡社安乐窝，灵台瑩澈恬无波。","烟水云山动高兴，玉堂金马奈予何。"]},{"t":"秋日寄牛农师","f":"五言律诗","c":["别酒记春深，秋来少信音。","出门谁共语，策杖祇幽寻。","晴叶因风堕，寒螀著露吟。","荆门霜落早，离思亦难禁。"]},{"t":"同十七弟训南城访友不遇且闻将有金陵之行","f":"五言律诗","c":["芳径暴桥西，徘徊白板扉。","家人出帘语，小季掉鞭归。","榆荚晴将老，杨花晚渐稀。","仍闻欲南棹，情思愈依依。"]},{"t":"送张光道归洛中","f":"五言律诗","c":["惆怅都门道，还家又布衣。","著书毛颖秃，归隐蕨芽肥。","南陌经春雨，西□□□□。","□□□□听，谁复理金徽。"]},{"t":"马伯庸淮南别业号石田山房指韵求诗仍依次用","f":"五言古诗","c":["窈曲愚公谷，萦旋戴氏池。","人从西掖召，文任北山移。","畦稻收新粒，岩花艳故枝。","地因人愈胜，心共景相宜。","户昼孙常闭，园春董不窥。","纷华忘世变，衷素付天知。","暗筱藏仙客，乔林叫窃脂。","淮流纡大带，楚岫作修眉。","辋水堪摩诘，樊川称牧之。","山房空蕙帐，猿鸟望归期。"]},{"t":"太学生刘君定挽诗二首（君定西域人延祐七年中大都乡试是岁冬客死京师其父母时在浙西蔡思庸字有道陈可久字宗得皆胄子之翘楚者是岁并亡故及之） 其一","f":"五言律诗","c":["岁暮当风雪，乔松偃涧阿。","丰仪思蕴藉，文采失中和。","前日阳春曲，今朝薤露歌。","天高鬼神恶，此世定如何。"]},{"t":"太学生刘君定挽诗二首（君定西域人延祐七年中大都乡试是岁冬客死京师其父母时在浙西蔡思庸字有道陈可久字宗得皆胄子之翘楚者是岁并亡故及之） 其二","f":"五言律诗","c":["蔡子乘虬去，陈生跨鹤征。","人方怜二妙，天遂夺三英。","稚弟攀輀哭，群公执绋行。","庭闱四千里，悲动浙江城。"]},{"t":"汉阳拱北楼","f":"五言古诗","c":["世祖开寰宇，遐邦寝甲兵。","贤王违旷僻，中国慕升平。","凤诏疏恩□，□□锡命荣。","白茅分赤土，文组耀华缨。","北极群星拱，东溟众水倾。","五朝嘉笃懿，百代述忠贞。","戎幕招僚佐，书帏下友生。","尧仁天广大，汉道日昭明。","德重心逾小，功深宠不轻。","朱轩临巨镇，画戟照高闳。","执玉云霄近，吟诗江汉清。","苍穹秋摩鹄，碧海夜翻鲸。","竹帛垂丕绩，衣冠播盛名。","长歌有馀兴，谁识曳裾情。"]},{"t":"卢疏斋赵平远小像","f":"五言古诗","c":["盛德不孤立，钜邦尊二贤。","卢翁官察访，赵使职旬宣。","契分元偕白，襟期甫暨虔。","柏森松竞秀，圭瑩璧相联。","高谊云霄外，清标几杖边。","句枝时络绎，杯算日缠绵。","宵候丹砂灶，秋鸣绿绮弦。","岳跻同谢屐，湘泛共膺船。","酿酒矜方妙，裁衣斗品全。","敖嬉驱騕袅，笑咏抚婵娟。","密迩通家好，留连对榻眠。","闭关常习静，挥麈或谈玄。","閒矣山中相，翛然地上仙。","仪刑人倏逝，丰度世争怜。","肖貌开光霁，垂名著简编。","精神栖落月，思致薄凌烟。","岂直江潭重，应齐宇宙传。","长沙多胜境，并祀待他年。"]},{"t":"挽岭北省郎中苏子宁（真定人）","f":"五言古诗","c":["河朔多奇士，栾城有令孙。","策名游宦海，衍庆出儒门。","两府推曹掾，群公听讨论。","天池鹏远击，云路鹤高鶱。","腾达初云迈，驰驱岂惮烦。","河汾一白简，江浙两华轩。","吏牍机权密，官联体统尊。","流亡藉安集，诖误得平反。","材器楩楠耸，胸襟云梦吞。","北藩曾入幕，南国复攀辕。","夙望存台阁，声能著塞垣。","芸编严子训，芝检答亲恩。","显达逢昭代，荒凉忆故园。","脩程车骋辙，厚福水流源。","政抚青霄立，俄瞻素旆翻。","佳城俨新市，搔首赋招魂。"]},{"t":"送杨惟肖（字与似）","f":"五言古诗","c":["浩浩岷江水，循循蜀郡人。","山川赋清淑，弦诵袭真淳。","毓秀年华盛，□□学业新。","金钟悬彩簴，玉树照青春。","翰墨资耆旧，才猷怨隐沦。","前时辞下国，指日问通津。","怀土心虽切，观光气遂振。","鲸鱼腾碧海，鸷鸟击苍旻。","识鉴滋无愧，因依得可亲。","吾侪陪客次，汝伯实儒珍。","促席襟期密，知音笑语频。","悲歌忘宇宙，慷慨惜风尘。","爱尔情俱似，而今意愈真。","閒门车马集，奥室简编陈。","会合时难久，渐摩德有邻。","三年曾刻楮，一旦忽思莼。","自分燕椎钝，深惭越女矉。","赠言申缱绻，别酒话酸辛。","时世文明日，诗书少壮身。","重来偕计吏，何用苦伤神。"]},{"t":"同年小集探策赋诗得天字","f":"五言古诗","c":["仁庙尊儒术，嘉猷匹古先。","丕承由列圣，大比涉三年。","拣拔归陶冶，招徕际幅员。","文星明似月，公道直如弦。","世运逢熙洽，吾侪属引延。","两班延虎拜，多士出胪传。","恩重冠裳赐，衔清馆阁联。","绿章趋画阙，华服曳春筵。","载酒芳坰外，闻歌小海边。","欢娱能几日，去住不同天。","文省摛辞丽，容台执礼虔。","四门崇教育，庶府杂周旋。","桂玉悲妻子，尘埃厌市廛。","缅思州县职，恒畏简书愆。","苦乐宁非分，升沉各有缘。","云随风力断，萍逐浪花牵。","几听宫莺啭，频惊海月圆。","重来情翕翕，复会语绵绵。","问梦观青鬓，遨嬉驻彩鞯。","但思倾玉斝，那复计金钱。","发兴分奇韵，抒怀托短篇。","勤劳有王事，□□□诸贤。"]},{"t":"祁真人所居云州金阁山有异香","f":"五言律诗","c":["真人持玉节，高居坐广霞。","风度三山杳，香闻数里赊。","氤氲翠羽盖，旖旎斑麟车。","无缘访玄迹，应赴蔡经家。"]},{"t":"送姚子中参政江浙行省（时浙省平章曹某罢免）","f":"五言古诗","c":["文学蜚腾早，中朝践履多。","嘉谋思妥帖，直道忍媕婀。","物议和□□，钧陶□岳峨。","凤池春入幕，象魏晓鸣珂。","蕴藉登醇酒，辉光厉太阿。","久劳裨国政，暂出省民疴。","眷注恩何厚，操持行不颇。","牙旌辞紫禁，鹢舫下黄河。","竹树供图画，江湖入咏歌。","金山访兰若，赤岸击牂牁。","馆传虽丰饰，登临得几何。","自公方变鲁，视事肯随酂。","保障逾闽海，征财及茗鹾。","民居散鸿雁，水患助蛟鼍。","恤匮施仁泽，搜贤置礼罗。","赠言徒感激，报政敢蹉跎。","去国时宁久，辞乡语渐讹。","殊方善调御，趣召鬓双皤。"]},{"t":"从驾观承天护圣寺（至顺二年五月）","f":"五言律诗","c":["陪驾西郊外，遐观倦未还。","荷深七里泊，云近五华山。","境胜嗟来暮，官微愧不閒。","凭高歌夏谚，直拟重跻攀。"]},{"t":"送苏伯修内翰南台御史","f":"五言律诗","c":["若人抱奇璞，柱史称高情。","含霜趋建业，踏雪过芜城。","奋彼澄清志，违此交友盟。","相思祝餐饭，贞哉保令名。"]},{"t":"送方公亮扬州教授","f":"五言律诗","c":["莫作芜城赋，长歌藻泮思。","盘餐陈苜蓿，虚座拥皋比。","彭蠡家何近，漳江棹不迟。","春城且冰雪，能忘别离时。"]},{"t":"靳士昌宅前大树","f":"五言律诗","c":["百丈门前树，多曾阅市人。","斜梢侵寺塔，直干阚城闉。","喜映龙楼日，愁栖马市尘。","何时濯枝雨，老翠尚能新。"]},{"t":"送江东贡有源分韵得庭字（以著书除学官）","f":"曲","c":["闻说宣城郡，名家聚德星。","因君诣京阙，如我到门屏。","?亩知闻道，诗书出过庭。","归航有毛檄，不负世明经。"]},{"t":"寄题水木清华亭","f":"曲","c":["僻地开三径，荒山住一翁。","栖迟瞰澄澈，结搆倚葱茏。","画槛穿黄蝶，芳塍散白豵。","云湫龙恍惚，月砌鹤氋氃。","破晓孤村日，号秋万壑风。","溪流明见底，岩树润通中。","曳杖行霜果，褰衣检露丛。","稻花香入户，杉叶势侵栊。","穫罢平川迥，樵归狭路穷。","岚迷峰上下，泉合涧西东。","陂养鱼千石，秧移地百弓。","收成防雀鼠，种植聚奴童。","薯蓣登秋课，禾麻验岁功。","要宾如郑驿，遗子似庞公。","物外心何远，朝中信不通。","坐从书帙乱，饮?酒尊空。","景物樊川似，生涯辋口同。","嬉游未可到，赋咏或难工。"]},{"t":"游昆山慧聚寺和唐人诗二首 其一","f":"五言律诗","c":["碧云天一方，休公具禅床。","天女散花近，懒残煨芋香。","殿灯耿寒灺，波月澄冷光。","愿言谢朝绂，托身栖道场。"]},{"t":"游昆山慧聚寺和唐人诗二首 其二","f":"五言律诗","c":["天外山光近，峰颠海气吞。","潮凭风作阵，云藉石为根。","鸟重烟藏树，帆多水绕村。","凭高暂诗酒，回首望脩门。"]},{"t":"游虎丘回宴舟中","f":"五言律诗","c":["名郡值佳境，良朋谐胜游。","阊门暂弭节，虎丘同汎舟。","岸莎欲佐舞，波鱼能听讴。","对酒写高兴，不乐复何求。"]},{"t":"送张谦受归天台","f":"五言律诗","c":["客路五千里，三年谒帝居。","新丰空对酒，光范不投书。","高兴莼鲈外，清标翰墨馀。","临岐赠诗句，惆怅欲何如。"]},{"t":"崇天门即事","f":"五言律诗","c":["久缀鹓班底，逶迤晓思迟。","偶因迎册处，却忆唱名时。","御水流故道，宫花换旧枝。","自惭无补报，四十鬓先衰。"]},{"t":"兵部侍郎王崇道出守东平","f":"五言律诗","c":["使君朝著久，暂出守名城。","祇羡黄堂贵，能忘粉署荣。","编民瞻□履，候吏引麾旌。","早寄高斋咏，令人识政成。"]},{"t":"城南道院即事","f":"五言律诗","c":["三径草纤纤，苔痕过雨粘。","风光殊不恶，凉意复相兼。","芍药斜侵墄，蒲桃乱入檐。","可怜成小憩，不得遂幽潜。"]},{"t":"雄州道中即事","f":"五言律诗","c":["南过新城道，田畴迥不同。","长沟如浙右，下壤似淮东。","塘泺依依住，桥梁处处通。","道傍遗老说，此可治农功。"]},{"t":"贾恭人哀挽（六月二十八日贾郭氏其夫由征交趾为百夫长戍杭子某代为之迎养恭人于南既没归葬中牟）","f":"五言律诗","c":["彼美涵濡厚，于归树立艰。","持家夫效勇，袭职子承颜。","海错供甘旨，河壖返佩环。","因嗟陈孝妇，不见藁砧还。"]},{"t":"送简秋碧河源县尹","f":"五言律诗","c":["文墨终堪奋，牙绯亦自豪。","身留阙下久，官入岭南高。","儿子随行李，乡邻且浊醪。","长材能制锦，何惮折腰劳。"]},{"t":"南城天庆寺僧雅致亭","f":"五言律诗","c":["一昔到上方，尘虑能相忘。","鼎水他山茗，炉烟异国香。","杂芳供春艳，佳木通夕凉。","不有草堂咏，那闻赞公房。"]},{"t":"宛平县尹李克中号约斋","f":"五言律诗","c":["赤县徵呼际，缁尘浩瀚间。","事随红日出，心共白云閒。","万顷鱼龙海，重霄虎豹关。","人人瞻北极，处处看青山。"]},{"t":"次韵谢敬德司业冬至夜见念诗二首 其一","f":"五言律诗","c":["历肇羲和纪，云从太史书。","寒威尽凛冽，阳晷渐舒徐。","消息存元气，行藏问太虚。","茫茫千岁测，坐致欲何如。"]},{"t":"次韵谢敬德司业冬至夜见念诗二首 其二","f":"五言律诗","c":["陶令惟耽饮，虞卿漫著书。","雄文莫吊屈，高士不徵徐。","酒肉朱门臭，尘埃白屋虚。","古交崇节义，时慕蔺相如。"]},{"t":"元夕西门外访友","f":"五言律诗","c":["信马出林坰，因君得暂停。","春灯九子殿，夕照百官厅。","断水冰犹白，荒陂草未青。","遥观陪扈处，怀昔意冥冥。"]},{"t":"送明理赴南丰州判官","f":"五言律诗","c":["吴越流亡岁，湖南馈饷时。","目前堪抚字，江右少疮痍。","上佐官何美，南行乐不支。","盛年思报国，莫动别离悲。"]},{"t":"先兄正献公坟所寒食五首 其一","f":"五言律诗","c":["车马自骈阗，风寒复禁烟。","野筵惟粔籹，村女亦秋千。","远岫清明雨，高坟白竹钱。","乞墦君莫笑，攫肉有轻鸢。"]},{"t":"先兄正献公坟所寒食五首 其二","f":"五言律诗","c":["才动山林兴，还增畎亩忧。","夕阴仍不雨，春冷欲如秋。","抚旧谁伤悼，乘时尽醉游。","农家多苦旱，啼杀舍南鸠。"]},{"t":"先兄正献公坟所寒食五首 其三","f":"五言律诗","c":["树冷杏悭花，池乾草勒芽。","愁吟春自浅，乐饮日还斜。","远翼摩霄鹤，喧传得食鸦。","城中火宅苦，吾欲觅仙家。"]},{"t":"先兄正献公坟所寒食五首 其四","f":"五言律诗","c":["兀坐寻诗句，豪吟引酒杯。","悲歌常激烈，暗咏亦徘徊。","诗向眼前得，兴从天外来。","成章多坦率，犹待故人裁。"]},{"t":"先兄正献公坟所寒食五首 其五","f":"五言律诗","c":["三日春郊宿，留连不肯回。","寻诗乘款段，步屧踏莓苔。","胜境僧多占，深村客少来。","明朝入城市，那复好怀开。"]},{"t":"送王君冕归长安","f":"五言律诗","c":["去国三千里，登科二十年。","盍簪方晤语，分袂忽言还。","书帙休晨检，诗筒息夜传。","更无吟偪侧，惟有恨缠绵。"]},{"t":"遵化县感怀书事二首（巡历京畿东道） 其一","f":"五言律诗","c":["驱马出京华，疲民尽怨嗟。","孤臣难报国，老客不思家。","酿雪观云气，占风看月牙。","翻思未遇日，啸傲寄烟霞。"]},{"t":"遵化县感怀书事二首（巡历京畿东道） 其二","f":"五言律诗","c":["有疾不饮酒，无悰难赋诗。","豪强妨抚字，奸黠玩鞭笞。","废堞群鸦集，荒山雪意垂。","庭前一曕眺，聊尔当遨嬉。"]},{"t":"宿安平驿（按行河南四道）","f":"五言律诗","c":["屋西山气合，门外竹光浮。","总为襟怀敞，不知行役愁。","清时少词愬，乐岁美田畴。","帝力知难报，犹须动隐忧。"]},{"t":"南漳县留题（录囚襄阳）","f":"五言律诗","c":["寂寂南漳县，熙熙稍可居。","水流穿町疃，山色瞰阶除。","木槿能红白，色蕉半卷舒。","讼庭无判牒，聊复写清虚。"]},{"t":"均州顺流之光化县舟中作","f":"五言律诗","c":["岸阔渐无山，波平顿少滩。","鱼来晨艇集，谷熟夜庐看。","野处民生遂，江行旅思欢。","仍闻囹圄静，尤觉老怀宽。"]},{"t":"襄阳","f":"五言律诗","c":["暂驻襄阳府，怀贤一惘然。","留名堕泪石，得计遗安田。","醉听拦街唱，饥餐缩项鳊。","诗人亦痴绝，四美欲鱼全。"]},{"t":"江渎行祠","f":"五言律诗","c":["晓出楚城东，丛祠肸蚃通。","沙高淤象嘴，波静閟龙宫。","吴蜀源流远，薶沉世代同。","所祈无溃决，相我岁年丰。"]},{"t":"四月晦日即事","f":"五言律诗","c":["暝树俯疏棂，阴浓簇广庭。","连绵送月雨，历落照泥星。","好友违千里，痴儿昧一经。","近来忘百虑，恬淡养遐龄。"]},{"t":"复回下外朝山行白浪道中二首 其一","f":"五言律诗","c":["惴惴均房道，重来又数程。","步溪愁石坎，苦雨畏云行。","履险神魂散，忘私性命轻。","回车从小憩，呼酒贺更生。"]},{"t":"复回下外朝山行白浪道中二首 其二","f":"五言律诗","c":["径路纡馀出，沙湾宛转流。","群山中不合，万竹翠相缪。","稼圃何粗鄙，桃源岂谬悠。","境奇诗句拙，摹写愧林丘。"]},{"t":"李清卿迁掾淮东（时已贡六察掾再娶奉母登舟）","f":"五言古诗","c":["将母刊沟上，君舟届远行。","不须生别恨，所重立修名。","谢绝山中险，方来海上征。","续弦新井臼，读律古章程。","夜月孤舟稳，秋风五两轻。","中台辟书蚤，便道易趋京。"]},{"t":"冬雨","f":"五言律诗","c":["十月楚天雨，同云暗八荒。","前山应是雪，此地不成霜。","气混朝岚重，声兼夜漏长。","閒庭断来往，幽思渺无方。"]},{"t":"枝江县独坐（按部峡州）","f":"五言律诗","c":["泽国持龙节，蒙恩备使臣。","简书时自理，灯火夜相亲。","山雪迷残腊，溪梅借早春。","所忧无异政，何以慰斯民。"]},{"t":"环翠亭述怀（至正元年正月）","f":"五言律诗","c":["江县闾阎合，池亭水草交。","红梅过年蕊，绿竹隔墙梢。","清兴诗联集，微疴酒盏抛。","何能遗世累，云外结松巢。"]},{"t":"次前韵寄苏伯脩韩大雅","f":"五言律诗","c":["园令常多病，嵇康欲绝交。","游鱼跃江浦，宿鸟聚松梢。","远志何时遂，閒愁一昔抛。","故人多显达，阿阁凤皇巢。"]},{"t":"太古诗","f":"五言律诗","c":["宇宙万年外，污隆百代中。","时艰崇谲诈，世降逞奸雄。","效职心如石，攻邪气似虹。","如君多布列，庶可返淳风。"]},{"t":"商山道中早行","f":"五言律诗","c":["五月商于道，驱羸戊夜行。","万山分地色，千涧混鸡声。","野硙乘机置，山田冒险耕。","浮名致萍梗，吾亦叹劳生。"]},{"t":"阌乡道中","f":"曲","c":["风雨度崤?，新晴喜若何。","云间瞻太华，马上看黄河。","心已为形役，身兼抱病多。","平生远游志，垂老渐销磨。"]},{"t":"送王止善广东市舶提举（尝为两浙运司及海道府幕官）","f":"五言律诗","c":["送子炎方去，临岐发永叹。","如何医国手，祇作理财官。","海晏商帆盛，风清客枕安。","番禺天不远，佳誉彻朝端。"]},{"t":"送冯公厉江浙参政分题得扬子江","f":"五言古诗","c":["万里岷峨水，维扬会众流。","云涛倾楚尾，天堑壮吴头。","北固山光近，南泠水品优。","离亭风笛晚，古寺月钟秋。","衮舄承新渥，旌麾镇上游。","疮痍烦抚定，景物肯淹留。","瓜步堪凝眺，芜城动别愁。","江波深更阔，应似庙堂忧。"]},{"t":"清苑张节妇（遗腹子某今为左卫幕官节妇八十容城人）","f":"五言律诗","c":["一线艰危路，伊人亦自贤。","兰芽始拨雪，桂子已参天。","苦节年龄永，衰宗福泽延。","一时华表柱，千古柏舟篇。"]},{"t":"徐元庸寒泉庐","f":"五言律诗","c":["孝子终天恨，寒泉未足云。","水浆不入口，鹿豕与同群。","手线今何在，杯棬岂忍闻。","素冠曾有刺，珍重守孤坟。"]},{"t":"送张掌仪诗","f":"五言律诗","c":["之子宁亲去，桥门忽别离。","一时分祖饯，六馆重威仪。","乡国青山近，宫墙白日移。","功名已在望，菽水未妨迟。"]},{"t":"至元三年六月八日史局作休从伯京御史公亮太监伯温秘卿伯循待制暂至城西秘卿待制别去伯京归家予遂偕公亮回憩都水监双清亭监掾平伯钦留饮即席赋五言十八韵","f":"五言古诗","c":["皇都官曹盛，铨衡簿领优。","公庭临紫陌，宾幕对沧洲。","树影移门暗，荷香曲榭幽。","亭台分错绣，车马去如流。","市迥尘声杳，山明霁色浮。","广寒南耸殿，齐政北瞻楼。","心远逾寥廓，身高不自由。","茶瓜延永昼，絺绤借清秋。","翠牖何劳扇，珠帘不下钩。","冰盘丹果沈，石枕碧苔留。","浪迸频跳鲤，萍开缓泛鸥。","画船思荡漾，红粉废歌讴。","竹叶生高兴，甘棠叙旧游。","主人供饮馔，胜景得绸缪。","洗砚惟呼仆，移床屡召驺。","史才惭忝预，诗句费冥搜。","联璧知何在，乘驺计少休。","诘朝重赴局，持此诧同俦。"]},{"t":"赠墨工魏元得","f":"五言律诗","c":["煤麝捣鱼胞，居然品格高。","剂传龙髓记，香出豹囊韬。","讵可饰昭应，唯将录楚骚。","多君远持赠，诗句少酬劳。"]},{"t":"送萧同可之肇庆照磨（吉州万安人）","f":"五言律诗","c":["遐方殊不恶，幕府独贤劳。","客路离乡近，官资过岭高。","溪清石可砚，飓息海无涛。","此去腾芳誉，公车荐剡操。"]},{"t":"送李惟中西台侍御史分题得长乐坡","f":"五言律诗","c":["秦东有古坂，一舍近重城。","已脱崤函隘，仍瞻灞浐清。","柳条前岁别，草色蚤春迎。","旧路平如掌，乘骢自不惊。"]},{"t":"友人借书为科举文检阅戏书以答之","f":"五言绝句","c":["一笑鹘搦兔，终朝獭祭鱼。","秋闱与春试，却用郝隆书。"]},{"t":"公安道中","f":"五言绝句","c":["碌轴如醉翁，深春卧晴绿。","坳径露不乾，下有蚯蚓哭。"]},{"t":"小景扇","f":"五言绝句","c":["桂楫寒烟浦，茅庐老树枝。","画图嗟岁暮，不及见春时。"]},{"t":"访僧不遇题壁","f":"五言绝句","c":["莎草沿阶密，筼筜绕槛幽。","禅床太清绝，聊待碧云休。"]},{"t":"子昂风竹横披","f":"五言绝句","c":["笔意出天机，翛然仰复低。","稍须风势定，应有凤来栖。"]},{"t":"采莲小景","f":"五言绝句","c":["莲华被君采，莲实被君折。","相牵俱如丝，如何能遽绝。"]},{"t":"仇云轩训其子彦中廉访三绝句其孙今御史公度持以求诗","f":"五言绝句","c":["柳玭著家法，马援述交情。","人称世济美，谁谓公惭卿。"]},{"t":"三鹭扇头","f":"五言绝句","c":["欲下势翩翩，对立羽肃肃。","风标尽潇洒，其奈股无肉。"]},{"t":"送高句骊僧式上人东归二首（号无外） 其一","f":"五言绝句","c":["师从东国来，却返东国去。","能操无外心，何不中国住。"]},{"t":"送高句骊僧式上人东归二首（号无外） 其二","f":"五言绝句","c":["暮餐城南粥，朝踏城东尘。","道人心似水，去住本无因。"]},{"t":"送国子生吉祥海涯还蕲州觐省","f":"五言绝句","c":["少年住京国，思亲不暂停。","岂伊居庸翠，不及楚山青。"]},{"t":"磨石村口号（谷城道中）","f":"五言绝句","c":["伛柳碍行骑，山家少憩时。","黑云催上马，不省主人谁。"]},{"t":"分宪后圃二咏（襄阳路） 其一 桃","f":"五言绝句","c":["秋桃实累累，久熟双颊赤。","风来堕苔径，取食味如蜜。"]},{"t":"分宪后圃二咏（襄阳路） 其二 玉簪","f":"五言绝句","c":["雅洁玉簪花，清芬莫与比。","不得向阳栽，植根北窗底。"]},{"t":"公安早行","f":"五言绝句","c":["误听野鸡鸣，扬鞭趋驿程。","平明见茅屋，方觉冒霜行。"]},{"t":"都城杂咏（四首） 其一","f":"七言律诗","c":["万户千门气郁葱，汉家城阙画图中。","九关上彻星辰界，三市横陈锦绣丛。","玉盌金杯丞相府，珠幢宝刹梵王宫。","远夷纵睹争修贡，不用雕戈塞徼通。"]},{"t":"都城杂咏（四首） 其二","f":"七言律诗","c":["豪杰纷纷白玉京，汗颜血指战功名。","九重见帝多因鬼，万里封侯不用兵。","肥马尘深心独苦，鲋鱼波涸事难平。","西山小隐烟霞暗，依旧春犁趁雨耕。"]},{"t":"都城杂咏（四首） 其三","f":"七言律诗","c":["风物鲜妍饰禁城，豪家戚里竞留情。","花围锦幄清明宴，香拥珠楼乞巧棚。","叱拨马摇金辔具，帡幪车飏绣帘旌。","他年定拟持铅椠，细数繁华纪太平。"]},{"t":"都城杂咏（四首） 其四","f":"七言律诗","c":["流珠声调锦琵琶，韦曲池台似馆娃。","罗袖舞低杨柳月，玉笙吹绽牡丹花。","龙头泻酒红云滟，象口吹香绿雾斜。","却笑西邻蠹书客，牙签缃帙费年华。"]},{"t":"闻驾幸开平不获瞻仰怅然有作","f":"七言律诗","c":["云裘浮翠漾朝暾，舜陛雍容引绀辕。","驼鼓一声离□馆，龙旗小队驻花园。","空闻祝軷西华道，不及瞻天建德门。","自是承平好行幸，薰风无乃圣躬烦。"]},{"t":"明照坊对雨","f":"七言律诗","c":["章台车马去如流，白雨霏烟拂画楼。","九陌平铺明似练，两沟急泻碧于油。","美人虹见西山霁，少女风来北里秋。","凉意满襟帘幕捲，宫鸦归树夕阳收。"]},{"t":"璧月","f":"七言律诗","c":["璧月悠悠上女墙，六街灯市远微茫。","随车径去柳家婢，走马独归韦氏郎。","戚里烟尘眩银海，九重宫阙接瑶光。","铜驼陌上听鼕鼓，笑杀西楼白玉觞。"]},{"t":"延祐七年十一月朔小雪既上英宗皇帝入太庙祀享致斋万姓瞻仰喜而赋诗","f":"七言律诗","c":["五夜飞花合御沟，銮舆拂晓建龙斿。","千官玉佩开黄道，九陌琼枝照綵旒。","皓色潜消鳷鹊殿，清光欲近凤凰楼。","遥想斋宫祠祀罢，天恩应共海波流。"]},{"t":"上中书张参议","f":"七言律诗","c":["中官传敕构鳌山，公相披云犯玉颜。","紫府腾书天咫尺，彤庭赐帛锦斓斑。","丹心济世今能遂，白发归田未可閒。","早晚传宣催大拜，更将霖雨膏尘寰。"]},{"t":"送高子敬归彭城","f":"七言律诗","c":["元龙不拜富民侯，袖剑囊书苦掉头。","李愿有心盘谷去，阮咸无意雒中留。","春城寒食莺花静，日暮乡关汴泗流。","我亦拿舟江海去，试从沙鸟问黄楼。"]},{"t":"寒食暂出","f":"七言律诗","c":["一百五日上街头，半晴半雨天悠悠。","豪家出郭车争道，少妇当垆人上楼。","辇路暗生芳草远，御沟平瞰碧波流。","少年直把春偿酒，若个新诗纪胜游。"]},{"t":"哭张惟健（惟健济南张公希孟之子贤而有文才识通敏丰仪俊秀礼法从容好古物善草隶诸书当时之名公子也）","f":"七言律诗","c":["天风吹下玉鱼符，绛节飙轮下玉虚。","人海渺茫思卫虎，士林憔悴叹曹蜍。","纷纷故物尘凝座，寂寂春魂月满除。","珍重尊翁休痛哭，郎君方代少霞书。"]},{"t":"卫御史（故西台御史平阳卫弼字良佐延祐初以列郡守忤贵近意由是有旨罢西台良佐遂归亡何薨后数年识其子靖卿靖卿席世赏得官亦气节凛凛有父风云）","f":"七言律诗","c":["御史昔乘青骢马，霜气横秋乌府门。","太白终南让高峻，泾流渭水分清浑。","神随丹旐归全晋，名入青编纪大元。","欲识当时真铁面，只今犹有凤皇存。"]},{"t":"通州晚晴即事（南游湖湘）","f":"七言律诗","c":["水榭空明雨脚收，凝笳催上驿亭舟。","紫霞斓剪翔鸿锦，碧草平铺集翠裘。","落日关河初客路，浮云宫阙上神洲。","谁怜五色江郎笔，真使超然赋远游。"]},{"t":"橹港夜泊","f":"七言律诗","c":["七月六日立新秋，船窗风露凉萧飕。","神祠击鼓鸦集树，水驿通灯鱼傍舟。","身在江湖频北顾，眼看河汉近西流。","远人争问京华事，为说夔龙佐冕旒。"]},{"t":"江上夜泊遇京使回却寄都下诸公","f":"七言律诗","c":["风气凉凉水气清，白榆如玉绛津明。","横江渡口晚潮退，采石矶头凉月生。","远道迢迢蝴蝶梦，旧涯历历凤皇城。","群公奋翮青云上，应笑扁舟万里行。"]},{"t":"书湘阴谢使君厅壁","f":"七言律诗","c":["使君厅事冷于冰，使君无家静如僧。","门树枕街横暮犬，戟枝当户照寒芿。","僮奴伍伯随阳雁，曹佐书司被冻蝇。","料得太常斋未足，玉珂朝马去飞腾。"]},{"t":"雪中游洞庭","f":"七言律诗","c":["楚酒初开腊瓮边，湖船遥指暮山前。","乡关迢递不归去，身世伶仃时自怜。","雨雪还须送残岁，晴明应是入新年。","阳和咫尺烟花媚，却写春光被管弦。"]},{"t":"除夜宿武口驿忆诚夫兄","f":"七言律诗","c":["瓶笙榾柮淡无聊，几度他乡遇此宵。","三十男儿尚书剑，寻常意气自云霄。","风灯直下渔歌乱，斗柄傍连帝阙遥。","悬想银台门下客，听鸡忙赴紫宸朝。"]},{"t":"初冬之先垄即事（至治三年作先垄在南城之东南宜泉村沙垡）","f":"七言律诗","c":["乌鹊相依啄野田，白驼对立饮冰泉。","蒲洲凌薄车旋泞，棘路沙虚马惧鞭。","冢上白杨时猎猎，苑中红叶晓翩翩。","嗟予谩索长安米，愿就耕夫受一廛。"]},{"t":"登第诗五首（泰定元年甲子） 其一 崇天门唱名","f":"七言律诗","c":["三月吉日当十三，紫雾氤氲阊阖南。","天子龙飞坐霄汉，儒生鹄立耀冠篸。","黄麾仗上清风细，丹凤楼头晓日酣。","独爱玉阶阶下草，解将袍色染成蓝。"]},{"t":"登第诗五首（泰定元年甲子） 其二 恩荣宴（四月二十六日）","f":"七言律诗","c":["上相传宣弁□趋，玉堂西北拜銮舆。","歌声缥缈方壶外，酒味氤氲沆瀣馀。","幕额锦光晴烂漫，帽檐花影昼扶疏。","君恩谁识深如海，独倚东风咏藻鱼。"]},{"t":"登第诗五首（泰定元年甲子） 其三 同年会（四月二十九日海岸之万春园）","f":"七言律诗","c":["临水亭台似曲江，同年人物宴华堂。","婵娟笑弄龙香拨，醽醁深涵鸟羽觞。","醉后方言频尔汝，座中除目互平章。","从来期集输京雒，仍见诗歌播八方。"]},{"t":"登第诗五首（泰定元年甲子） 其四 赐章服（自是年始幞头袍带靴银木简皆具简上仍刻御赐字金填之五月一日皆除书同授）","f":"七言律诗","c":["承平天子重科名，章服分颁出大明。","袍是涿罗香缕细，笏胜楷木素文横。","晨趋象魏云霞粲，夕奏龙墀玉雪清。","遥想鸣珂朝会处，鹓行争讶被恩荣。"]},{"t":"登第诗五首（泰定元年甲子） 其五 上表谢恩（五月二十一日时驾已北幸）","f":"七言律诗","c":["瑞日鲜明射玉题，华袍綷䌨近罘罳。","舍人宣赞瞻丹阙，新进趋跄诣赤墀。","黄屋云行天杳邈，绿章风送路逶迤。","湛恩岂许须臾报，要见他年献纳辞。"]},{"t":"海岸春行","f":"七言律诗","c":["越桥西下苑墙高，绿染垂杨绛染桃。","霞拥玉楼晴启户，风生瑶海暮翻涛。","官因立马看花担，渔忆闻莺罢竹篙。","唯有杏园春事好，几人诗兴似吾曹。"]},{"t":"送朱仁卿盱江觐省","f":"七言律诗","c":["晴霞紫陌忽逢君，暂托尘衣访白云。","上国离人心草草，北堂慈母梦欣欣。","波冲海淀漳川合，舟入鄱阳楚路分。","珍重驿程诗句好，不妨驰寄慰离群。"]},{"t":"和张仲容杂诗","f":"七言律诗","c":["蓬莱云彩烂东方，鱼钥开门禁漏长。","万仞楼台争霁色，九重宫阙动秋凉。","羽林执戟趋神武，骑客彯缨入建章。","独爱芸窗常寂寞，六街车马是谁忙。"]},{"t":"诚夫兄由兵部员外调选江湘次留别诗韵送之","f":"七言律诗","c":["鲸鲵吞饵钓槎閒，英簜开承使节函。","北地关河摇落后，东吴风物笑谈间。","晴湖泛艇鸥冲桨，夜邸悬灯马卸鞍。","莫以遨嬉夸小季，春风今在五华山。"]},{"t":"和赵鲁瞻海岸冬日晚归","f":"七言律诗","c":["白塔高标射紫霞，乌栖宫树客投家。","烧香人拜弯弓月，穿市儿携剪彩花。","苜蓿地眠朝退马，蒲桃园隔宴回车。","人生要纵长安眼，何事能容便面遮。"]},{"t":"闰月五日即事","f":"七言律诗","c":["皇都万家欲何往，信马悠悠成独行。","击缆桥边春水急，吹笙楼外暮云平。","金丝柳弱窗临道，羊角风高尘过城。","取次韶华堪寓目，诗情饮兴一时生。"]},{"t":"寄题涔河石桥（河在澧州北四十里实往来孔道州人谢氏叠石作桥壮丽宏阔予自延祐以来凡八过其上慨念行役之苦为之惘然）","f":"七言古诗","c":["湾水溶溶漾碧虚，白虹高偃接云衢。","深春曲岸栽杨柳，落日□□□□□。","□□□□□□□，□□□□□□□。","□□□□含毫士，莫画寒江待渡图。"]},{"t":"秋思书将陵驿（馆伴安南国使还鄂）","f":"七言律诗","c":["斜阳催出凤皇城，津鼓声沉夜橹鸣。","海口风来吹酒醒，漳滨叶落唤愁生。","望深夕浦苍烟暗，梦入秋闺素月倾。","况是潘郎年纪到，二毛侵鬓不须惊。"]},{"t":"秋浦夜泊忆诚夫兵曹兄","f":"七言律诗","c":["悠悠旌旆驻郊亭，车马东门劳送行。","衔命但知谈笑乐，趣装方动别离情。","千山万山风月恨，十家五家砧杵声。","惆怅粉闱人下马，碧窗谁与对书檠。"]},{"t":"送哈必齐文苑佥宪浙西","f":"七言律诗","c":["五云仙佩厌朝鸡，抖擞春衣著绣衣。","陌上好花晴羃䍥，津头行客路逶迤。","杨梅佐酒火实粲，鲈鱼作脍银丝肥。","共道莫教辜负口，不知冰檗可充饥。"]},{"t":"双清亭春日独坐（时张为都水经历双清幕府名也）","f":"七言律诗","c":["帝城何处不红尘，小海危亭独可人。","笭箵舟航浮上闸，笙歌池馆接西津。","恩波浴鹭连洲暖，宫树啼莺隔岸春。","不用鞭笞了官事，笑谈容得幕中宾。"]},{"t":"二月二十二日野寺哭张仲容","f":"七言律诗","c":["身前谁不羡词华，水散沦漪日散霞。","仙桂无缘空种树，幽兰有种自生芽。","泪飘旧殡棠梨叶，酒入荒台野荠花。","最是相知呜咽处，洛中松柏渺天涯。"]},{"t":"送张孟功江淮觐省就赴河南幕","f":"七言律诗","c":["清时郎选重华年，英妙如君众口怜。","霍霍宝刀新试刃，泠泠瑶瑟旧调弦。","思亲将捧白鸠杖，去国还浮画鹢船。","淮浦汴堤俱好在，吟诗仍似水云天。"]},{"t":"送贡泰甫还江东","f":"七言律诗","c":["河流欲冰燕雁号，仆夫出门具吴舠。","三年游子住京国，一日念母还江皋。","才名岂藉功名重，词气终随意气高。","欲识别君情缱绻，临岐持赠紫丝绦。"]},{"t":"沙垡拜扫","f":"七言律诗","c":["风花寒食旧城陬，路指湾碜思致幽。","沙陇致钱买鼢鼠，郊扉掷果调狝猴。","辛夷已受园丁献，秾李尤烦步卒偷。","自是词人多乐事，繁华那识抱官囚。"]},{"t":"春暮双清亭小酌怀张孟功","f":"七言律诗","c":["吏退公庭雁鹜行，持杯暂对水云乡。","山开罨画涵晴影，花落胭脂漾晚香。","酒帜隔津标柳陌，渔舟避浪向蒲塘。","怀人不得同相赏，空赋《停云》第二章。"]},{"t":"晓自宦者门入院马上口占","f":"七言律诗","c":["缭垣齐拱禁门高，别院斜连御水遥。","芳草有情生广掖，垂杨无力倚危桥。","承宣白面风标俊，入内华裾意气骄。","么么词臣不通籍，却疑宫阙在璇霄。"]},{"t":"病暍柬王君实太博","f":"七言律诗","c":["卧病三日如三秋，时见谢程苏孟俦。","环堵自疑溟涨外，高居独在阆山头。","医师胗视投苓术，文友过从遗脯脩。","独怪新除齐博士，不来相问负薪忧。"]},{"t":"送道士李希白还山","f":"七言律诗","c":["洞中流水五芝肥，鹤上仙人万里归。","海月伴残丹灶火，天风吹动绣云衣。","焚香秘室招王远，蹑屐名山访子微。","闻道长生有真诀，我从何处叩岩扉。"]},{"t":"和苏伯修应奉上都试院夜坐韵","f":"七言律诗","c":["八月帘帷试夜寒，诸公文酒度更阑。","然藜共喜临天禄，分芋何劳问懒残。","谁许桂枝平地折，莫将花样近来看。","主司不是冬烘者，解送宜胜十政官。"]},{"t":"送诚夫大监兄代祀海神","f":"七言律诗","c":["毳帽貂裘素绮裳，明时远致御封香。","朝端使者传天语，海上神君见火光。","万弩射潮非计策，三山湛影漫文章。","灵来细祝忧勤念，不是求仙汉武皇。"]},{"t":"送剑州任倅","f":"七言律诗","c":["爱君畴昔赋远游，志如鹏鹗横霜秋。","抱才应辟到滇海，挟策赴调趋皇州。","蜀山秦树有德色，猿声鸟道无羁愁。","里中同舍不俶傥，坐守尘编空白头。"]},{"t":"咏御沟","f":"七言古诗","c":["决决穿云出涧初，千回百折到皇居。","行人不敢来饮马，稚子时能坐钓鱼。","内史府前晴滉瀁，云岩观后晚舒徐。","波漫略彴通丹禁，风飏辎軿映画裾。","三月霏烟著杨柳，九秋凉露泣芙蕖。","荒唐莫说流红怨，自是清涟解起予。"]},{"t":"送益阳州守额森哈雅（楚武定公阿尔哈雅之孙由宿卫初官）","f":"七言律诗","c":["龙节光临泽国遥，凤毛声振相门高。","朝辞阙陛香凝袖，暮饯邮亭酒污袍。","我爱甘棠留楚甸，谁怜楚雁集江皋。","一州如斗君休薄，考最犹能张尔曹。"]},{"t":"送贾孟善闽浙觐省遂奉父之官淮安","f":"七言律诗","c":["浮云一昔凉风起，游子匆匆买去舟。","喜奉严君辞远徼，不因作客别神州。","白蘋漠漠吴江岸，红树萧萧楚驿楼。","总是停桡捧觞处，知君无复有离愁。"]},{"t":"次韵诚夫兄丽正门外晚归","f":"七言律诗","c":["碧霄云物献诗题，双阙西边日驭低。","弦月弯环城上塔，锦霞鲜丽水南堤。","仙郎下直辞鸡树，猎骑收围撤兔蹄。","争笑閒身空七尺，不因鼕鼓卧幽栖。"]},{"t":"柏堂（刘母熊氏三十而寡不嫁其子观作堂名柏以奉之）","f":"七言律诗","c":["到处慈闱总树萱，君家庭院拥苍官。","心非红紫争春意，人似青葱耐岁寒。","锦帐罗襦秋拆凤，云窗月户晓栖鸾。","阶墀更有芝兰在，掩映浓阴十亩宽。"]},{"t":"南宁彭使君重建东坡载酒堂（儋州）","f":"七言律诗","c":["椰叶榔花映祠宇，椒浆桂酒蕙肴蒸。","古人不作千年恨，遗迹犹存百代徵。","魂魄何须归玉局，是非从此见金陵。","使君作室吾侪咏，一笑俱成附骥蝇。"]},{"t":"苏伯脩脩撰分院滦阳众仲（陈）君实（王）有诗送行读之洒然动人清兴走笔拟之","f":"七言律诗","c":["桑乾居庸南北京，崤山涧水相送迎。","羡君于兹三扈从，怜我不得一经行。","到时文酒度长昼，去日车马奔新晴。","鳌峰清语应见念，使仆鄙吝心中萌。"]},{"t":"琴士项崇节还新安其人居京师七年尝为威顺王及鲁国长主琴","f":"七言律诗","c":["调弦理曲世滔滔，百代斜川鉴识高。","有耳唯聪广陵散，无生不奏郁轮袍。","长安米索尘凝席，千里莼香月满舠。","忍道醉眠卿且去，玉徽明日楚江皋。"]},{"t":"早春马上即景书怀呈张孟功左司","f":"七言律诗","c":["日日骑马到西城，年来竟无清兴生。","冰潭照影觉形秽，云岫对人增眼明。","墨客词流惊邂逅，玉珂香毂恼逢迎。","凤池赖有知音客，一曲阳春为寄声。"]},{"t":"欧阳南阳还临江便道之官庐陵幕府（前翰林检阅抚州录判）","f":"七言律诗","c":["东观玉堂如积薪，十年补外空劳神。","红尘赤日能败兴，白鹭沧洲却可人。","相阁老槐涵墨沼，官亭新柳送车轮。","扁舟三月桃花浪，归及临江江上春。"]},{"t":"送李彦方福建宪副","f":"七言律诗","c":["绣衣乘遽度闽关，回望皇州紫气间。","辍直暂勤安赤子，临岐谁敢叹苍颜。","陛辞此日严将指，疏奏明年早赐环。","自是轺车不游览，往来多驻武夷山。"]},{"t":"道士王用亨父母高年作寿庆堂其上世蜀人仕宋今居江东","f":"七言律诗","c":["云锦溪头小有天，崇文宫畔地行仙。","故家乔木三千里，流水桃花五百年。","云液养龄春潋滟，霞衣上寿晚翩跹。","山中玉斧传真诀，应向高堂说又玄。"]},{"t":"暇日小集项鍊师丹房（鍊师字子虚）","f":"七言律诗","c":["新秋道院凉如水，载酒幽人对绿莎。","移榻小窗从啸咏，抄诗别馆尽经过。","劳生不解谈丹鼎，明日堪怜动玉珂。","吟罢自惭题字恶，定应无计换群鹅。"]},{"t":"和孟景章早秋即事韵","f":"七言律诗","c":["葱茏仙桂压勾栏，月下婆娑玉臂寒。","荷榭有风纨扇歇，醉乡无暑蔗浆残。","银灯光散填河鹊，粉袖香销舞镜鸾。","惆怅边衣何日就，锦书同附劝加餐。"]},{"t":"李良臣之睢阳别业为其考平叔公作家庙予校书时李为秘卿","f":"七言律诗","c":["忆昔青衫典校时，尊翁作监鬓垂丝。","蓬山风月谁能记，蒿里衣冠我独悲。","黑壤禾麻存别墅，素帷香火待佳儿。","旧僚犹有丹铅笔，试撰丽牲第二碑。"]},{"t":"送艺文令史宋子与驿召欧阳原功太监湘中便道过家觐省兼简吴彦晖徵君内翰周子嘉省郎","f":"七言律诗","c":["风雪闭门贫病婴，开门南去惬我情。","万里独游旧官长，十年一拜贤父兄。","征路快驰宛騕袅，归期应及闰清明。","梁园楚岸春俱好，一访相知为寄声。"]},{"t":"江西袁庆远由郡博士为幕职再调潮州路经历徵诗送行","f":"七言古诗","c":["长松磥砢出霜林，不分儒官久陆沈。","岭外官资云路快，城南祖帐雪泥深。","红莲绿水无多事，翡翠明珠肯动心。","莫道皇都□□□，□□□□□□□。"]},{"t":"南岳李炼师所居号盘中","f":"七言律诗","c":["南岳崚嶒倚太空，盘中胜地著渠侬。","烟霞近接朱陵洞，雷雨潜通天柱峰。","仙境得名符古昔，道人无事养疏慵。","他年准拟寻松鹤，归日应能借竹笼。"]},{"t":"送君则林倅南还辛酉登科今为京尹主文","f":"七言律诗","c":["经笥便便玉价高，帝城十载屡游遨。","月中前度攀丹桂，天上今年种碧桃。","燕市风尘情浩浩，吴帆烟水兴滔滔。","仙舟幸有金华客，共与哦诗饮浊醪。"]},{"t":"闰三月七日城西访友不遇马上口占","f":"七言律诗","c":["寒疾连朝避风雨，今晨一出复何如。","扣门投刺意不惬，上马逢人情有馀。","饥鹤啄虫行广陌，垂杨飘絮汎污渠。","暂经马市缁尘满，归去蓬窗理旧书。"]},{"t":"和杜德常万岁山暮春","f":"七言古诗","c":["雾杳云深日驭西，红稀绿暗闹黄鹂。","双娥有泪仍啼竹，四老无情谩采芝。","游冶喜逢三月闰，芳菲空度一春迟。","谁家甲第歌声咽，何处名园舞袖垂。","祇有情怀似中酒，那能心绪及游丝。","少年笑我真痴绝，一日閒愁十二时。"]},{"t":"追赋苑主事南野亭（丽正门外）","f":"七言律诗","c":["女墙不隔凤城春，柳色危亭枕水滨。","夜墄松风吹几杖，晓阑花露湿衣巾。","西邻池馆存碑石，东里园林换主人。","得似夫君能旷达，百壶清酒日娱宾。"]},{"t":"送崔时敏司狱省母汴中兼寄吴彦辉（六月一日）","f":"七言律诗","c":["万态峰前望白云，暂因王事问晨昏。","渡头横济瓜蔓水，归骑直趋酸枣门。","阿母慈颜深有喜，宁馨阴德果无冤。","故人跂脚临樽俎，为说相思入梦魂。"]},{"t":"端午日雨霁暂出齐化门回入城遥面京西诸山及市肆风景追忆延祐六年六月廿有二日侍诚夫尚书兄初自江南还都亦经此路仍值雨晴今十有五年矣感念畴昔因赋此诗","f":"七言律诗","c":["官柳垂阴霁景鲜，忆携家具过通廛。","雕盘粔籹映珠幰，绣陌骅骝辉锦鞯。","上国繁华过陕洛，中朝文物胜开天。","由来几度南柯梦，惟有青山似昔年。"]},{"t":"柳人王道原游吴楚至京师凡二十馀年著春秋义成书除韶州路教授","f":"七言律诗","c":["方州一士耻孤陋，老大挐舟辞楚乡。","万里周流踪迹远，半生著述鬓毛苍。","侯门久客公车荐，驿路荣归祖席张。","到日里闾争馈贺，儒冠稽古动辉光。"]},{"t":"直沽夜兴（元统癸酉八月南使江浙）","f":"七言律诗","c":["戍鼓声催夕照低，蒹葭杨柳澹烟微。","偶因海浦听吹篴，却忆京城闻捣衣。","恋阙岂无情戚戚，别家那有思依依。","传闻大驾还都近，怪得寒风凛夕威。"]},{"t":"东冈崇恩寺晚酌其僧一峰求诗","f":"七言律诗","c":["山门杉桧碧萧森，步屧回廊一径深。","罢酒长风来北渚，按歌明月出东林。","幽轩晚立云容湿，高阁晴登海气侵。","忽报寒沟潮信到，可能重听颍师琴。"]},{"t":"过馀姚寄贾治安同知","f":"七言律诗","c":["秋深持节下銮坡，吴越风烟入浩歌。","溪水通桥松作窦，山云收雨石为窝。","避泥骄马哺寒草，过陇饥牛齧早禾。","别驾归来应笑我，驿程何事苦吟哦。"]},{"t":"庆元书事","f":"七言律诗","c":["莺脰湖平好看山，鲒踦亭远莫凭阑。","帽沾江雨晓须湿，袖举海风秋臂寒。","天上仙槎来八月，云边商舶去三韩。","蓬莱更访长生药，却拟乘桴事不难。"]},{"t":"台州郡治后山亭留饮席上走笔","f":"七言律诗","c":["孟冬短日到台州，胜境喜遇都贤侯。","眼前丘壑太岑蔚，阁后台榭仍风流。","巾子峰高晓色近，净香亭小寒光浮。","徜徉尽可留朔客，谈笑不必存吴讴。"]},{"t":"永嘉江心寺留题","f":"七言律诗","c":["隔江孤屿敞空门，不似山林不似村。","双塔昼深樟树影，半阶寒沁海潮痕。","连城客到诗常满，别岛僧回粥尚温。","欲寄微躯恨无策，暂时相赏慰羁魂。"]},{"t":"福建道中","f":"七言律诗","c":["北人不惯住炎方，英簜函边药裹香。","鼻到崇安试苏合，舌过南剑渍槟榔。","朝寒命酒资调护，昼暖披襟恐中伤。","共喜我来当十月，肩舆犹憩午阴凉。"]},{"t":"赠任大正御史于福州","f":"七言律诗","c":["十月一别太契阔，两月仍得相逢三。","世事茫茫不可料，交情翕翕谁能谙。","姑苏台前秋草远，浙江亭下寒云酣。","冬深却恐霜威重，后会不得同清谈。"]},{"t":"马伯诚（彦恂）以缮写经世大典成书授左卫教授须次暂还吴兴","f":"七言律诗","c":["几年京国养疏慵，诗似朝霞气似虹。","天上书藏群玉府，日边人访水晶宫。","唐朝富丽词臣盛，汉代隆平赋客工。","政好清明事铅椠，重来摛藻颂无穷。"]},{"t":"高丽人李谷字中甫元统元年登乙科为翰林检阅官明年被命使本国宣谕勉厉学校制书其行也赠之以诗","f":"七言律诗","c":["盖苏文后少武事，渍沟楼下有书声。","贡士来经鸭绿远，登科去被牙绯荣。","中朝分命新诏使，东人争讶旧儒生。","德音宣布声教广，遣子入学同趋京。"]},{"t":"莆田陈众仲由国子助教提学江浙","f":"七言律诗","c":["送君有情忘别恨，愧我无句摅幽怀。","固知湖山适吟啸，乃与馆阁成暌乖。","紫凤天吴存曲折，黄钟大吕变淫哇。","斯文自是专方面，犹为峨冠叹不谐。"]},{"t":"平坡访谢草池二首 其一","f":"七言律诗","c":["仙家秘馆西山隈，石磴乘马能独来。","山腰桧柏当昼暝，涧底桃杏争春开。","设棋不作空置局，贮酒常满频衔杯。","道士诵诗久成听，不知斜日下荒台。"]},{"t":"平坡访谢草池二首 其二","f":"七言律诗","c":["玉泉西畔昔惯往，卢师东边今始行。","山石荦确齧马足，树林阴翳藏禽声。","座上主人谈众妙，壁间图尽教长生。","所嗟秘境禁来往，不敢题诗留姓名。"]},{"t":"礼部主事刘文瑞父母庆八十寿","f":"七言律诗","c":["沂州老人八十强，宁馨有官居议郎。","鸾凤五华恩诰下，鱼龙百戏寿筵张。","西京牛酒春无价，南极星辰夜有光。","昨日升堂亲几杖，毫眉三寸点秋霜。"]},{"t":"新城道中雷雨喜晚晴","f":"七言律诗","c":["震霆人马俱辟易，挥鞭不复能掩聪。","枣叶沉沉过冻雨，柳陌萧萧来晚风。","失马急追怜从者，负薪徒涉念衰翁。","驿程亦有驰驱苦，犹及残阳一点中。"]},{"t":"送吕仲实佥宪广西","f":"七言律诗","c":["得官岭表众所恶，持宪广西君独荣。","士论翕翕似华衮，祖道粲粲皆簪缨。","榕叶晓看思禁柳，杜鹃晨听忆宫莺。","归来铁面如红玉，不尽论思献纳情。"]},{"t":"鉴湖水送乌希说（希说以至元丙子夏由史属代祀北岳济渎南至会稽腊残求赠言适笺尾腊文有鉴湖水之语遂为题赋诗饯之予以至顺癸酉使过绍兴不得一至湖上至今歉然）","f":"七言律诗","c":["鉴湖百顷生凉秋，知章陈请太白游。","子今乃能五月往，我昔不得一日留。","吴娃合曲风度舫，越女浣纱云满头。","燕赵缁尘都洗尽，荷花深处荐琼舟。"]},{"t":"送张实夫觐省回漳州","f":"七言律诗","c":["赤岭坡前春日迟，杨柳桥下暮潮低。","闽中游子歌相别，天上故人书漫题。","茉莉吹香来竹户，麇䴥作队过松畦。","良田美树还家乐，昨日青林杜宇啼。"]},{"t":"送安伯宁由大名治中赴上沔阳知府","f":"七言律诗","c":["一违鹓鹭行中去，两度江河补外行。","吏校远迎茅步市，旌麾先过汉阳城。","民间鱼稻富生理，幕下宾僚多宦情。","我亦二毛思五马，临风常为使君荣。"]},{"t":"襄阳杨万户命道士祷雨有应","f":"七言律诗","c":["雨华旧说随车降，天意曾因决狱回。","铁甲将军今祷雨，玉壶方士解呼雷。","樊城麦穗千家熟，岘首秧苗几处栽。","感应玄机有如此，辕门新政亦佳哉。"]},{"t":"左司丁贞夫号嵩岩（洛阳人）","f":"七言律诗","c":["枝峰蔓壑灿烟霞，自古神仙就作家。","天井穴深留石髓，贝多树老放瑶华。","山人索价遗踪杳，王子吹笙去路赊。","莫向风前赋招隐，紫薇花下鬓鬖髿。"]},{"t":"和王君实户部早秋巡山韵","f":"七言律诗","c":["远临辽海近军都，今代神皋异古初。","万乘省方严禁钥，千官耀武肃郊居。","祈年寺塔存唐像，利国河渠入汉书。","赖是星郎解摸写，吟馀胸次日清虚。"]},{"t":"送杨子宣尹郓城","f":"七言律诗","c":["明时作邑重优游，我为斯人抱隐忧。","巨室昂昂张虎翼，奸民濈濈沸鱼头。","朝衙召集乡三老，幕邸趋承郡督邮。","利刃往年曾一试，知君谈笑已无牛。"]},{"t":"七月望日西山即景十二韵","f":"七言古诗","c":["朔土中元展墓辰，暂时从俗出重闉。","秋光萧飒无馀暑，野色虚明不动尘。","仙馆旧时通辇路，官沟佳处似江津。","郊扉亭榭皆沽酒，石岸湾埼半鬻薪。","见寺参差多白塔，逢僧络绎尽红巾。","凫茨映草花轻小，鸿芡遮萍大叶匀。","洁白芙蕖犹是夏，淡黄杨柳不如春。","偶随渔艇方游目，忽见龙舟却怆神。","金水河宽风掠面，玉泉山暗雨催人。","马蹄不惮平芜远，鸟语常因密树频。","可惜痴顽携子侄，未能放旷会亲宾。","茫茫世网谁堪约，负郭同为学稼民。"]},{"t":"济南张侯至大二年奉御香祷旱历山舜祠雨应是年十二月也","f":"七言律诗","c":["武皇斋祓祷重瞳，近侍含香解蕴隆。","泺水气通云漠漠，绣江波合雨濛濛。","螟蝗不待逢深雪，牧守惟知问太空。","自古精诚多感格，谁云野语出齐东。"]},{"t":"送笃烈图敬夫南台御史时予居閒","f":"七言律诗","c":["一从桂苑下瀛洲，君宠难忘志未酬。","今戴豸冠辞上国，又分龙节向南州。","跛鳖应贻骐骥笑，飞鸿亦有稻粱谋。","道傍杨柳不堪折，江上梅花相忆不。"]},{"t":"先兄正献公坟所寒食自和气门归马上赋","f":"七言律诗","c":["适野襟怀自豁然，入城景物又堪怜。","御沟春水高于路，海岸风尘暗似烟。","醉客轻生驰騕袅，痴儿薄行调婵媛。","徐驱返顾西山色，自笑诗人嗜好偏。"]},{"t":"送范悦古赴江西宪掾（悦古名亭曲进士不第掾江西宪久之以诬罢去又中乡举会科场废御史辨其冤复为江西宪掾）","f":"七言律诗","c":["丹桂凋零翠柏高，吴船还又泛江涛。","鸷禽整翮仍堪击，鸥鸟忘机自不劳。","晓陌行人折杨柳，春城别馆酌蒲桃。","婵娟后夜东湖月，莫向明时叹马曹。"]},{"t":"于潜谢尧章松巢","f":"七言律诗","c":["浊世尘嚣如洚水，巢居故向万松间。","下窥震泽三江浪，高揖钱唐九里山。","虎魄糇粮应可畜，兔丝牖户若为攀。","杏梁桂柱长安陌，不直危枝一解颜。"]},{"t":"临安刘子简以至元二年观光京师明年告归作诗送之","f":"七言律诗","c":["文昌殿古黑云低，光范门深白日迷。","逢掖有时甘引去，丈夫何事苦分携。","上林春去莺犹啭，南国晨征马不嘶。","多少忧端兼别恨，烟江何处觅缄题。"]},{"t":"李重山都司号梅庭","f":"七言律诗","c":["爱梅大是清绝伦，置之庭除尤可人。","寒影夜移青玉案，暗香晨裛白纶巾。","陇头江上徒千里，月地云阶少四邻。","更道广平心铁石，可无新语慰花神。"]},{"t":"昌平县廨和解之昂御史时巡历京畿东道","f":"七言律诗","c":["向来按部指秋期，子月登车我独迟。","双塔道傍观俗处，百泉庄上恤灾时。","烟昏导骑摇箶簶，灯暗痴童下扊扅。","不听讴歌听愁叹，何心工和壁间辞。"]},{"t":"漷州除夕忆京师诸公奉寄","f":"曲","c":["岂不怀归畏简书，无人袒跣斗樗蒲。","那知年后得春气，谩向天边瞻斗枢。","一榻衾裯明榾柮，五更箫鼓蹋?毹。","屠苏诘旦谁先饮，鹓鹭黎明众共趋。","纤手菜丝应不送，端门柑宴肯相须。","凤城多少藏阄会，一样银灯惜岁徂。"]},{"t":"元日又怀诸公自次韵","f":"曲","c":["揽辔寒郊理簿书，明时不用伏青蒲。","喜闻蓂荚颁庭陛，惊见桃符映户枢。","长乐晓钟红叱拨，大明春殿紫?毹。","六街车马鱼鳞集，百弼衣冠鸟翼趋。","幕省贵人辞琐闼，晴窗独客揽髭须。","暮年勋业归公等，莫叹红尘急景徂。"]},{"t":"六日雨中闻诏赦将至复次韵","f":"曲","c":["一札飞来宽大书，潞阳归骑踏菅蒲。","九天雨露开元化，列宿光芒拱北枢。","时近春盘传饼餤，云昏午枕卧?毹。","连朝吏士开尊饮，旦日官僚秉笏趋。","葛亮有言垂往昔，阳球兴叹失斯须。","传闻几处圜扉静，谳狱无劳趁暑徂。"]},{"t":"淮南潘子素持吴□唱酬诗一卷见示偶七夕久坐书怀次韵寄卷中诸友","f":"七言律诗","c":["悔抛蕙帐下岩阿，老鬓飘萧半□窝。","涉世情怀今日薄，立朝勋业古人多。","静闻珠露零丹桂，清爱银湾漾白波。","良夜赏心难寄远，定应同调制吴歌。"]},{"t":"予以延祐元年从先兄正献公入汴始识彦辉吴徵君是岁故中丞马公伯庸今翰林学士谢公敬德国子博士王君师鲁乡贡河南行省迄今二十五年予再以按行至汴居监察行院去徵君所居仅半里犹以公事未毕尚迟于请见时马公亦薨谢王在馆阁感念存殁赋唐律一首先遣持遗徵君正之（至元四年戊寅）","f":"七言律诗","c":["二十年前入汴州，梵王仙馆涉春秋。","家家庭院森湖玉，处处帘栊映海榴。","金马石渠伤远别，丘山华屋动新愁。","谁怜闭著车中妇，犹望元龙百尺楼。"]},{"t":"仲宣楼登眺","f":"七言律诗","c":["国家全盛似金瓯，江汉澄清控上游。","帝子几时临北渚，庾公何处倚南楼。","云来巫峡祠空在，霜落荆门树自稠。","持节重来纾四望，孤怀别有凭阑愁。"]},{"t":"左司李重贤远清亭","f":"七言律诗","c":["亭下盆池漾绿光，红妆翠盖似横塘。","不须玉井十丈藕，自有鉴湖五月凉。","座上莫闻金鼎篆，尊前仍注碧兰香。","主人逸兴幽人句，多幸俱留百世芳。"]},{"t":"武昌近城阻风雨三日不得到城下遣兴一首山南佥宪之行","f":"七言律诗","c":["五月江风多自南，停舟滞雨兴难堪。","吕公矶送惊心浪，大别山凝扑面岚。","北海酒尊空已久，善和书册远谁探。","妻儿不解穷通理，看挂明朝十日帆。"]},{"t":"当阳道中（录囚襄阳）","f":"七言律诗","c":["路指沮漳散马蹄，园林芳润称幽栖。","浅山有势藏杉冢，细水无声过稻畦。","病暍久忘河朔饮，贪眠常恶汝南鸡。","莫嗟六辔多匆遽，犹暇寻诗泚笔题。"]},{"t":"山中逢武当冯尹景仲入京以诗送之","f":"七言律诗","c":["卓午山头树影高，岂期多幸此相遭。","久嗟寒雁迷书问，共讶秋霜点鬓毛。","张绪犹如少年柳，刘郎重看旧时桃。","故人侍直金銮密，应向明时诵拔茅。"]},{"t":"过马嘶山留题寺中","f":"七言律诗","c":["鸡鸣山接马嘶山，万壑晴云井底看。","湍涧萦纡五十度，石梯荦确百千盘。","光华固有周原重，险阻其如蜀道难。","题罢新诗动高兴，五湖何处水云宽。"]},{"t":"山中漫赋题□平官舍","f":"七言律诗","c":["绣衣不为吟哦出，诗料纵横簇眼前。","岩鸟杂鸣诸部乐，石苔乱布五铢钱。","焚香乞水痴求雨，刻木通泉巧溉田。","尸位空言无所补，寓情托物亦犹贤。"]},{"t":"七月三日喜至郧县山行兼旬至此始出","f":"七言律诗","c":["稻花香里过琳宫，一舸斜阳汉水东。","下马已辞山巀嶪，开轩仍见竹葱茏。","画檐不碍迎霜叶，玉宇频来处暑风。","童御无知友朋远，满襟幽思与谁同。"]},{"t":"太公遇文王图","f":"七言律诗","c":["狂王丧心醉其上，老叟避世居渭滨。","出猎初非取兽意，垂钩岂是求鱼人。","千年茅土有终始，一时际遇无比伦。","韩彭乌合成俎醢，三顾犹堪继后尘。"]},{"t":"爱竹（所寓官舍有竹数丛）","f":"七言律诗","c":["京华廿载看画竹，今见群笋森阶前。","锦绷初苞已挺特，筠粉半落尤清妍。","何人炎歊弄团扇，有客风露为华筵。","平安不待纲维报，轩车未膏日周旋。"]},{"t":"章台寺留题","f":"七言律诗","c":["高林过雨晓苍苍，水木清华古道场。","亭子是谁开四五，招提缘此异寻常。","风声萧飒群松翠，日气醺酣二麦黄。","墟墓令人不怡悦，何妨却茗进琼觞。"]},{"t":"荆门州治后惠养亭留题（亭在山麓）","f":"七言律诗","c":["南直江城近可通，东连郢树暗无穷。","台高先得瀛洲月，地陕难乘阆苑风。","云射晴霞红烂熳，山经冻雨翠溟濛。","惟馀蒙惠泉头路，犹在探奇梦寐中。"]},{"t":"雨后利阳道中","f":"七言律诗","c":["二年四过山前路，三度值雨难攀跻。","最怜绿水注深堰，不惜青骢污浊泥。","泽畔藕花怡旅况，陇头禾穗慰妻啼。","丰登已是囊中物，易得新诗扫壁题。"]},{"t":"寄贺徐复初江浙检校","f":"七言律诗","c":["故人家住黄鹤楼，三年不到鹦鹉洲。","红尘面目事京局，清夜梦寐思林丘。","耸壑昂霄今老大，唾壶谈麈旧风流。","传闻调官赴吴会，我为终夕喜不休。"]},{"t":"寄慰翰林谢敬德学士","f":"七言律诗","c":["故人昔佐湘阴州，召赴馆阁二十秋。","高文大册有清誉，赋诗酌酒无白头。","荷橐两京久劳瘁，行年六帙空优游。","一官不调竟无愠，我为终夕闷不休。"]},{"t":"夷陵晚望峡口即景感怀十四韵（按部峡州）","f":"七言古诗","c":["一握青天万丈崖，长江束缚此中来。","山形连导岷峨脉，水戒明徵滟滪堆。","疏凿神功思禹载，战争遗迹叹秦灰。","涛翻澎湃朝喷雪，滩激砰訇夜吼雷。","割据每能资霸业，弃捐亦复到奴才。","乾坤设险华夷判，名利轻生肝胆摧。","□匠操篙要厚赂，波神赐珓享冥财。","儿时梦寐光阴速，客里登临怀抱开。","红叶黄花为谁好，玄猿白雁有馀哀。","百川逝水流无极，孤鸟长空去不回。","昨日舟航辞白帝，当年云雨下阳台。","竹枝歌里堪容与，人鲊瓮边难溯洄。","千里画图真妙甚，醉翁文字亦高哉。","远游政到离骚国，赋罢招魂试举杯。"]},{"t":"远安留题","f":"七言律诗","c":["楚边穷处蜀分疆，小邑几为山所藏。","放火种畬今得趣，辟兵凿穴旧堪伤。","每因岩壑起云气，少见日月开晴光。","我来问俗聊弭节，深林不敢久徜徉。"]},{"t":"目送","f":"七言律诗","c":["目送孤鸿欲灭时，幽人怀抱有谁知。","茫茫往古青山在，亹亹来今白发垂。","陶令忘忧多嗜酒，少陵逸兴只吟诗。","惟馀安乐窝中老，笑俯尘寰看大棋。"]},{"t":"孝感纪异诗","f":"七言律诗","c":["河东老父雪盈头，捧檄儿郎事远游。","莫道襟怀如陆绩，直疑魂魄似黔娄。","荐新礼在情相称，陟岵诗成泪莫收。","理气相关有如此，不须身外强推求。"]},{"t":"逸老堂（九老仙都宫唐真人）","f":"七言律诗","c":["临水垂杨绕院松，高堂仙客养疏慵。","道存柱史五千字，心在蓬莱第一峰。","未可逍遥空看鹤，不妨劳动急呼龙。","我惭不得金丹术，尘满衣襟抗俗容。"]},{"t":"江上阻风（自山南还都）","f":"七言律诗","c":["昨日痴坐庾公楼，今晨祇过桑落洲。","连朝巨浪高似屋，万斛大舸轻于鸥。","青山两岸不可画，绿酒一尊能解忧。","行年五十倦頫仰，愁见京尘扑马头。"]},{"t":"高丽僧式上人游两浙江会提学黄晋卿句曲外史茅山张伯雨好事者绘为文会图","f":"七言律诗","c":["文章释老谁争雄，昔人三语将无同。","已公茅屋见新句，匡庐莲社追随风。","名胜绝怜留翰墨，笑谈莫谓变虚空。","鸡林到日传相诧，杖锦归来未是穷。"]},{"t":"吏部侍郎杜弘道号西岩野逸（保下人）","f":"七言律诗","c":["万古西岩好地形，凭高四望接英灵。","太行王屋千峰雪，碣石居庸一带青。","山径缘云通略彴，野泉流月度坳陉。","主人固有幽栖志，同送孤鸿入杳冥。"]},{"t":"送钱思复下第还杭州分得秋字","f":"七言律诗","c":["陌上王孙壮气遒，交锋劘垒在朝头。","拟来披腹排阊阖，空使乘槎犯斗牛。","蟾府丹香应少待，凤梭花样肯旁搜。","冬烘却是居停主，江上芙蓉莫怨秋。"]},{"t":"正月二十六日监中习仪即景书怀","f":"七言律诗","c":["椒觞献岁暖如蒸，收灯前后不复晴。","风色料峭雪欲落，云阴晃漾日半明。","四郊未有花柳意，六馆但闻弦诵声。","城南三月牡丹发，莫遣白头愁里生。"]},{"t":"阳明楼（崇真万寿宫道士丁元善）","f":"七言律诗","c":["道士由来不火食，仙人况复好楼居。","镜湖秋水望不极，禹穴晴岚浓有馀。","岩下茯苓供采药，窗前柿叶待临书。","紫鸾玄鹤应相迟，会碾飙轮赴碧虚。"]},{"t":"初秋苦雨","f":"七言律诗","c":["白潦玄云净影涵，漏天奚止说西南。","毁垣到处疏篱当，支厦何年大木堪。","憭慄未须悲宋玉，沉吟漫尔忆岑参。","无穷世故灵台小，华发萧骚不满簪。"]},{"t":"济南张智夫八十诗云庄","f":"七言律诗","c":["闻道仙翁乐事多，几曾衰槁坐鸡窝。","华峰月冷云横久，趵突泉甘酒热过。","少壮争询三叟寿，光阴未尽百年歌。","太平生长仍终老，笑杀行兵马伏波。"]},{"t":"送叶仲舆令尹赴上盐场司令","f":"七言律诗","c":["砉砉牛刀新发硎，闽中作宰慰编氓。","石崖镌颂不尽意，樟木刻祠方称情。","丹诏十行求善政，玉堂一老有诸生。","牢盆又比爰书苦，谁为长林叹不平。"]},{"t":"次韵苏伯修侍御樊川游春 其一","f":"七言律诗","c":["霄汉春深鬓有华，离愁望眼一时赊。","裁诗不待灞桥雪，醉酒莫嗔韦曲花。","渭北树阴晴䨴郁，终南云气暮周遮。","帝城咫尺居庸翠，谁道痴呆不念家。"]},{"t":"次韵苏伯修侍御樊川游春 其二","f":"七言律诗","c":["我别长安四见秋，当时风景如梦游。","含元殿下麦初老，兴庆池头波欲流。","三春柳荫北轩井，千技柏暗南坊丘。","而今祇是成追忆，畴昔无因得久留。"]},{"t":"送孙引进湖州同知","f":"七言律诗","c":["绵蕝何须鲁两生，紫髯落落称华缨。","泰坛导驾开徐步，文陛催班引大声。","一代世官周礼重，九重增秩汉恩荣。","水晶宫里蘋风起，北望红云是帝城。"]},{"t":"张女挽诗","f":"七言律诗","c":["三生常侍玉宸君，想像文姬一样人。","露气清凝仙掌夜，天葩秀吐上林春。","木兰歌怨征行苦，柳絮才高老大身。","却是贞魂埋不得，綵鸾同与驾飙轮。"]},{"t":"台州应翁八十号希有斋","f":"七言律诗","c":["老人须发如秋霜，深居海滨乐且康。","寿考何须菊潭水，神仙只在梅林阳。","五铢衣薄肌骨爽，九节杖轻行步彊。","我欲相期广莫野，痛饮共到无何乡。"]},{"t":"告中寒食感事书怀（至正五年作时奉敕纂修宋史）","f":"七言律诗","c":["少日读书今白头，半生窃禄不知休。","讲筵深愧程杨学，史稿重遗班马羞。","多事愁怀苦于病，久寒春意淡如秋。","江南烟雨京华月，閒倚晴窗忆旧游。"]},{"t":"婺源程弘道教经堂（其子名允时）","f":"七言律诗","c":["圣训行天似日星，秦时晦日汉时明。","半山老人坏正道，紫阳夫子集大成。","孝经尚欲化遐郡，论语还堪致太平。","他日儿曹心醉后，我知不羡遗金籯。"]},{"t":"送诗僧泐季潭江南","f":"七言律诗","c":["方外何尝浪得名，士林高处学迁莺。","远公能重陶元亮，老汉常陪石曼卿。","日暮碧云追雅致，阳春白雪有馀声。","江南烟雨楼台好，尽意推敲不用惊。"]},{"t":"纪行述怀（有清溪稿扈从上京之行）","f":"七言律诗","c":["陪扈滦京愧未曾，马瘏儿病苦凌兢。","龙门湍息山陉雪，偏岭风凄石濑冰。","倏忽雨旸天叵测，迂疏道路事难凭。","侍臣争笑冯唐老，不向明时献技能。"]},{"t":"冻雨晚晴自成物门归院马上口占","f":"七言律诗","c":["碧山缭绕昼阴垂，云湿宫城雨湿衣。","芳草远含春意态，微阳閒弄晚光辉。","滦河委曲经千里，魏阙嵯峨壮九围。","满目郁葱佳气在，莫从陈迹访依稀。"]},{"t":"送王仲方淮东廉使","f":"七言律诗","c":["薰风殿阁舜琴张，睿念求贤治远方。","滦水绣衣朝浥雨，淮壖白简夏飞霜。","九天星直三台近，六辔路增千里长。","拔薤抱儿君素志，琼花开处煮茶香。"]},{"t":"宣文博士周伯温世家鄱阳别墅有坡先世树梅千株其郡志载宋时守居多梅有亭名玉雪坡伯温爱之亦以名其亭","f":"七言律诗","c":["薄俗妖妍莫竞春，万株清气照乾坤。","神仙身在藐姑射，居士梦入罗浮村。","写物更无和靖句，怀贤宜占谢公墩。","久知佳境因人胜，何必登亭对酒尊。"]},{"t":"喜归大都玉署","f":"七言律诗","c":["玉署萧然一事无，漫陪銮驭到行都。","白痴祇对鳌峰石，清供唯观海月图。","野疃有情开紫菊，禁园无数列黄榆。","轮蹄迫塞通衢隘，明日扬鞭出坦途。"]},{"t":"送赵大本赴西台御史分得尘字","f":"七言律诗","c":["释褐由来第几春，綵衣重袭绣衣新。","地连羌僰民皆幸，天助风霜笔有神。","骢马岂期多避路，都亭无用苦埋轮。","致君勋业争先睹，应叹遗贤满后尘。"]},{"t":"送王彬叔赴西书吏","f":"七言律诗","c":["庐江宪府昔曾经，作掾闻君有此行。","灊皖诸山倚天峻，淮淝二水得霜清。","苍鹰自向秋风击，丹凤还依晓日鸣。","简牍贤劳好珍重，灵台明处是云程。"]},{"t":"宣城黄山汪公仲云松楼","f":"七言律诗","c":["江东胜士高起楼，坐对万松云气浮。","流水桃花非世外，小山丛桂为谁留。","繁华竞逐移春槛，货殖空名千户侯。","唯有清标供抚玩，栋梁霖雨付悠悠。"]},{"t":"早春遣怀","f":"七言律诗","c":["百尺危桥路稍平，新年邂逅一经行。","池台半入荒残景，觞咏浑非少壮情。","祇见晴波群浴马，未闻芳树乱啼莺。","相亲赖有西山色，常似连屏照凤城。"]},{"t":"张德谦寿松石","f":"七言律诗","c":["木精山骨旧相亲，鬼匠临摹大逼真。","霜老苍龙潜委蜕，月明寒玉暗传神。","丘园预卜长年兆，苔藓难埋后夜春。","信是坚贞同气类，望秋蒲柳谩成尘。"]},{"t":"吕仙亭","f":"七言绝句","c":["物外烟霞属胜游，有时长啸海门秋。","岳阳楼上题诗了，惭愧人间韩伯休。"]},{"t":"一絇丝（张昌仪兄弟恃易之昌宗之宠所居奢溢有人题其门曰一絇丝能得几日络昌仪遽书其下云一日即足后祸及）","f":"七言绝句","c":["清河桑少蚕拍簇，曳雪牵霜不盈握。","西风吹落红莲花，败篗尘埃弃墙角。"]},{"t":"书宜都内人传后（二首） 其一","f":"七言绝句","c":["痴绝庐陵不保身，忽从妇口议天伦。","鸾台凤阁须眉者，谁识当时有内人。"]},{"t":"书宜都内人传后（二首） 其二","f":"七言绝句","c":["绣帷春色久徘徊，檀机傍边说祸胎。","一笑诗人漫怀古，梦中曾见内人来。"]},{"t":"朝元宫杂诗三首（延祐丙辰在汴作） 其一","f":"七言绝句","c":["飞仙堂前深草青，葵花榴花红重轻。","幽鸟飞来弱枝动，泓泓残雨夕阳明。"]},{"t":"朝元宫杂诗三首（延祐丙辰在汴作） 其二","f":"七言绝句","c":["七真殿西开小门，此中南与书司邻。","板扉无人蝴蝶乱，细草幽花三月春。"]},{"t":"朝元宫杂诗三首（延祐丙辰在汴作） 其三","f":"七言绝句","c":["郑州车过雷■■，□墙桥上人已行。","睡眼羞明窗纸白，惊人又是石鱼声。"]},{"t":"送牛农师北上","f":"七言绝句","c":["玉带河流缘蔚蓝，君家桥北我桥南。","一谈忽作容易别，便是无情也不堪。"]},{"t":"招屈亭东酒一卮人生最苦远别离不须更折路傍柳君家门外青垂垂（招屈亭乃郡人送别之所）","f":"七言绝句","c":["阿亭学书才五经，阿孙学语才春莺。","乃翁去去莫回目，外有先生内有叔。"]},{"t":"重过江陵 其一","f":"七言绝句","c":["渚宫春水数经过，风物消沉可奈何。","闻得街头耆旧说，鲫鱼翻比昔年多。"]},{"t":"重过江陵 其二","f":"七言绝句","c":["南条山色翠微茫，映带江城冠楚乡。","杨柳两街多大宅，好教留待段文昌。"]},{"t":"送陈亨甫如湖南","f":"七言绝句","c":["莫为功名怨别离，别离何用送行诗。","沅江腊月无杨柳，聊折梅花赠一枝。"]},{"t":"次韵赋春词三首 其一","f":"七言绝句","c":["象口香消冷瑞烟，锦衾罗荐任朝眠。","一心要续怀春梦，不管啼莺绕槛前。"]},{"t":"次韵赋春词三首 其二","f":"七言绝句","c":["妆楼淡月转廊腰，晴露和春浸碧桃。","爱品凤箫腔未稳，夜天空望彩云高。"]},{"t":"次韵赋春词三首 其三","f":"七言绝句","c":["娇春杨柳暗藏鸦，掩映文窗一树花。","寒食清明都过了，悄无车马问侬家。"]},{"t":"澧阳道中春日","f":"七言绝句","c":["隔村山鸟学绵蛮，夹路溪泉响佩环。","晴日烘人透衣暖，不须春酒亦酡颜。"]},{"t":"别武陵诸友分韵得身字（延祐己未三月晦日别武陵北归）","f":"七言绝句","c":["人别江南花别春，莺莺燕燕总伤神。","旗亭酒软歌姬艳，争奈相如是病人。"]},{"t":"别后寄友","f":"七言绝句","c":["兰舟三日屈原亭，醉出南门缓辔行。","柳暗河街新月上，一场离恨不分明。"]},{"t":"舟中夜雨奇周子善","f":"七言绝句","c":["雨暗空江夜寂寥，打篷声似打芭蕉。","故人好在纱窗下，高拥银灯对小乔。"]},{"t":"漂母墓","f":"七言绝句","c":["南昌亭长木兰僧，进食英雄岂不能。","澼絖家资消几许，阿婆高冢碧崚嶒。"]},{"t":"沛中","f":"七言绝句","c":["未央宫阙锦辉煌，隆准何心恋故乡。","直到中兴守家法，年年供顿幸南阳。"]},{"t":"晚兴","f":"七言绝句","c":["紫陌归来月魄新，草深凉院掩柴门。","絺衣欲挂梧桐上，惭愧缁尘染树痕。"]},{"t":"感怀","f":"七言绝句","c":["扰扰红尘世态殊，少年空殢五车书。","才情纵解吟春草，毕竟京师不易居。"]},{"t":"初至都书金城坊所僦屋壁","f":"七言绝句","c":["士龙东头士衡西，长沙舞袖难旋转。","豪家尽有厦连云，自是诗人嫌日短。"]},{"t":"晚出都城（是年八月东之乐亭县）","f":"七言绝句","c":["风入秋罗半臂寒，紫霞赤气日光殷。","西山大是无情思，忍送巾车又出关。"]},{"t":"宿错桥","f":"七言绝句","c":["胡来城下错桥西，神树栖鸦迫暮啼。","数骑东来饮河水，一声羌管碧云低。"]},{"t":"渔阳（二首） 其一","f":"七言绝句","c":["万马纷纷动鼓鼙，三郎束手翠华西。","向来别有销兵策，莫恨青闱燕子泥。"]},{"t":"渔阳（二首） 其二","f":"七言绝句","c":["小丑从渠怨忌多，不知和解欲如何。","万几尽有关心处，却办城东热洛河。"]},{"t":"诚夫兄寄都下杂诗五首（次韵奉答予时在乐亭县） 其一","f":"七言绝句","c":["虎豹环宫守日旗，夔龙鹄立捲班迟。","明良自有赓歌咏，逢掖诸生莫献诗。"]},{"t":"诚夫兄寄都下杂诗五首（次韵奉答予时在乐亭县） 其二","f":"七言绝句","c":["凤吹龙筝楼上头，市中沽酒会英游。","狂心似火何时遂，定约春风赋御沟。"]},{"t":"诚夫兄寄都下杂诗五首（次韵奉答予时在乐亭县） 其三","f":"七言绝句","c":["玉皇端拱白云乡，扣额何时上绿章。","威凤祥麟都网尽，后人谁更说昭王。"]},{"t":"诚夫兄寄都下杂诗五首（次韵奉答予时在乐亭县） 其四","f":"七言绝句","c":["拥被巴童似猬拳，矮窗炉火夜深然。","风流张绪如杨柳，却向荒寒度半年。"]},{"t":"诚夫兄寄都下杂诗五首（次韵奉答予时在乐亭县） 其五","f":"七言绝句","c":["碎霜斜舞下遥天，透胆寒威折塞绵。","不似豪儿衣狐白，读书辛苦谩多年。"]},{"t":"忆武陵旧事（三首） 其一","f":"七言绝句","c":["咏归亭瞰武陵溪，隔岸花开雨后齐。","竹筱庄园春社散，青陵村外目平西。"]},{"t":"忆武陵旧事（三首） 其二","f":"七言绝句","c":["芙蓉如妓绕横塘，一段秋容著色妆。","犹记周郎会心处，醒时双陆醉时狂。"]},{"t":"忆武陵旧事（三首） 其三","f":"七言绝句","c":["两袖东风脸似霞，满怀红刺访侬家。","春莺错唱清平调，输却钗头缥蒂花。"]},{"t":"通州桥下见诀别者","f":"七言绝句","c":["二月五日风扬沙，潞阳河津杨柳芽。","毡车离人泣红颊，摇鞭羡我能还家。"]},{"t":"三月一日杂诗四首（延祐七年） 其一","f":"七言绝句","c":["仙龙髯堕古混台，碧籞春深花自开。","踏白马前双斧钺，路人争喜晋王来。"]},{"t":"三月一日杂诗四首（延祐七年） 其二","f":"七言绝句","c":["苑树云藏绀色鸦，綵楼昏鼓促沉霞。","分明不似鼕鼕韵，寂寞东风十万家。"]},{"t":"三月一日杂诗四首（延祐七年） 其三","f":"七言绝句","c":["柳簇红桥绿雾匀，羽林戈戟锁重闉。","朝阳空照俜仃影，长似东街碧树身。"]},{"t":"三月一日杂诗四首（延祐七年） 其四","f":"七言绝句","c":["旧时瓮城野樱桃，隈隅弄日晴树高。","游人来往不能折，烂醉来时玩碧梢。"]},{"t":"李廷圭墨","f":"七言绝句","c":["神物蟠髹麝溲煤，升元曾是进蓬莱。","玄光依旧能今日，谁信昌言己夜台。"]},{"t":"阳关图（二首） 其一","f":"七言绝句","c":["系马停车待酒阑，骊驹歌断不成欢。","凭谁说与图中客，水远山长行路难。"]},{"t":"阳关图（二首） 其二","f":"七言绝句","c":["前春别宴武陵溪，候馆垂杨暖拂堤。","忽见画图疑是梦，故人回首洞庭西。"]},{"t":"七月八日晓晴暂出丽正门外（二首） 其一","f":"七言绝句","c":["团团碧树压宫城，白凤门楣淡日明。","回首琼华仙岛上，片云犹欲妒新晴。"]},{"t":"七月八日晓晴暂出丽正门外（二首） 其二","f":"七言绝句","c":["晓凉门巷柳阴蝉，九陌晴泥著锦鞯。","到处帘栊尽相似，巧棚人静五生蔫。"]},{"t":"冬夜","f":"七言绝句","c":["纸窗如水月如冰，天际浮云罨画屏。","漏板阑珊参过午，篝灯犹诵太玄经。"]},{"t":"群蔬写生图","f":"七言绝句","c":["午衙太守杞菊赋，朝日先生苜蓿盘。","翠釜驼峰无限美，画师何事画酸寒。"]},{"t":"元夜偕二友看水灯","f":"七言绝句","c":["绿鬓相携御软风，珠尘粉雾月朦胧。","水灯浮过南桥去，却被残冰碍□红。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其一","f":"七言绝句","c":["春王朝会大明宫，祝栗鱼蛮四海同。","至治元年调玉烛，和风甘雨看年丰。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其二","f":"七言绝句","c":["晓日云冠缀綵珠，龙颜如玉映康衢。","大官门外停天驷，群辟翱翔侍步趋。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其三","f":"七言绝句","c":["黄流玉瓒荐馨香，九庙神灵降百祥。","一部云韶导仙驾，归来朝贺坐明堂。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其四","f":"七言绝句","c":["至公堂下鱼鳞屋，丽正门前蜗壳居。","三百英雄来献赋，是中应有马相如。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其五","f":"七言绝句","c":["瑶肝玉肺渥洼驹，玄圃昆崙是坦途。","暂蹶霜蹄未为失，三年奋迅碧云衢。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其六","f":"七言绝句","c":["人海茫茫万仞山，健夫争赴碧岩端。","跻攀分寸不得上，始信文场蜀道难。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其七","f":"七言绝句","c":["一念遗孤一怆然，心旌无日不悬悬。","潞阳二月河冰解，定买吴侬燕尾船。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其八","f":"七言绝句","c":["谢家择婿得逸少，温峤先酬玉镜台。","罗帐合欢犹有待，可怜孤凤意徘徊。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其九","f":"七言绝句","c":["迩来吟思浊如泥，今日酬君喜赋诗。","不识心忪并胆怯，犀珠银液竟何施。"]},{"t":"得周子善书问京师事及贱迹以绝句十首奉答 其十","f":"七言绝句","c":["汨没京尘度岁华，胸中千绪乱如麻。","南风准拟挥谈麈，剩费君家木杵茶。"]},{"t":"钱圣举山茶","f":"七言绝句","c":["丹青笔点水晶宫，为尔寒葩染淡红。","今日北人多见惯，不须和雪上屏风。"]},{"t":"雪竹白头翁横披（二首） 其一","f":"七言绝句","c":["琅玕袅袅碧云空，雪缀斜梢倚北风。","丹凤不来年岁晚，一枝聊借白头翁。"]},{"t":"雪竹白头翁横披（二首） 其二","f":"七言绝句","c":["苍衣雪颈冻难飞，寂寞寒梢独自栖。","别有春明好风景，绿杨如画乳莺啼。"]},{"t":"出京酬送别者（南游湖湘）","f":"七言绝句","c":["台笠华缨洗暗尘，都门官柳送车轮。","洛阳津吏揶揄我，不是终军等辈人。"]},{"t":"阿城","f":"七言绝句","c":["掖庭咫尺失王嫱，库吏奸因鼠粪扬。","邂逅阿城重怀古，欲从何处吊威王。"]},{"t":"小姑贤祠","f":"七言绝句","c":["离鸾别鹊两沉冥，肠断庐江焦仲卿。","不见虎丘南畔月，至今常为小姑明。"]},{"t":"舟中述怀","f":"七言绝句","c":["饭了从容瞌睡禅，诗情涩似急滩船。","吟成欲附都人卖，又恐明时不值钱。"]},{"t":"彭泽水驿嘲渊明","f":"七言绝句","c":["循资白发绾铜章，明府何心解绶忙。","今日公田多十倍，折腰儿辈亦无伤。"]},{"t":"五王博塞图","f":"七言绝句","c":["鹡鸰飞满万年枝，羯鼓声闻博塞时。","自是开元太平事，不曾闻有豆萁诗。"]},{"t":"贾傅祠堂（二首） 其一","f":"七言绝句","c":["绛灌才书汗马功，治安策里事无穷。","汉家未有停年格，一岁超迁到大中。"]},{"t":"贾傅祠堂（二首） 其二","f":"七言绝句","c":["天上银河洗甲兵，八方风雨会咸京。","洛阳年少偏多事，强说当时未太平。"]},{"t":"舟中闻笛（岳阳楼下邻舟一军将醉而吹笛爱其音韵清壮命酒赏之旦求予诗遂赋此以赠）","f":"七言绝句","c":["虬须醉倚木兰舟，不识人间出塞愁。","吹散碧云江上去，芳洲斜日自悠悠。"]},{"t":"毛女图","f":"七言绝句","c":["终南灵药可成仙，徐福空劳泛海船。","七月辒辌鲍鱼臭，不知宫女却长年。"]},{"t":"漫成","f":"七言绝句","c":["日射金堤御水明，杨花榆荚出宫城。","上林如锦春如画，却怪黄莺不解鸣。"]},{"t":"送存初宣慰湖南十首 其一","f":"七言绝句","c":["太平天子辟经筵，侧席金华引旧贤。","顿首玉皇香案底，旌麾毕竟使飘然。"]},{"t":"送存初宣慰湖南十首 其二","f":"七言绝句","c":["绿暗红稀出凤城，潞河津上酒双瓶。","湘花湘鸟凭谁报，早晚楼船过洞庭。"]},{"t":"送存初宣慰湖南十首 其三","f":"七言绝句","c":["甘棠旧树几年馀，枝叶葱茏拂月衢。","长沙耆旧如相候，先向轺车看凤雏。"]},{"t":"送存初宣慰湖南十首 其四","f":"七言绝句","c":["碧湘如镜岳如屏，赋客骚人聚德星。","况是苏仙吟咏处，高名从此竞芳馨。"]},{"t":"送存初宣慰湖南十首 其五","f":"七言绝句","c":["金貂门第黑头公，五省三台指顾中。","便拟梅花庄上隐，不应解组太匆匆。"]},{"t":"送存初宣慰湖南十首 其六","f":"七言绝句","c":["三载王城接燕谈，高斋夜坐语喃喃。","有时共对桓伊曲，一种清禅静里参。"]},{"t":"送存初宣慰湖南十首 其七","f":"七言绝句","c":["金闺朝退暮归时，指点铅华尽赋诗。","惆怅海棠花底事，有谁题咏有谁知。"]},{"t":"送存初宣慰湖南十首 其八","f":"七言绝句","c":["青霄持节镇湖山，东阁招贤事不难。","若用紫薇为幕客，常教街子报平安。"]},{"t":"送存初宣慰湖南十首 其九","f":"七言绝句","c":["花飘禁籞锦机空，人别河梁酒晕红。","送春已是情怀恶，又向残春送相公。"]},{"t":"送存初宣慰湖南十首 其十","f":"七言绝句","c":["科名自愧忝君恩，未省何曹著此身。","遥想莲花门外路，几时湘水共行春。"]},{"t":"早出过御沟","f":"七言绝句","c":["残月欲落日未生，树根交合清水明。","翠华迢迢沙碛杳，铜驼陌上马声少。"]},{"t":"唐人两马图","f":"七言绝句","c":["玉山刍秣渭川波，振刷骁腾意气多。","政好骈趋驾黄屋，临危踶齧奈君何。"]},{"t":"少陵春游图","f":"七言绝句","c":["山崦楼台花树枝，杜陵韦曲恣遨嬉。","画图省识春风面，应是开元未乱时。"]},{"t":"张仲容七夕来徵诗就次韵以答","f":"七言绝句","c":["钿合红蛛缀网丝，玉儿瓜果设香帷。","从来天上张公子，解试梧桐一叶诗。"]},{"t":"闻蝉","f":"七言绝句","c":["昨日流莺今日蝉，无端世故苦相煎。","长安多少封侯骨，雨打风吹过少年。"]},{"t":"龚秀才还临江（二首） 其一","f":"七言绝句","c":["江上春波烟雾昏，江南游子怨销魂。","五侯池馆歌钟沸，争信麻衣忆故园。"]},{"t":"龚秀才还临江（二首） 其二","f":"七言绝句","c":["烟霞锢疾是谁医，来到都门几许时。","莫待蜀禽啼血叫，薜萝猿鸟怨归期。"]},{"t":"送成都何岩亮二首（由提学云南乘传过家为父庆八十寿） 其一","f":"七言绝句","c":["云顶嵯峨蛇阵长，锦江春日淡无光。","老翁白发升平世，閒倚东风看海棠。"]},{"t":"送成都何岩亮二首（由提学云南乘传过家为父庆八十寿） 其二","f":"七言绝句","c":["树迷云栈路间关，诗礼庭闱梦寐还。","五色衣裳千岁酒，马蹄仍度点苍山。"]},{"t":"省郎王景星僦居钟楼之东颇有幽趣遂号市庄主人（二首） 其一","f":"七言绝句","c":["樊川别业辋川庄，摩诘才情小杜狂。","闻说当年多胜事，却怜官职苦相妨。"]},{"t":"省郎王景星僦居钟楼之东颇有幽趣遂号市庄主人（二首） 其二","f":"七言绝句","c":["佳树名花总是春，画帘遥隔软红尘。","池台政赖閒妆点，惟欠林边学吠人。"]},{"t":"看云楼","f":"七言绝句","c":["昨日笙歌今日尘，交情反覆世情新。","山中态度能多少，辛苦长安陌上人。"]},{"t":"听雨楼（陈存翁）","f":"七言绝句","c":["侵窗度竹复临池，绝胜潇湘夜半时。","客邸十年听不足，可能今日重题诗。"]},{"t":"夜下新安驿奇家（馆伴安南国使还鄂）","f":"七言绝句","c":["河流如箭棹如飞，星汉垂光月渐西。","回首曲廊微步处，文明门上夜乌啼。"]},{"t":"晚泊维扬驿（二首） 其一","f":"七言绝句","c":["驿墙红树晚萧萧，解劝征人驻画桡。","拟办青楼狂载酒，月明何处玉人箫。"]},{"t":"晚泊维扬驿（二首） 其二","f":"七言绝句","c":["朱轩翠馆郁岧峣，几处笙歌几处桥。","怪得隔江人望见，夜深灯火似元宵。"]},{"t":"江上棹歌五首（采石舟中作以相长年三老且以慰使云） 其一","f":"七言绝句","c":["日南使人朝贡来，东观校书远送回。","长江无波风伯喜，不须铜钲苦相催。"]},{"t":"江上棹歌五首（采石舟中作以相长年三老且以慰使云） 其二","f":"七言绝句","c":["江边日出便解舟，轻帆经过烈山头。","我侬一日还到驿，你侬何日到邕州。"]},{"t":"江上棹歌五首（采石舟中作以相长年三老且以慰使云） 其三","f":"七言绝句","c":["远人莫愁行路难，故乡万里应须还。","明朝得风到池口，回首不见蛾眉山。"]},{"t":"江上棹歌五首（采石舟中作以相长年三老且以慰使云） 其四","f":"七言绝句","c":["象奴晚泊卖象梳，金钱卖得相欢呼。","大信有肉采石酒，何不多买犒棹夫。"]},{"t":"江上棹歌五首（采石舟中作以相长年三老且以慰使云） 其五","f":"七言绝句","c":["荻花萧萧江月明，十舟齐发棹歌声。","但有五两好风信，莫为离别动乡情。"]},{"t":"寄张仲容（四首） 其一","f":"七言绝句","c":["縠窗昨日君辞妇，白驹今朝我别家。","马御仆夫都见惯，莫教闺梦到天涯。"]},{"t":"寄张仲容（四首） 其二","f":"七言绝句","c":["城南城北渺风烟，一度论文月再圆。","肠断而今更愁绝，蓬莱云隔楚江天。"]},{"t":"寄张仲容（四首） 其三","f":"七言绝句","c":["风流多病汉文园，玉树森森瘦可怜。","梦里若逢徐福问，仙家何药得长年。"]},{"t":"寄张仲容（四首） 其四","f":"七言绝句","c":["有情谁解不相思，罗幌风乾叶落时。","莫问离愁有多少，君归犹趁菊花期。"]},{"t":"书汉津驿（九月十二日）","f":"七言绝句","c":["凉月满庭清似水，匡床无寐苦难胜。","闺人不见羁人况，落叶横窗蛾扑灯。"]},{"t":"甄氏坟园春露亭（二首） 其一","f":"七言绝句","c":["白杨如柱草如茵，湛玉零珠苦怆神。","况是清明风雨恶，可能无泪湿衣巾。"]},{"t":"甄氏坟园春露亭（二首） 其二","f":"七言绝句","c":["轩楹错粲对泉宫，菽水庭闱在眼中。","别有孤丘漆灯灭，宁馨何处哭秋风。"]},{"t":"鄱阳萧性渊能鼓琴琴号霜钟是其曾大父宋南渡时所畜者其家上世善琴云（二首） 其一","f":"七言绝句","c":["池台肠断雍门周，艮岳繁华逐水流。","往事寥寥君不见，金仙垂泣渭城秋。"]},{"t":"鄱阳萧性渊能鼓琴琴号霜钟是其曾大父宋南渡时所畜者其家上世善琴云（二首） 其二","f":"七言绝句","c":["不似琵琶不似筝，鲸音历历似秋清。","龟年流落江潭外，谁识秦声与楚声。"]},{"t":"柯敬仲持其乃尊山斋翁遗训诗求跋","f":"七言绝句","c":["太傅当年自教儿，唾壶谈麈亦吾师。","蓼莪流落玄扃下，不见音容只见诗。"]},{"t":"徐氏致爽斋图（取拄笏西山之义）","f":"七言绝句","c":["阴霾荡尽晓无霞，秋气萧森山气佳。","万户千门城阙里，不知空翠落谁家。"]},{"t":"送章生还江陵（三首） 其一","f":"七言绝句","c":["六尺身躯二十强，长安索米日仓皇。","多应梦里还家乐，菜市街头春酒香。"]},{"t":"送章生还江陵（三首） 其二","f":"七言绝句","c":["荆门驿路草萋萋，郢树连云晓色迷。","因忆儿时赏心处，女贞杨柳夹濠堤。"]},{"t":"送章生还江陵（三首） 其三","f":"七言绝句","c":["南国相知音信疏，暮云春树渺愁予。","东风解办含情句，代作长江双鲤鱼。"]},{"t":"秋江小景","f":"七言绝句","c":["霜落吴江息暮涛，荻芦花叶冷萧骚。","山林真隐今谁在，画里渔舟亦自高。"]},{"t":"赵集贤致政（二首） 其一","f":"七言绝句","c":["集贤学士鬓双皤，少日轩车意气多。","有口惟称老聃语，向人不晓缺壶歌。"]},{"t":"赵集贤致政（二首） 其二","f":"七言绝句","c":["酒满清尊花满丛，高年乐事政无穷。","近来好语君休报，惊动林间矍铄翁。"]},{"t":"送同年王在中编修代祀西行（六首） 其一","f":"七言绝句","c":["宫云拥节下青冥，巨岳通川草木荣。","传语祠官休秘祝，汉王深意在苍生。"]},{"t":"送同年王在中编修代祀西行（六首） 其二","f":"曲","c":["银盝天香出帝都，春衣綷粲马连?。","城南关吏争来认，曾向当年见弃繻。"]},{"t":"送同年王在中编修代祀西行（六首） 其三","f":"七言绝句","c":["联镳席帽杏园春，五见宫花照路尘。","今日分携重惆怅，顺承门外草如茵。"]},{"t":"送同年王在中编修代祀西行（六首） 其四","f":"七言绝句","c":["娇儿文褓语初莺，内子閒闺数驿程。","自是曲江春酒重，不堪芳樾听鹃声。"]},{"t":"送同年王在中编修代祀西行（六首） 其五","f":"七言绝句","c":["同年折桂复同官，同巷衡门指顾间。","纵是薄情诗兴涩，可能无句到阳关。"]},{"t":"送同年王在中编修代祀西行（六首） 其六","f":"七言绝句","c":["蜀山秦树碧相连，鸟道花开三月天。","马上从来诗句好，定应多费薛涛笺。"]},{"t":"街柳为暴风所折谩赋绝句","f":"七言绝句","c":["妆点官街能几春，经行常羡绿阴匀。","邻翁只怪南风恶，不道年来蠹满身。"]},{"t":"城南小雨","f":"七言绝句","c":["官街杨柳绿参差，花外危亭俯路岐。","物色宜人总依旧，天阴不似去年时。"]},{"t":"送曹义省亲新淦","f":"七言绝句","c":["亲在江南子在都，担簦戏綵事难俱。","宁馨学业今如此，郎罢还教食肉无。"]},{"t":"詹事府承宣使方君恕还岳阳（四首） 其一","f":"七言绝句","c":["银榜宫前近识君，当时悔不早知闻。","相逢未尽忘形话，又逐燕鸿度冥云。"]},{"t":"詹事府承宣使方君恕还岳阳（四首） 其二","f":"七言绝句","c":["古来词客不胜愁，感慨悲歌谩白头。","君若到家无事日，等閒莫上岳阳楼。"]},{"t":"詹事府承宣使方君恕还岳阳（四首） 其三","f":"七言绝句","c":["腊酒浓斟白玉卮，寒梅香缀碧苔枝。","知君不作京华梦，睡到山城日出时。"]},{"t":"詹事府承宣使方君恕还岳阳（四首） 其四","f":"七言绝句","c":["江南才子总知名，久别烦君为寄声。","说道头颅将四十，髭须先白两三茎。"]},{"t":"送李文清之官八番宣慰司幕府（三首） 其一","f":"七言绝句","c":["马谙旧路不崎岖，草色新袍是故吾。","山鸟山花总相识，莫将诗句咏娵隅。"]},{"t":"送李文清之官八番宣慰司幕府（三首） 其二","f":"七言绝句","c":["西南边徼渺烟霞，星土列疆道正赊。","羁思宦情应等尔，锦城虽乐不如家。"]},{"t":"送李文清之官八番宣慰司幕府（三首） 其三","f":"七言绝句","c":["武昌门外柳如丝，曾见吴侬笑咏时。","张绪而今渐憔悴，定应不似昔年枝。"]},{"t":"送谢德润还澧州（二首） 其一","f":"七言绝句","c":["通济桥头杨柳枝，涔阳极浦漾金丝。","惊见昔年题柱客，归来白发照涟漪。"]},{"t":"送谢德润还澧州（二首） 其二","f":"七言绝句","c":["征鞍远过孙王渡，稚子迎门喜气多。","烟水云山一杯酒，拂衣归去兴如何。"]},{"t":"春云出岫图","f":"七言绝句","c":["石根腾起气如饙，擘絮成衣布置匀。","态度不须空蔼蔼，东皋愁杀耦耕人。"]},{"t":"大名于景初家屋梁燕巢偶坏以悬匏代之因堕雏其中燕竟不他适来往其家凡六年异而求诗（二首） 其一","f":"七言绝句","c":["春秋来去不相安，王谢恩深往复还。","盛事他年君看取，蛇衔明月雀衔环。"]},{"t":"大名于景初家屋梁燕巢偶坏以悬匏代之因堕雏其中燕竟不他适来往其家凡六年异而求诗（二首） 其二","f":"七言绝句","c":["暮宿悬匏昼出飞，笑他辛苦杏花泥。","邻家灶突多炎上，犹自双双得意栖。"]},{"t":"送张尚德还长沙（四首） 其一","f":"七言绝句","c":["闻君家住古长沙，吴楚川途万里赊。","九衢夏木皆尘土，归棹惟应看藕花。"]},{"t":"送张尚德还长沙（四首） 其二","f":"七言绝句","c":["江山风露夜凄清，散入心脾爽气生。","重来写作金声赋，莫向时人鸣不平。"]},{"t":"送张尚德还长沙（四首） 其三","f":"七言绝句","c":["枫林水驿旧留连，小小歌谣四五篇。","烦君说向沙鸥道，今日才情减昔年。"]},{"t":"送张尚德还长沙（四首） 其四","f":"七言绝句","c":["洞庭如海山如黛，畴昔扁舟数往还。","今日因君倍惆怅，功名无味钓槎閒。"]},{"t":"送刘克让归汴中三首（名天秩由河南乡贡中第竞以便养辞馆阁之职除济宁录事须次觐省） 其一","f":"七言绝句","c":["梁园词客卯金刀，五十人中赋手高。","却是邹枚有神授，他州解送敢争豪。"]},{"t":"送刘克让归汴中三首（名天秩由河南乡贡中第竞以便养辞馆阁之职除济宁录事须次觐省） 其二","f":"七言绝句","c":["苑墙霏雨拂春旌，兴圣宫前晓唱名。","闻道明经传奕叶，宁馨今日被恩荣。"]},{"t":"送刘克让归汴中三首（名天秩由河南乡贡中第竞以便养辞馆阁之职除济宁录事须次觐省） 其三","f":"七言绝句","c":["玉树瀛洲总列仙，徒劳州县亦堪怜。","趋庭不羡长安乐，还上河津画鹢船。"]},{"t":"送翰林编修赵宗吉秦蜀降香便道觐省（二首） 其一","f":"七言绝句","c":["九重端拱不时巡，宣室斋心礼百神。","奠璧沉牛唯遣使，东封西祀肯劳民。"]},{"t":"送翰林编修赵宗吉秦蜀降香便道觐省（二首） 其二","f":"七言绝句","c":["锦衣玉节照皇都，紫陌春风拂传车。","行役不须愁万里，过家能似汉相如。"]},{"t":"和省郎杜德常清明三绝兼柬王君实艺林 其一","f":"七言绝句","c":["开门景物苦无涯，柳拂青丝杏衬霞。","酝藉仙郎谁得似，官曹常对紫薇花。"]},{"t":"和省郎杜德常清明三绝兼柬王君实艺林 其二","f":"七言绝句","c":["春闺无事不闻鸡，睡起朝阳树影西。","尽道陌头寒食好，卖花声里有莺啼。"]},{"t":"和省郎杜德常清明三绝兼柬王君实艺林 其三","f":"七言绝句","c":["赤阑桥瞰花溪过，白板扉临柳岸开。","最好苑墙东畔路，可人何事不频来。"]},{"t":"送湖州李教授之官（二首） 其一","f":"七言绝句","c":["软红尘里换青衫，弹铗歌残策去骖。","不用临岐重惆怅，落花迎棹过江南。"]},{"t":"送湖州李教授之官（二首） 其二","f":"七言绝句","c":["笔翰超然松雪仙，丹青已矣霅溪笺。","高斋应有横经暇，品画临书亦自贤。"]},{"t":"群鱼龟蟹图","f":"七言绝句","c":["紫蟹玄龟素鬣鱼，悠扬作队出菰蒲。","吴中饿殍须南食，肠断腥风是画图。"]},{"t":"送新安王元成赴辽阳教官（二首） 其一","f":"七言绝句","c":["三月边城未见花，榆关尽处草连沙。","举头只见长安日，忘却江东是故家。"]},{"t":"送新安王元成赴辽阳教官（二首） 其二","f":"七言绝句","c":["闻道东人乐事并，舞姬酬锦曲酬绫。","广文别有诗书味，自分皋比冷似冰。"]},{"t":"揆初堂（关中某氏永感之后寿日避客之所）","f":"七言绝句","c":["二十年前具庆时，彩衣歌吹进琼卮。","而今亦有如渑酒，自顾微驱欲奉谁。"]},{"t":"尧民图","f":"七言绝句","c":["歌谣人物接康衢，和气氤氲溢八区。","日晷悠悠才过午，周人酒诰汉人酺。"]},{"t":"送王君实西台御史（十首） 其一","f":"七言绝句","c":["凤城雪霁收灯后，乌府风清奏牍馀。","道路行人传好语，艺文学士拜新除。"]},{"t":"送王君实西台御史（十首） 其二","f":"七言绝句","c":["折桂蟾宫近十年，品流第一冠群仙。","颂台藏室遨游遍，御史分司又占先。"]},{"t":"送王君实西台御史（十首） 其三","f":"七言绝句","c":["一代才华百事堪，祥麟威凤木楩楠。","愿携云阁修书笔，移向惠文冠后篸。"]},{"t":"送王君实西台御史（十首） 其四","f":"七言绝句","c":["樊川韦曲称閒情，卉木林泉画不成。","毕竟高明挂霄汉，终南峻岭渭流清。"]},{"t":"送王君实西台御史（十首） 其五","f":"七言绝句","c":["鲁郭原头才拜扫，双清亭上罢吟哦。","黄尘发轫关河路，奈此骚人标致何。"]},{"t":"送王君实西台御史（十首） 其六","f":"七言绝句","c":["十二官街踏雪泥，归来门巷晚凄迷。","故人忽报明朝去，横玉一声春日低。"]},{"t":"送王君实西台御史（十首） 其七","f":"七言绝句","c":["江东日暮碧云阴，前月缄书锦鲤沉。","渭北春天多绿树，又从何处觅乔林。"]},{"t":"送王君实西台御史（十首） 其八","f":"七言绝句","c":["同年分袂不通书，陇峤巴川星散居。","骢马经行能问讯，定应投刺不踌躇。"]},{"t":"送王君实西台御史（十首） 其九","f":"七言绝句","c":["生长何曾出帝城，马蹄一旦赴咸京。","子长游览文章健，张掖滇池在此行。"]},{"t":"送王君实西台御史（十首） 其十","f":"七言绝句","c":["芙蓉秋水锦生花，羲献风流是故家。","谁敢持缣叩厅阁，多应判牒走龙蛇。"]},{"t":"送王伯修内翰奉母之官南台御史（六首） 其一","f":"七言绝句","c":["冯驩时动剑歌声，忽听乘骢建业行。","侍御虽然曾识面，台端共说旧闻名。"]},{"t":"送王伯修内翰奉母之官南台御史（六首） 其二","f":"七言绝句","c":["今代銮坡匠手閒，故教持斧出江关。","多应湖海频移节，敢望君王早赐环。"]},{"t":"送王伯修内翰奉母之官南台御史（六首） 其三","f":"七言绝句","c":["九重天子恩如海，雷雨斯须遍八荒。","南土不寒多草木，却愁无地著秋霜。"]},{"t":"送王伯修内翰奉母之官南台御史（六首） 其四","f":"七言绝句","c":["无悰莫饮采石酒，有耳休听商女歌。","揽辔归来无一事，蒋山高处看烟萝。"]},{"t":"送王伯修内翰奉母之官南台御史（六首） 其五","f":"七言绝句","c":["漳河潞河水悠悠，夫君去上沙棠舟。","承颜无复别亲苦，分袂但增知己愁。"]},{"t":"送王伯修内翰奉母之官南台御史（六首） 其六","f":"七言绝句","c":["伯修思子马如飞，兼善携家棹且迟。","邂逅故人烦寄语，故人挥麈日评诗。"]},{"t":"渡济河马上初见近城诸山","f":"七言绝句","c":["华山高耸鹊山东，一带烟霏翠接空。","安石从来多雅兴，却如新妇闭车中。"]},{"t":"中秋与吕仲实清话忆溉之李内翰不见","f":"七言绝句","c":["大明湖上水涵天，月色偏宜李谪仙。","应笑吾曹杀风景，碧桐窗下对灯眠。"]},{"t":"和州孝子黄钺父病痈笃孝子醮愿减年以益父寿果再生十年","f":"七言绝句","c":["上帝高居虎豹关，尘寰蝼蚁敢相干。","宁馨别有延年术，一寸灵台九转丹。"]},{"t":"冬日杂诗（五首） 其一","f":"七言绝句","c":["暗尘驽马夕阳酣，冻路凌兢思不堪。","徥侣徒行知捷径，踏冰时过象坊南。"]},{"t":"冬日杂诗（五首） 其二","f":"七言绝句","c":["金水桥西沙路低，东来翠幰与桥齐。","不知夫婿何官职，后拥前驱过曲堤。"]},{"t":"冬日杂诗（五首） 其三","f":"七言绝句","c":["下床指直难结带，出户舌卷深入喉。","共羡将军能出猎，党家帐里不风流。"]},{"t":"冬日杂诗（五首） 其四","f":"七言绝句","c":["金阙银宫上帝居，绿章封事达云衢。","晓来官吏传相告，明日放生仍断屠。"]},{"t":"冬日杂诗（五首） 其五","f":"七言绝句","c":["扫除愁恨惟应酒，陶写襟灵仅有诗。","四十头颅只如此，可能心事及游丝。"]},{"t":"过海子观浴象","f":"曲","c":["四蹄如柱鼻垂云，踏碎春泥乱水纹。","鸂?鵁鶄好风景，一时惊散不成群。"]},{"t":"送赵伯常淮西宪副（六首） 其一","f":"七言绝句","c":["十年前是紫薇郎，伴我书声隔粉墙。","今日绣衣持斧去，冲冠毛发半秋霜。"]},{"t":"送赵伯常淮西宪副（六首） 其二","f":"七言绝句","c":["元龙湖海旧襟期，叔度汪洋万顷陂。","知君不作媕娿态，拟见澄清报盛时。"]},{"t":"送赵伯常淮西宪副（六首） 其三","f":"七言绝句","c":["天北天南赋远游，合肥城下理松楸。","多应梦见还家乐，无复眉攒去国愁。"]},{"t":"送赵伯常淮西宪副（六首） 其四","f":"七言绝句","c":["常日相陪散马蹄，官曹同事凤城西。","别来应忆太禧白，醉后仍须乌迭泥。"]},{"t":"送赵伯常淮西宪副（六首） 其五","f":"七言绝句","c":["明月清风赤壁矶，八公山色照涟漪。","轺车使者多清致，揽辔经行合有诗。"]},{"t":"送赵伯常淮西宪副（六首） 其六","f":"七言绝句","c":["春来几度送华辀，芳草多情柳亦愁。","不惜裁诗写离恨，道傍只恐鬼揶揄。"]},{"t":"河东郭从让友于堂","f":"七言绝句","c":["金昆玉季尽优游，学似椿津共白头。","总为隋家贤吏部，读书不问驾车牛。"]},{"t":"万户侯李通敏祠堂","f":"七言绝句","c":["猿臂将军金虎符，寻常气压万熊貙。","而今庙貌开生面，犹似辕门按湛卢。"]},{"t":"李文愿自号寓盘","f":"七言绝句","c":["茂树清泉乐意深，当年祇有一知音。","却怜千古河阳月，几照令人慕蔺心。"]},{"t":"送张克宁赴淮东宪掾","f":"七言绝句","c":["读律由来可致身，十年乌府气无伦。","明朝奉檄淮南去，多少芳年惜后尘。"]},{"t":"神凤琴（太原李公逊所藏唐雷恒制宋建隆重修）","f":"七言绝句","c":["绝响朝阳瑞世鸣，喧啾百鸟谩关情。","却凭千古丝桐在，传得岐山一样声。"]},{"t":"浴罢（九月七日平江作南使江浙之行）","f":"七言绝句","c":["黄华街市雨珊珊，磴滑桥危马足难。","催唤小胥供祝版，吴歈坊下振衣还。"]},{"t":"姑苏即事（二首） 其一","f":"七言绝句","c":["南北东西画舫通，卖鱼输稻不愁风。","邻人使北归来说，车马京尘十丈红。"]},{"t":"姑苏即事（二首） 其二","f":"七言绝句","c":["娃儿十五瘦腰肢，眼角红妆浅淡施。","闻道阿娘将典却，揭帘催唤买燕支。"]},{"t":"平望驿和王伯循芙蓉韵","f":"七言绝句","c":["都门暑雨别匆匆，尊酒论文久不重。","却忆篷莱云起处，如舟亭下看芙蓉。"]},{"t":"晓发皂林驿","f":"七言绝句","c":["万寿山前旭日鲜，琅玕无数映清涟。","吴儿笑我杀风景，马上驱驰不坐船。"]},{"t":"长安驿道中观芙蓉寄嘲伯循","f":"七言绝句","c":["玉溪桥畔淡朝霞，照景红妆泫露华。","说似分司才御史，水边花胜驿中花。"]},{"t":"一钱太守祠（刘宠）","f":"七言绝句","c":["山中父老感承宣，五马高情亦自贤。","一样青铜成肉好，后来多是捋须钱。"]},{"t":"上虞山行值雨马上口占","f":"七言绝句","c":["山腰云掩翠光微，远见云浓近见稀。","对景漫思高彦敬，怀人常忆米元晖。"]},{"t":"上虞山行晓霜","f":"七言绝句","c":["略彴凝霜晓不乾，竟无人迹白漫漫。","马蹄踏破铅华色，得似鸳鸯瓦上看。"]},{"t":"嵊县道中","f":"七言绝句","c":["一径蜿蜒万壑遮，良田美树衬烟霞。","明时不作秦人避，欲占膏腴别起家。"]},{"t":"过雁荡不见李五峰隐君","f":"七言绝句","c":["雁荡山高不可攀，松巢竹坞白云端。","题诗为报经行客，莫作寻常少室看。"]},{"t":"石溪驿候伯循不至","f":"七言绝句","c":["古来元白似金兰，谁道风标不可攀。","驿骑飞来问骢马，计程应是在铅山。"]},{"t":"深青早发比明至柳阳桥戏赋","f":"七言绝句","c":["槟榔嚼罢复含姜，月落松明马首香。","□□匆匆闻禁漏，宿酲初解对残妆。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其一","f":"七言绝句","c":["北城繁华拨不开，南城尽是废池台。","看花君子颇解事，不笑南城似冷灰。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其二","f":"七言绝句","c":["南城宦家有孤儿，华裾宝马日遨嬉。","群奴豪酗卖丘木，身在醉乡犹未知。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其三","f":"七言绝句","c":["柳村南路百泉涌，陷车踬马沮洳深。","茕茕一僧力负土，治道不成徒苦心。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其四","f":"七言绝句","c":["停骖惆怅圣安寺，旧时轮奂想翚飞。","前朝已落王承福，后堂空祀李宸妃。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其五","f":"七言绝句","c":["街头父老发垂肩，拄杖支颐话可怜。","粔籹不甜寒具小，风光那似十年前。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其六","f":"七言绝句","c":["贵人池沼多鱼鳖，好佛经年不杀生。","恶少家奴苦相负，时时钩擉恣煎烹。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其七","f":"七言绝句","c":["故都空有废残城，天历人家学避兵。","今日街衢却依旧，栅门全毁堑填平。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其八","f":"七言绝句","c":["晓携儿侄拜先垄，常恐重来径路迷。","马上举鞭频指示，石碑东畔绿杨西。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其九","f":"七言绝句","c":["杨柳萧条花树稀，风光毕竟属春时。","更过几日来相赏，杜宇声催绿满枝。"]},{"t":"寒食拜扫盘桓南城亲友家书所闻见俚歌十首 其十","f":"七言绝句","c":["醉人驰骤紫叱拨，游女摇曳双秋千。","争笑书生常蹙頞，不关名利谩华颠。"]},{"t":"四月晦日早自石桥北度安济桥入史局马上口号","f":"七言绝句","c":["街树葱茏晓雨收，官河相近御沟流。","帝城不是多尘土，直住诗人到白头。"]},{"t":"台州韩诚之入京赴调教授松江及归取道彰德展省宋丞相魏公之墓绝句三首送之 其一","f":"七言绝句","c":["巾子峰前□岁盟，观光未久去王城。","匆匆又省安阳墓，不负西风万里行。"]},{"t":"台州韩诚之入京赴调教授松江及归取道彰德展省宋丞相魏公之墓绝句三首送之 其二","f":"七言绝句","c":["前朝谱牒自流传，陵谷那知有变迁。","昼锦英灵俨千古，多应能喜后人贤。"]},{"t":"台州韩诚之入京赴调教授松江及归取道彰德展省宋丞相魏公之墓绝句三首送之 其三","f":"七言绝句","c":["金窠大印押班联，剑履缤纷落九天。","餐尽万羊成馁鬼，楸梧何处认曾玄。"]},{"t":"揭曼硕小仆邹福颇能作诗诸名胜皆有所赠","f":"七言绝句","c":["福也事人甚不切，学诗习字欲自别。","不似南邻守舍儿，轻裘肥马通关节。"]},{"t":"送李从善之湖南医官","f":"七言绝句","c":["衡岭云开去路长，名山芝术气芬芳。","多因采得逢仙子，乞与延年第一方。"]},{"t":"舞阳刘元亭风漪亭","f":"七言绝句","c":["南薰微度曲陂前，鸭绿粼粼出自然。","眼底文章人不识，却教容易入诗篇。"]},{"t":"调谢敬德麦敬存二主司口号（同为东平乡试考官）","f":"七言绝句","c":["半生跋涉每独往，今得两公皆俊才。","对榻联镳已经夕，如何绣口未曾开。"]},{"t":"嘲敬德口号","f":"七言绝句","c":["翰林十载擅才名，廷试南宫数与明。","今日东行倍惆怅，重来投牒赴南城。"]},{"t":"闰十二月二十七日喜雪四首（前二日平章彻里特穆尔窜南安） 其一","f":"七言绝句","c":["赵魏燕齐无麦苗，秋冬不雨煖尘飘。","王城一夜霏春雪，喜气氤氲疹气消。"]},{"t":"闰十二月二十七日喜雪四首（前二日平章彻里特穆尔窜南安） 其二","f":"七言绝句","c":["昨夜鸱鸮出凤池，同云如水际天垂。","谁知六出丰登瑞，不在黄扉燮理时。"]},{"t":"闰十二月二十七日喜雪四首（前二日平章彻里特穆尔窜南安） 其三","f":"七言绝句","c":["积祸丘山重莫蠲，君恩如海听南迁。","品流悬绝昌黎叟，一样蓝关马不前。"]},{"t":"闰十二月二十七日喜雪四首（前二日平章彻里特穆尔窜南安） 其四","f":"七言绝句","c":["姓名何事到金瓯，沧海横流浩莫收。","鹄立白袍三百个，有谁回首望崖州。"]},{"t":"雨中马上口号","f":"七言绝句","c":["十二官街底许宽，寻常尘土昼漫漫。","晚来一雨春多少，唯有垂杨最好看。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其一","f":"七言绝句","c":["翰林供奉三十强，前春曾是探花郎。","年来居京大不易，走向沙头觅去航。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其二","f":"七言绝句","c":["才情如水气如烟，寒露玉壶冰浸天。","北庭沙草渺何许，江南风月故依然。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其三","f":"七言绝句","c":["巷南巷北叹偪侧，楚山楚水去难留。","白玉堂深云雾杳，迟子还应八月秋。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其四","f":"七言绝句","c":["往时折得高枝桂，身在蓬莱无处寻。","今日论交便如故，百年诗酒百年心。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其五","f":"七言绝句","c":["携幼入室藉文褓，上堂拜母舞斑衣。","青绫被冷承明直，忆著餐钱应早归。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其六","f":"七言绝句","c":["妻儿含啼红腐粥，仆夫奈冻吉贝衣。","到家同作端午节，角黍如玉江鱼肥。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其七","f":"七言绝句","c":["京华尘土浩漫漫，精神百倍是南还。","杨柳风前梳黑发，荷花池上洗朱颜。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其八","f":"七言绝句","c":["小季读书饱笼饼，同人对榻戏樗蒲。","君过扬州应北望，相思魂梦绕川途。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其九","f":"七言绝句","c":["昨朝直院舟先发，供奉今晨又趣装。","广陌无人留去骑，前途有幸及归航。"]},{"t":"送翰林应奉寿同海涯挈家觐省十首（供奉字弘毅至顺四年进士第二名辉和尔人自号清冰玉壶登第时寓居蓬莱真境） 其十","f":"七言绝句","c":["一日不见如三秋，乃今送君作远游。","我侬犹索长安米，你侬指日到蕲州。"]},{"t":"夜归即事","f":"七言绝句","c":["九衢尘土夜模糊，款段无臕不任驱。","闻是鸣驺忙避路，谁知恶少诈传呼。"]},{"t":"赠长安孝义张周卿三首（世昌） 其一","f":"七言绝句","c":["堂上家公白发垂，随阳鸿雁各分飞。","当时独有娱亲志，不羡朝衣羡彩衣。"]},{"t":"赠长安孝义张周卿三首（世昌） 其二","f":"七言绝句","c":["几多豪杰出长安，散尽黄金救急难。","得似夫君有阳报，白头强健子能官。"]},{"t":"赠长安孝义张周卿三首（世昌） 其三","f":"七言绝句","c":["曾同尊酒话蝉联，君世西秦我世燕。","慷慨固当歌义侠，流风传过二千年。"]},{"t":"无题","f":"七言绝句","c":["秋千架底过清明，贵婿除官促远行。","收拾春衣单骑去，落花风里暮砧鸣。"]},{"t":"三原张氏茔望松亭（张克礼）","f":"七言绝句","c":["已闻翠柏凝苦泪，更道白杨多悲风。","时时见此霜雪干，终身哀思何时穷。"]},{"t":"唐人两马图","f":"七言绝句","c":["出洗当年满渭川，四十万疋粲云烟。","画图只见风蹄八，孤负河东晋问篇。"]},{"t":"山水横披","f":"七言绝句","c":["渔翁袖手空舣棹，琴客攒眉欲绝弦。","惟有群僧无俗恨，乱山孤寺静谈禅。"]},{"t":"江浙省段照磨吉甫于予为同年友至顺癸酉会于吴门今春书来寄近诗十馀首遂和其次韵张伯雨新居四绝句以答时同年吕仲实佥浙西宪并以柬之 其一","f":"七言绝句","c":["流水阊门画舸横，姑苏台上暮云平。","五年一觉吴宫梦，珍重归鸿肯寄声。"]},{"t":"江浙省段照磨吉甫于予为同年友至顺癸酉会于吴门今春书来寄近诗十馀首遂和其次韵张伯雨新居四绝句以答时同年吕仲实佥浙西宪并以柬之 其二","f":"七言绝句","c":["越水吴山未了青，越调吴歈尽可听。","自恨昔年骑马过，钱唐佳处不曾停。"]},{"t":"江浙省段照磨吉甫于予为同年友至顺癸酉会于吴门今春书来寄近诗十馀首遂和其次韵张伯雨新居四绝句以答时同年吕仲实佥浙西宪并以柬之 其三","f":"七言绝句","c":["寻芳缓步玉津园，掷果闻呼石洞猿。","更说公馀多乐事，酒船撑过涌金门。"]},{"t":"江浙省段照磨吉甫于予为同年友至顺癸酉会于吴门今春书来寄近诗十馀首遂和其次韵张伯雨新居四绝句以答时同年吕仲实佥浙西宪并以柬之 其四","f":"七言绝句","c":["葛岭跻扳屐齿苔，旧游山鸟不相猜。","绣衣使者虽同调，不许联镳共往来。"]},{"t":"又次韵述怀见答 其一","f":"七言绝句","c":["搏桑日出事纵横，浊酒能浇磊块平。","占籍神州将百岁，晚风空送杜鹃声。"]},{"t":"又次韵述怀见答 其二","f":"七言绝句","c":["居庸一带雨馀青，历鹿车声久厌听。","梦到江南旧游处，钓鱼矶畔柳风停。"]},{"t":"又次韵述怀见答 其三","f":"七言绝句","c":["菟裘无地可田园，犹是栖栖择木猿。","昨夜洛阳风雪甚，袁安依旧卧衡门。"]},{"t":"又次韵述怀见答 其四","f":"七言绝句","c":["虚庭罗雀砌生苔，紫燕穿帘似见猜。","开尽碧桃凝伫久，麻姑书信几时来。"]},{"t":"王君冕尝于长安城东出南头第一门之北凿牖穴号归云洞二首（门即青门庙记又名青绮门） 其一","f":"七言绝句","c":["青绮门边有穴居，窈无窗户与阶除。","暂时收住为霖气，不逐狂风谩卷舒。"]},{"t":"王君冕尝于长安城东出南头第一门之北凿牖穴号归云洞二首（门即青门庙记又名青绮门） 其二","f":"七言绝句","c":["苍狗白衣多变幻，土屋深沉藏不散。","神龙有时飞汗漫，犹可相从雨霄汉。"]},{"t":"抚州李氏种桃亭","f":"七言绝句","c":["瑶池阿母杳无踪，结实开花怅望中。","何似君家亭子上，一年一度看春风。"]},{"t":"赠辛瑞卿（名居祯尝质物于某氏私库误赎得玉带金器不受而返之时人义其事）","f":"七言绝句","c":["之子轻财能好义，事如行道不拾遗。","试从人物观此世，有似开元贞观时。"]},{"t":"夏日家食偶成","f":"七言绝句","c":["晓日荒荒帘影低，炊烟浮动孟光衣。","苍蝇大是无知物，苜蓿盘边亦乱飞。"]},{"t":"顺州会曹元宾尚书贻诗二绝因和其韵（巡历京畿东道） 其一","f":"七言绝句","c":["三十昂藏试省闱，回思金榜挂名时。","府公幸遇张京兆，到处逢人说项斯。"]},{"t":"顺州会曹元宾尚书贻诗二绝因和其韵（巡历京畿东道） 其二","f":"七言绝句","c":["王事那能计苦寒，客窗灯火夜阑珊。","谁人解得尚书乐，不戴朝冠戴道冠。"]},{"t":"十二月十五日香河偶成","f":"七言绝句","c":["朔风初定晓霜晴，独坐寒厅日转盈。","怪得无人来诉讼，羽林猎骑尽还营。"]},{"t":"檀州之平谷道中口号（赈饥东道）","f":"七言绝句","c":["村垣儿女可怜生，满髻花枝弄晚晴。","放下秋千争见笑，雨中骑马过清明。"]},{"t":"丰润县赈饥答武孝隆文学","f":"七言绝句","c":["唐坊霖雨怨八座，汉庭灾异免三公。","古人争解言调燮，不识春郊发廪功。"]},{"t":"武清县斋遣兴","f":"七言绝句","c":["想像规模临晋帖，搜求章句记唐诗。","绿尊且喜无群饮，缃帙安能许自随。"]},{"t":"三月晦日偶成","f":"七言绝句","c":["十里平原晚色低，粉飘红坠绿凄迷。","客中无限伤春句，却为乘骢不敢题。"]},{"t":"病后自嘲","f":"七言古诗","c":["谁使儒冠易豸冠，寸心万虑死灰寒。","九衢随例乘骢马，□□□□□□□。"]},{"t":"灊山县廨和赵伯常宪副韵","f":"七言绝句","c":["霜气澄清日色明，诗情横逐晓霞生。","前驱负弩休驰骤，自有云山管送迎。"]},{"t":"武安堰秦氏山庄留题（录囚襄阳）","f":"七言绝句","c":["清溪如玉竹如屏，门掩苔墙犬不惊。","怪得轺车尝小驻，林间时有读书声。"]},{"t":"赠玉泉寺僧天云","f":"七言绝句","c":["吴山锡杖楚山云，云染袈裟诣县门。","莫怪褰帷不相见，禅机深处付忘言。"]},{"t":"对月和谷城县尹杨文载壁间韵","f":"七言绝句","c":["凉月娟娟照满怀，流光如水共徘徊。","持杯对影非吾事，但许帘栊彻夜开。"]},{"t":"夜起","f":"七言绝句","c":["揽衣开户纳微凉，西北遥山掣电光。","但愿天瓢膏禾黍，莫愁溪水没津梁。"]},{"t":"自谷城将往山中","f":"曲","c":["路入均房千里馀，人传山径大崎岖。","?崃叱驭真男子，何必屏间看地图。"]},{"t":"山行值雨","f":"七言绝句","c":["山雨随云往返飞，行时沾湿避时稀。","须臾驰过前冈去，满马斜阳就晒衣。"]},{"t":"过均州界山宿道院","f":"七言绝句","c":["楚邮燕驿饱经过，尘土风涛败兴多。","涧水绕阶云绕屋，可人今夜好行窝。"]},{"t":"竹山山中太皇观小憩道士白刘伯温御史旧所题二绝句即景和寄 其一","f":"七言绝句","c":["雨汗淋漓鬓发苍，空山无地得苍凉。","乔松老鹤聊容与，转觉仙家气味长。"]},{"t":"竹山山中太皇观小憩道士白刘伯温御史旧所题二绝句即景和寄 其二","f":"七言绝句","c":["酒泉才子气凌云，落落清谈久不闻。","见说松厅深处坐，简霜挥洒净妖氛。"]},{"t":"刘阮入天台图","f":"七言绝句","c":["谁知物外一山川，缥缈楼台小有天。","不向溪头遇仙子，桃花流水亦悠然。"]},{"t":"秋江独钓图","f":"七言绝句","c":["林间二客形骸俗，江上扁舟波浪愁。","万里乾坤少知己，一竿风月自优游。"]},{"t":"沙市道中二首 其一","f":"七言绝句","c":["十里沙津绿树凉，长红小白粲林塘。","今年分外春光久，四月幽花夹道香。"]},{"t":"沙市道中二首 其二","f":"七言绝句","c":["紫椹累累桑柘浓，野人生计尽从容。","林间自有催蚕鸟，不用乘驺苦劝农。"]},{"t":"谢德润号月海（二首） 其一","f":"七言绝句","c":["三山宫阙湛无尘，万古青天白玉轮。","身世清高能尔许，当年惟有泛槎人。"]},{"t":"谢德润号月海（二首） 其二","f":"七言绝句","c":["坡仙畴昔赋赤壁，万顷秋江一苇游。","更向东溟观月色，当时襟度复谁俦。"]},{"t":"寄京师诸公（四首） 其一","f":"七言绝句","c":["华颠戚戚苦无悰，愁绝湘南六一翁。","采得宜男仍谒告，未应空学顾非熊。"]},{"t":"寄京师诸公（四首） 其二","f":"七言绝句","c":["白玉堂前一老仙，能文善饮量如川。","官高犹说清贫甚，乞与田租作酒钱。"]},{"t":"寄京师诸公（四首） 其三","f":"七言绝句","c":["渚宫春好酒如川，引领巴江眼欲穿。","却笑词人杀风景，瞿塘不敢泛楼船。"]},{"t":"寄京师诸公（四首） 其四","f":"七言绝句","c":["月露星河共一天，无由缩地谩悽然。","金闺莫羡江湖趣，曾溷京尘二十年。"]},{"t":"次韵王伯循御史","f":"七言绝句","c":["汉江如练画船开，负弩前驱照岸隈。","却是沙鸥解相识，綵衣人著绣衣来。"]},{"t":"宿牛首市陆叟所居二首（再录囚襄阳） 其一","f":"七言绝句","c":["窗户斜临雁汊洲，墨云金电晚风飕。","西城不用随车雨，酝酿新凉学立秋。"]},{"t":"宿牛首市陆叟所居二首（再录囚襄阳） 其二","f":"七言绝句","c":["尘染綀衣雨汗流，停骖借得半窗秋。","自怜不及居停主，坐看青山到白头。"]},{"t":"谷城县斋留题（二首） 其一","f":"七言绝句","c":["城南筑水息波涛，城里青帘间树梢。","谁信琴堂太岑寂，承尘低处燕为巢。"]},{"t":"谷城县斋留题（二首） 其二","f":"七言绝句","c":["方沼移栽菡萏茄，曲台培植牡丹芽。","小山丛桂多清致，不用河阳一县花。"]},{"t":"舟下汉皋渡","f":"七言绝句","c":["朝辞光化水无泷，搥鼓扬旌下汉江。","何事舟人混南北，棹歌不似竹枝腔。"]},{"t":"复回至利阳道中","f":"七言绝句","c":["愁见群峰云气阴，泥涂溽暑苦难任。","逢人莫问何时雨，陌上蹄涔尺许深。"]},{"t":"宜都朝京亭四首（按部峡州） 其一","f":"七言绝句","c":["烟霭空濛江上山，晴时不及雨时看。","沙鸥笑杀亭前客，有底忙时不倚阑。"]},{"t":"宜都朝京亭四首（按部峡州） 其二","f":"七言绝句","c":["清江水合浊江流，闻说瀰漫燕尾洲。","想像秋风秋月下，登临不减岳阳楼。"]},{"t":"宜都朝京亭四首（按部峡州） 其三","f":"七言绝句","c":["远近峰峦浓淡姿，微茫洲渚画图披。","新诗似与江山约，恰值幽人兴到时。"]},{"t":"宜都朝京亭四首（按部峡州） 其四","f":"七言绝句","c":["九华山耸此山低，一样澄清映翠微。","千载神交谁会得，临风说向谢玄晖。"]},{"t":"题民安驿","f":"七言绝句","c":["枯芦断岸年年雪，古木颓垣夜夜风。","自是江山入图画，可堪华发道途中。"]},{"t":"津市留题","f":"七言绝句","c":["烟霏空翠瞰芳洲，杨柳依稀古渡头。","斜日扬鞭倦行役，自惭不及贾胡留。"]},{"t":"山南宪副拜珠太古四友亭（二首） 其一","f":"七言绝句","c":["三友翛然奈岁寒，使君雅趣共盘桓。","京尘扰扰春游客，不满高人一笑看。"]},{"t":"山南宪副拜珠太古四友亭（二首） 其二","f":"七言绝句","c":["窗外梅花照雪晴，江城松竹更青青。","宦游难学宜春槛，好向行窝别筑亭。"]},{"t":"赠相士西湖","f":"七言绝句","c":["淡妆浓抺固相宜，风月才情酒共诗。","欲把芰荷都折尽，只将清泚照须眉。"]},{"t":"赠相士小山","f":"七言绝句","c":["桂树丛生猿鹤幽，薜萝烟月閟清愁。","白云何处吟招隐，我欲因君作少留。"]},{"t":"赠僧别传 其一","f":"七言绝句","c":["雁行零落禅床寂，回首人间二十年。","曾见缁衣立函丈，不堪抚卷重悽然。"]},{"t":"赠僧别传 其二","f":"七言绝句","c":["越中海影接山光，更著招提著色妆。","珍重道人多雅致，尽收清气入诗囊。"]},{"t":"赠僧别传 其三","f":"七言绝句","c":["吴越经过我亦曾，溪流夜泛岭晨登。","仙岩佛洞遨游遍，却愧不如行脚僧。"]},{"t":"淮东县属朱子静乃祖所得松雪困学二帖","f":"七言绝句","c":["两公墨妙贵莫比，一门祖孙世济美。","纷纷恶札请托猥，覆瓿无踪祇愧死。"]},{"t":"白子芳瓶梅结实 其一","f":"七言绝句","c":["蒙惠泉头岁暮时，相逢云已及瓜期。","捐金筑埭功难就，嬴得州民死后思。"]},{"t":"白子芳瓶梅结实 其二","f":"七言绝句","c":["诗书门第宁馨儿，梦寐音容守穗帷。","物外春风几千岁，瓶花常见子累累。"]},{"t":"墨梅（为李华远作）","f":"七言绝句","c":["风香月影雪肌肤，朔客晴窗看画图。","江北江南数千里，梦魂何处觅西湖。"]},{"t":"晨入太学即事口号","f":"七言绝句","c":["揽衣忙趁到斋钟，天际初阳照面红。","不是羸骖鞭不进，驼车一行截街东。"]},{"t":"胄监东厅口号","f":"七言绝句","c":["北窗桂影对晴空，帘幕虚明爽气通。","绿树正宜留永日，黄埃莫遣涨飘风。"]},{"t":"孙隐居春洲图（三首） 其一","f":"七言绝句","c":["河豚初贵荻芽生，洲上高人曳杖行。","谁识静中观物理，长空淡淡大江横。"]},{"t":"孙隐居春洲图（三首） 其二","f":"七言绝句","c":["幅巾野服楚江干，胸次云梦眼界宽。","久矣忘机对鸥鸟，不须遮日望长安。"]},{"t":"孙隐居春洲图（三首） 其三","f":"七言绝句","c":["杜若香中水没篙，沙平草软恣游遨。","江湖真隐今谁在，画里衣冠亦自高。"]},{"t":"赠谈三命碧峤","f":"七言绝句","c":["蓬莱方丈屹相通，掀举神鳌接太空。","人海不如云海阔，茫茫谁识李虚中。"]},{"t":"赠叶仲舆（名衡至大皇庆间尝从承旨姚文公游及与先兄正献公友善）","f":"七言绝句","c":["三月皇都偶遇君，袖携诗卷见情亲。","玉堂仙去难兄逝，流水残花亦怆神。"]},{"t":"送宣城罗教授赴攸州","f":"七言绝句","c":["吞凤文章老益奇，杏坛深处拥皋比。","湘南山水江东树，洗尽京尘总是诗。"]},{"t":"潘云谷献所制墨见天子于上京慈仁殿以诗赠之归江南","f":"七言绝句","c":["一寸龙江一寸金，布衣持进五云深。","文房自幸非常遇，惆怅长杨献赋心。"]},{"t":"六月三日寄吁（至正乙酉时在上京）","f":"七言绝句","c":["窗后红芳旭日明，堂前绿树晚风清。","白头竟被虚名误，梦见儿曹笑语声。"]},{"t":"赠吏部尚书罗罗士安","f":"七言绝句","c":["紫薇花底退朝迟，马上相逢共说诗。","几度访君多不见，北窗开彻晚荼蘼。"]},{"t":"诈马宴（上京作）","f":"七言绝句","c":["宝马珠衣乐事深，只宜晴景不宜阴。","西僧解禁连朝雨，清晓传宣趣赐金。"]},{"t":"寄南台治书廉公亮（公亮幼学于金陵登科后扬历省台尝为南台幕长今又拜是职作诗贺之）","f":"七言绝句","c":["五花骢马拥旌幢，霜气横秋肃楚江。","钟阜秦淮日来往，光辉应照旧书窗。"]},{"t":"天香第一亭三首（汪叔志先茔在泾县方壶村墓亭有古桂延祐间汪擢乙科遂名亭天香第一） 其一","f":"七言绝句","c":["松楸深拥若堂封，仙树婆娑八月风。","奕叶儿孙高处折，人间别有广寒宫。"]},{"t":"天香第一亭三首（汪叔志先茔在泾县方壶村墓亭有古桂延祐间汪擢乙科遂名亭天香第一） 其二","f":"七言绝句","c":["世传佳木姓名偕，召伯甘棠王氏槐。","记取汪坟苍桂树，文科应兆不相乖。"]},{"t":"天香第一亭三首（汪叔志先茔在泾县方壶村墓亭有古桂延祐间汪擢乙科遂名亭天香第一） 其三","f":"七言绝句","c":["天上飘香云外过，青冥风露挹仙柯。","文章自有流芳理，不用长安郭橐驼。"]},{"t":"月夜渡淮","f":"曲","c":["玉局翁赤壁岸，锦袍仙采石矶。","千古词人高致，一般秋月清辉。"]},{"t":"陈南仲幼失母寻至永丰逆旅得见","f":"曲","c":["及泉忍闻誓母，历郡乃见寻亲。","借问永丰逆旅，何如颖谷封人。"]},{"t":"送校官萧性渊赴上丰城山市巡徼官二首（和林学正能鼓琴琴号霜钟） 其一","f":"曲","c":["儒冠暂易武弁，漠北径去江南。","借问龙庭风雪，何如山市晴岚。"]},{"t":"送校官萧性渊赴上丰城山市巡徼官二首（和林学正能鼓琴琴号霜钟） 其二","f":"曲","c":["绝句曾闻李涉，悲笳常爱刘琨。","自鼓霜钟一操，群盗不怕櫜鞬。"]},{"t":"山行即事","f":"曲","c":["山云容易作雨，岩瀑取次成川。","石润犹开水硙，林霏仅有炊烟。"]},{"t":"调吴正传博士吴方为柳道传撰墓志","f":"曲","c":["词苑老臣遗世，成均故友知音。","陈寿何尝得米，刘乂且欲分金。"]},{"t":"江叔志司业堪老园（四首） 其一","f":"曲","c":["先生尽会婆娑，文苑故老无多。","去志任思泉石，归梦枉到松萝。"]},{"t":"江叔志司业堪老园（四首） 其二","f":"曲","c":["老子垂止足戒，将军存矍铄心。","南山有三径菊，东都无二疏金。"]},{"t":"江叔志司业堪老园（四首） 其三","f":"曲","c":["故园之乐何如，大胜金马石渠。","田头有秫酿酒，朝中无客通书。"]},{"t":"江叔志司业堪老园（四首） 其四","f":"曲","c":["老我菟裘何地，半世雨梗风萍。","后日拿舟相访，还须许作园丁。"]},{"t":"满庭芳 汴中寒食","f":"曲","c":["雨意愔愔，养花天气，卖饧何处春箫。","清明上巳，车马正连朝。","对酒唱、归时多忘，惜花心、醉后偏饶。","凝云暮，青楼帘捲，几度对魂销。","无聊空怅望，东阑雪剩，北郭香飘。","梦江南，行乐水远山遥。","深院宇、绿窗啼鸟，明寒食、宝月良宵。","秋千外，柳风柔小，无力著春娇。"]},{"t":"满庭芳 寒食伤先兄正献公","f":"曲","c":["魂黯云山，泪零风野，转头三度清明。","感今怀旧，何事不伤情。","文史共、梁园书几，枭卢对、湓浦灯檠。","经行处，洞庭彭蠡，同载赴瑶京。","才名人尽羡，朝家大宋，陆氏难兄。","但驽骀，小季少后鹏程。","丹桂树、何论高下，紫荆花、早变枯荣。","微衷苦，乱峰如树，幽恨几时平。"]},{"t":"穆护砂 烛泪","f":"曲","c":["底事兰心苦。","便凄然、泣下如雨。","倚金台独立，揾香无主，肠断封家相妒。","乱扑簌、骊珠愁有许。","向卜夜、铜盘倾注。","便不似、红冰缀颊，也湿透、仙人烟树。","罗绮筵前，海棠花下，淫淫尝怕凤脂枯。","比雒阳年少，江州司马，多少定谁如。","照破别离心绪。","学人生、有情酸楚。","想洞房佳会，而今寥落，谁能暗收玉箸。","算只有、金钗曾巧补。","轻湿尽、粉痕如故。","愁思减、舞腰纤细，清血尽、媚脸肤腴。","又恐娇羞，绛纱笼却，绿窗伴我检诗书。","更休教、邻壁偷窥，幽兰啼晓露。"]},{"t":"木兰花慢 题蛾眉亭","f":"曲","c":["唤山灵一问，螺子黛、是谁供。","画婉娈双蛾，蝉联八字，雨泪烟浓。","澄江婵娟玉镜，尽朝朝暮暮照娇容。","只为古今陈迹，几回愁损渠侬。","千年颦蹙谩情钟。","惨绿带云封。","忆赏月天仙，然犀老将，此恨难穷。","持杯与山为寿，便展开修翠恣疏慵。","要似绛仙妩媚，更须岚霭空濛。"]},{"t":"望海潮 海子岸暮归金城坊","f":"曲","c":["山含烟素，波明霞绮，西风太液池头。","马似游龙，车如流水，归人何暇夷犹。","丛薄拥金沟。","更萧萧宫树，调弄新秋。","千里烟波，几双鸥鹭两渔舟。","暮云楼阁深幽。","政砧杵丁东，弦管啁啾。","淡淡星河，荧荧灯火，一时清景难酬。","马上试冥搜。","填入耆卿谱，模写风流。","明日重来柳下，携酒教名讴。"]},{"t":"人月圆 中秋小酌","f":"曲","c":["红螺香滟金茎露，清兴溢璇霄。","玉盘光冷，云鬟雾湿，丹阙烟消。","此生此夜，明年明月，何似今宵。","西风唤我，瑶阶折桂，绮槛吹箫。"]},{"t":"人月圆 诚夫兄生子名京华儿","f":"曲","c":["神州佳丽明光锦，生出玉麒麟。","四筵都爱，西山眉翠，太液瞳人。","他年应是，斗鸡走马，紫陌红尘。","这回休更，燕秦树栗，江浦垂纶。"]},{"t":"菩萨蛮 送辽西宪孙椽还司延祐己未乐亭县作","f":"曲","c":["紫髯如戟霜台掾。","风生采笔来行县。","邂逅海天涯。","盍簪能几时。","柳梢春尚冷。","无物堪持赠。","为谢幕中莲。","殷勤寄短篇。"]},{"t":"菩萨蛮 丹阳道中","f":"曲","c":["西风落日丹阳道。","竹冈松阪相环抱。","何处最多情。","练湖秋水明。","驿城那惮远。","佳句初开卷。","寒雁任相呼。","羁愁一点无。"]},{"t":"菩萨蛮 卫州道中至元四年十月与巴尔斯布哈御史同行按行河南四道","f":"曲","c":["两岐流水清如酒。","草根风蹙冰皮皱。","雪净太行青。","联镳看画屏。","按行多雅致。","解起澄清志。","回首五云天。","东华尘似烟。"]},{"t":"菩萨蛮 偃师道中","f":"曲","c":["北邙古冢纷无数。","崔嵬罗列成山阜。","何处断碑横。","无人知姓名。","今坟如蚁垤。","回首成磨灭。","今古两堪哀。","停骖酹绿苔。"]},{"t":"春从天上来 寿张惟健五月十六日","f":"曲","c":["帝敕朱明。","拥丹穴仙雏，表瑞升平。","天上公子，齐岱精英。","玉树照映神京。","渺翩翩纨裤，有谁似、间气玄成。","妙才情，擅钟王笔意，韦杜诗声。","薰风黑头初度，笑时世纷纭，舞雪歌莺。","燕子帘栊，葵榴庭院，天壤至乐难名。","邈轩裳奕世，青云步、紫绶华缨。","八千龄。","看缁衣父子，赤舄公卿。"]},{"t":"春从天上来 至元六年庚辰元日立春将为山南佥宪按部至应城县作此词奉寄许可用大参陈景议宪副","f":"曲","c":["旭日暾暾。","烂春饼堆盘，寿酒盈尊。","玉帛交错，襟佩翩翻。","想像虎豹天门。","霭蓬莱云气，布淑景、渐遍乾坤。","黯销魂，杳洋洋韶濩，赳赳櫜鞬。","升平万方元会，念去国孤怀，盛事谁论。","黄阁儒臣，乌台旧客，曾是执法调元。","望蒲骚小邑，才咫尺、寂寞山村。","抚婵娟。","料梅边倾倒，回拜天恩。"]},{"t":"贺新凉 寿刘时中五月廿又八日","f":"曲","c":["绣陌经新雨。","致升平、五弦琴里，薰风吹户。","夏馆深沉晨容好，宝鼎红云香雾。","还又是、逋仙初度。","畴昔骖鸾骑赤凤，溯西清、佳致凌霄步。","天壤外，快豪举。","遨游又作湖山主。","百千回、笑谈诗酒，盘桓容与。","未信星星能侵鬓，青镜流年如许。","毕竟到、广寒天府。","多少文章真事业，鹤南飞、自愧无佳语。","弦宝瑟，劝霞醑。"]},{"t":"贺新凉 徐复初池亭听雨轩至治辛酉时予将之湖南","f":"曲","c":["银竹能宫羽。","向荷盘、跳珠腷膊，花奴羯鼓。","浏浏泠泠春泉泻，滴尽槽头香醑。","爱徽外、遗音太古。","暗度松筠时淅沥，恍吴娃、低枕传私语。","君试听，有佳趣。","主人未解离愁苦。","对凉秋、芭蕉巨叶，梧桐高树。","梦断罗裙天如漆，一寸乡心凄楚。","点点是、寂寥情绪。","明日孤舟成独往，更难堪、长夜潇湘浦。","凭曲槛，且容与。"]},{"t":"虞美人 寄寿周子善二月十一日","f":"曲","c":["暖风金鼎香醽醁。","想像人如玉。","天南地北两心期。","尔汝忘形如愿、定何时。","夫君政似章台柳。","寿相人稀有。","吟馀时复饮丹砂。","何必求仙远访、稚川家。"]},{"t":"虞美人 福州北还雨中观梅","f":"曲","c":["十年久共梅花别。","乍见殊佳绝。","腊前风景雨中天。","翠竹青松恰好、映清妍。","繁枝开遍香成阵。","触目忘离恨。","玉人谁使似冰肌。","酒罢歌阑一向、又相思。"]},{"t":"绿头鸭 送张仲容过维扬复之钱塘结婚正月二十日出京是其寿日也","f":"曲","c":["缓摇鞭，销魂桥上留连。","恰春波、鸭头新绿，仓皇便买吴船。","就华堂、溶溶寿酒，作绣陌、草草离筵。","倾盖论交，分襟怨别，春风秋月仅经年。","都门道、纷纷轻薄，馀子政堪怜。","夫君妙，心期湖海，意气云天。","便明朝、拂衣径去，天涯幽恨无边。","暮维舟、沙鸥飏雪，春市酒、淮柳垂烟。","绿水迢迢，青山隐隐，浙江云拥洞房仙。","对西湖、烟浓雨淡，少少占芳妍。","归来好，扶摇九万，水击三千。"]},{"t":"婆罗门引 江上晚泊望月","f":"曲","c":["短衣乌帽，京尘眯目强钻头。","梦中八表神游。","今日江山佳处，便欲贾胡留。","爱峰岚滴翠，天水涵秋。","断霞渐收。","见隐隐、两蛾愁。","好在九华烟树，秋浦沙鸥。","相看依旧，但憔悴、潘郎俗状羞。","孤负却、笑傲林丘。"]},{"t":"水调歌头 寄诚夫兄在江南作时兄在史馆校雠先朝实录","f":"曲","c":["登车就长路，晓日照皇州。","风吹紫荆花落，那更别离忧。","咫尺天南地北，想像云窗雾阁，人在古瀛洲。","粉笔校书罢，乌帽拂尘游。","出银台，心浩浩，思悠悠。","人间万事姑置，食邑素封侯。","收拾金銮遗事，记取玉壶清话，此外复何求。","勋业好看镜，绿鬓不禁秋。"]},{"t":"蝶恋花 青田舟中","f":"曲","c":["无数好山攒碧树。","山下邮亭，亭下牵舟路。","山色娱人相指顾。","时时又被滩声妒。","寒日光阴容易度。","云去云来，那更商量雨。","强把羁愁排遣去。","一尊酒尽青山暮。"]},{"t":"蝶恋花 河内王干臣号竹溪","f":"曲","c":["门外红尘溪上竹。","竹似琅玕，溪水清如玉。","溪上主人情不俗。","多应每食能无肉。","千载高标成倏忽。","六逸飘然，君为追遐躅。","莫向溪边閒濯足。","我知孺子歌难续。"]},{"t":"清平乐 武陵客含小酌与田父相对酬酢闻农师子嘉诸人方饮他所欢甚","f":"曲","c":["花台竹坞。","对雨罗樽俎。","邂逅田翁同笑语。","问讯村墟禾黍。","酒徒咫尺高阳。","粉营狎坐飞觞。","一种曲生风味，不知谁弱谁强。"]},{"t":"清平乐 车厩道中","f":"曲","c":["青松乌桕。","寒食来车厩。","满目山明仍水秀。","忍听玉骢驰骤。","红桥掩映山庄。","酒旂摇曳林塘。","好在莺湖春色，笑人不暇飞觞。"]},{"t":"如梦令 题杨补之施蓬墨梅卷中他诗有忍寒背蓬立之句","f":"曲","c":["常记剡溪前度。","坐拓船窗窥觑。","棹进任舟移，行尽粉香千树。","佳趣。","佳趣。","篷背诗人何处。"]},{"t":"浣溪沙 昆山州城西小寺晚憩","f":"七言古诗","c":["落日吴江驻画桡。","招提佳处暂逍遥。","海风吹面酒全消。","曲沼芙蓉秋的的，小山丛桂晚萧萧。","几时容我夜吹箫。"]},{"t":"浣溪沙 寿南阳周文卿八十","f":"七言古诗","c":["生长升平鹤发翁。","儿郎衣彩照方瞳。","晨昏甘旨凤城中。","缓步不须鸠杖策，酡颜时藉蚁杯烘。","懒将身世应非熊。"]},{"t":"浣溪沙 冬日喜晴","f":"七言古诗","c":["万瓦轻霜爱日明。","游丝来往似春晴。","幽禽弄暖百般声。","斑竹乍翻经夏箨，绿池犹泛过秋萍。","溪桥谁共探梅行。"]},{"t":"风流子 至元四年七月廿又二日苏伯修侍郎举一儿子以予同年久交且三子名梯云拿云步云者方成童就傅乃求仿吾儿制名遂命之曰乘云继徵词以纪笔赋此以赠儿已满弥月矣侍郎作汤饼会并书呈席上诸公","f":"曲","c":["绀宇瑞烟浮。","仙童小、高举觅真游。","霞绚九光，徘徊若木，日宣五色，照耀瀛洲。","人争睹、翱翔趋绛阙，夭矫上昆丘。","几度骖鸾，蛾眉东畔，有时跨凤，恒岳南头。","何事暂夷犹。","尽青冥远揽，碧落奇搜。","不数薰香妩媚，傅粉娇羞。","笑襁褓襜褕，人间羊祜，桑弧蓬矢，地上齐州。","剩费通家小字，衮衮公侯。"]},{"t":"行香子 京山道中","f":"曲","c":["竹院松庭，犬吠鸡鸣。","被田家、画出升平。","园林掩映，鞍马经行。","怅暮天低，寒日淡，晓风轻。","浮世浮名。","役使神形。","霎时间、鬓变星星。","不忧不惧，无辱无荣。","爱水边渔，林下隐，陇头耕。"]},{"t":"行香子 暮抵应城宿县斋后园","f":"曲","c":["槲叶风乾，桕叶霜殷。","浅坡坨路径回环。","喜投公馆，暂卸征鞍。","对竹萧森，松夭矫，菊斓斑。","岁晏天寒，谁共清欢，过黄昏愁恨多端。","烛花渐暗，炉火将残。","更雁声哀，砧声急，雨声繁。"]},{"t":"减字木兰花 宪掾黄君美弄璋援苏伯修侍郎例乞名其子命之曰升云时二月六日寿席醉赋","f":"曲","c":["春空霭霭。","儿解飞腾窥五彩。","我制佳名。","异姓他年叙弟兄。","我须白早。","亦愿儿年如我老。","缓步徐行。","终到蓬莱近上层。"]},{"t":"南乡子 观云","f":"曲","c":["绀碧峙晴空。","态度分明巧不同。","櫑具神君，三四辈乘龙。","冠佩翱翔赴紫宫。","楼观远玲珑。","舞凤蹲猊刻镂工。","一笑斜川，痴老子奇峰。","便入南窗诗句中。"]},{"t":"南乡子 二月廿又八日君美弄第二雏仍前例名之曰凌云赋此以赠","f":"曲","c":["头玉太硗硗。","江夏无双世胄遥。","好是三生仙骨重，丛霄。","曾侍元君绛节朝。","咫尺趁扶摇。","直上鹏程挹斗杓。","他日挥毫能作赋，飘飘。","学取成都驷马桥。"]},{"t":"南乡子 至元六年九月十四日李重山宪副寿日是日适台使赍玺书奖谕风宪至山南遂大宴合乐重山号梅庭主人所居官舍即旧木犀亭久扁香宇","f":"曲","c":["桂宇散秋香。","咫尺梅庭十月阳。","红叶黄花，风致好华堂。","不比寻常进寿觞。","褒诏灿龙光。","百丈苍官百丈霜。","信是天恩，宽似海徜徉。","就趁笙歌入醉乡。"]},{"t":"踏莎行 早春景陵道中兼旬阴雨","f":"曲","c":["野烧回青，溪梅褪粉。","路傍新柳鹅黄嫩。","连阴未放碧波明，峭寒尚阻东风信。","咿轧肩舆，飘萧蓬鬓。","病馀怀抱无风韵。","彩笺何暇写閒情，绿尊无分排孤闷。"]},{"t":"点绛唇 沔阳道中","f":"曲","c":["泽国春生，葑田青接重湖浅。","鸳凫弄暖。","得意烟波远。","阴遇元宵，晴望花朝转。","和风扇。","群芳开遍。","应过京山县。"]},{"t":"鹧鸪天 题应山县城内渡蚁桥桥东东数步法兴寺即二宋读书处","f":"曲","c":["十万元驹过雨堤。","一双丹凤上天池。","科名已向生前定，阴德仍从暗里窥。","龙虎榜，鹡鸰诗。","同胞同甲照当时。","同宗盛事嗟微异，后折蟾宫向下枝。"]},{"t":"摸鱼儿 至元六年二月望日登安陆白云楼楼今为分宪公廨城中有楚大夫宋玉故宅与池其井名琉璃井有兰台故基","f":"曲","c":["屹危阑、郢都西北，滔滔汉水南去。","兰台陈迹何从访，废宅芳池凝伫。","愁绝处。","空只有、琉璃眢井蛙声聚。","千年遗绪。","邈白雪宫商，雄风襟量，恍惚可神遇。","英灵在，应念诸孙卤莽。","斯文徼福如许。","蕙肴兰藉椒浆奠，屈景幽魂同赴。","惊节序。","却邂逅、春深不识悲秋苦。","抚今怀古。","谩醉墨淋漓，狂歌悽惋，和者应无数。"]},{"t":"西江月 王伯修赠别","f":"曲","c":["乌石驿中长夜，小金山下新年。","淮堧萧寺麦秋天。","十载三回相见。","今日汉南官舍，光阴不得留连。","何时文酒再团圆。","莫待白头皱面。"]},{"t":"次韵赋春词二首 其一","f":"七言绝句","c":["象口香销冷瑞烟，锦衾罗荐恋朝眠。","一心要续怀春梦，不管啼莺绕槛边。"]},{"t":"句","f":"七言古诗","c":["行人不敢来饮马，稚子时能坐钓鱼。"]}]};